const PY_SOURCES = {
 "core/__init__.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Cœur de calcul de la Visionneuse Panoramax, sans QGIS.\n\nTriangulation, points 3D, terrain, précision GPS, calages, inclinaison automatique, axe de\nla route, façades et mesures : du Python pur (numpy en option, pour l'inclinaison\nautomatique), utilisable par le plugin QGIS comme par l'application web web-measures\n(Pyodide). Ce qui dépend de l'application hôte (réseau, altitude NGF, décodage d'une photo,\ntâches de fond) passe par host.py, que l'hôte remplit au démarrage.\n\nAucun module de ce paquet n'importe qgis : tests/test_core.py le vérifie.\n\"\"\"\n",
 "core/autotilt.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Inclinaison d'une photo 360° calculée d'après ses verticales, sans clic.\n\nUne caméra montée sur un véhicule penche avec lui (pente de la route, dévers, virages) : 1 à\n3° sur les photos imajbox, autant d'erreur de visée. Sur une photo équirectangulaire\nde niveau, les arêtes verticales du monde (angles de façades, poteaux, encadrements) restent\nverticales dans l'image ; la caméra penchée, elles s'inclinent selon une loi connue.\n\n1. Bandes de BAND_DEG d'élévation, au-dessus de l'horizon (le sol, les véhicules et la\n   voiture de prise de vue sont en dessous) : pour chaque pente possible, somme du gradient\n   horizontal le long de droites de cette pente (transformée de Radon locale). Une arête\n   rectiligne y fait un pic net : sa position et sa pente donnent un segment.\n2. Chaque segment impose, comme un objet vertical cliqué (calibration.tilt_from_verticals),\n   que la vraie verticale soit dans le plan qui contient la caméra et le segment. Moindres\n   carrés sur des centaines de segments, rejet itératif des segments qui ne sont pas vraiment\n   verticaux (arbres, toits, objets penchés).\n\nValidé à Pouilly-en-Auxois (photos imajbox) : une inclinaison imposée de 1° est retrouvée à\n0,05° près ; il faut des bâtiments ou des poteaux tout autour (en campagne : pas assez de\nverticales, voir terrain_tilt pour l'estimation par le LiDAR HD).\n\nCalculs numpy seuls (pas d'OpenCV dans QGIS) ; la photo est décodée réduite et rognée à la\nbande utile (host.decode_band), en arrière-plan (host.run_task).\n\"\"\"\n\nimport importlib.util\nimport math\n\nfrom . import calibration, host, metadata, precision\n\nHAS_NUMPY = importlib.util.find_spec(\"numpy\") is not None  # calcul des verticales\n\nELEV_MIN, ELEV_MAX = 3.0, 45.0  # bande analysée (degrés au-dessus de l'horizon)\nBAND_DEG = 2.5  # hauteur d'une bande d'analyse (degrés) : arêtes courtes ou coupées comprises\n# Pente maximale retenue (pixels par pixel, ~6,8°) : une verticale vue à 45° au-dessus de\n# l'horizon penche de deux fois l'inclinaison de la caméra (jusqu'à 3° sur l'imajbox)\nMAX_SLOPE = 0.12\nSLOPE_RANGE = 0.13  # pentes calculées, de part et d'autre\nSLOPES = 131\nWIDTH = 6144  # largeur de travail (photo HD imajbox : 12 288, décodée au demi)\nMIN_SEGMENTS = 40\nMAX_SIGMA = 0.25  # incertitude maximale acceptée (degrés)\nEDGE_BIN = 0.3  # degrés de cap : segments d'une même arête (incertitude)\nFLOOR = math.radians(0.05)  # dispersion minimale des segments retenus (radians)\n\n\ndef segments(band, row0, height, width, azimuth):\n    \"\"\"Segments quasi verticaux de la bande : liste de ((cap, élév.) bas, (cap, élév.) haut),\n    directions brutes (cap de la photo `azimuth` ajouté, comme les clics).\"\"\"\n    import numpy as np\n\n    deg = 180.0 / height\n    rows = max(8, int(round(BAND_DEG / deg)))\n    gx = np.zeros_like(band)\n    gx[:, 1:-1] = band[:, 2:] - band[:, :-2]\n    slopes = np.linspace(-SLOPE_RANGE, SLOPE_RANGE, SLOPES)\n    offs = np.arange(rows) - (rows - 1) / 2.0\n    # Somme le long de x + b·(r − milieu), interpolée entre deux colonnes : pour chaque pente,\n    # la ligne r est lue décalée de base[r] (poids 1 − frac[r]) et de base[r] + 1 (frac[r]).\n    # Les décalages entiers possibles sont peu nombreux : chaque fenêtre est décalée une fois\n    # pour chacun, puis chaque pente lit d'un coup ses lignes dans ces copies et en fait la\n    # somme pondérée (einsum). Mêmes calculs qu'une ligne après l'autre, en 2 appels à numpy\n    # par pente au lieu de 4 par ligne : environ 3 fois plus rapide en Python natif, et bien\n    # plus dans le navigateur (Pyodide, où chaque appel coûte cher et où le produit matriciel\n    # n'est pas optimisé).\n    plan = []\n    for b in slopes:\n        shift = b * offs\n        base = np.floor(shift).astype(int)\n        frac = (shift - base).astype(np.float32)\n        plan.append((np.stack([base, base + 1]), np.stack([1 - frac, frac])))\n    low = min(int(p[0].min()) for p in plan)\n    high = max(int(p[0].max()) for p in plan)\n    lines = np.arange(rows)\n    out = []\n\n    def direction(px, py):\n        return ((px + 0.5) / width * 360.0 - 180.0 + azimuth) % 360, 90.0 - (py + 0.5) * deg\n\n    for top in range(0, band.shape[0] - rows + 1, rows // 2):\n        win = gx[top:top + rows]\n        shifted = np.stack([np.roll(win, -d, axis=1) for d in range(low, high + 1)])  # (décalage, ligne, x)\n        acc = np.empty((SLOPES, width), np.float32)\n        for k, (shifts, weights) in enumerate(plan):\n            acc[k] = np.einsum(\"kr,krx->x\", weights, shifted[shifts - low, lines])\n        acc = np.abs(acc)\n        best = acc.argmax(axis=0)\n        peak = acc[best, np.arange(width)]\n        thr = max(5.0 * rows, 4.0 * float(np.median(peak)))\n        local = peak >= np.maximum.reduce([np.roll(peak, d) for d in range(-4, 5)])\n        yc = row0 + top + (rows - 1) / 2.0\n        half = rows / 2.0\n        for x in np.nonzero(local & (peak > thr))[0]:\n            if abs(slopes[best[x]]) > MAX_SLOPE:\n                continue  # pente hors de la plage cherchée\n            line = _refine(win, x, slopes[best[x]], offs)\n            if line is None:\n                continue\n            xc, b = line\n            out.append((direction(xc + b * half, yc + half), direction(xc - b * half, yc - half)))\n    return out\n\n\ndef _refine(win, x, slope, offs, reach=5):\n    \"\"\"Position et pente précises d'une arête détectée en x avec la pente approchée `slope` :\n    centre du gradient sur chaque ligne (autour de la droite approchée), puis droite des\n    moindres carrés. (x au milieu de la bande, pente) ou None si l'arête n'est pas rectiligne\n    ou pas continue sur toute la bande.\"\"\"\n    import numpy as np\n\n    width = win.shape[1]\n    a, b = float(x), float(slope)\n    for _ in range(3):  # recentrée sur la droite trouvée : moins d'effet de la grille des pixels\n        pred = a + b * offs\n        cols = np.round(pred).astype(int)[:, None] + np.arange(-reach, reach + 1)[None, :]\n        g = np.take_along_axis(win, cols % width, axis=1)\n        sign = 1.0 if g.sum() >= 0 else -1.0\n        wts = np.clip(sign * g, 0, None)\n        total = wts.sum(axis=1)\n        strong = total > 0.3 * np.median(total) if total.any() else total > 0\n        if strong.mean() < 0.8:\n            return None  # arête interrompue\n        centre = (wts * cols).sum(axis=1)[strong] / total[strong]\n        o = offs[strong]\n        b, a = np.polyfit(o, centre, 1)\n    if np.std(centre - (a + b * o)) > 0.4:\n        return None  # pas rectiligne\n    return a, b\n\n\ndef fit(pairs):\n    \"\"\"Verticale vraie d'après des segments (voir calibration.tilt_from_verticals), avec rejet\n    itératif des segments qui s'en écartent. Retourne le dict de tilt_from_verticals\n    complété de sigma (incertitude, degrés), segments (retenus), auto=True, ou None si les\n    segments sont trop peu nombreux ou mal répartis.\"\"\"\n    normals, yaws = [], []\n    for bottom, top in pairs:\n        n = calibration._cross(calibration.vector(*bottom), calibration.vector(*top))\n        norm = math.sqrt(calibration._dot(n, n))\n        if norm > 0:\n            normals.append((n[0] / norm, n[1] / norm, n[2] / norm))\n            yaws.append(bottom[0])\n    keep = list(range(len(normals)))\n    up = (0.0, 0.0, 1.0)\n    for _ in range(8):\n        if len(keep) < 3:\n            return None\n        a11 = a12 = a22 = r1 = r2 = 0.0\n        for i in keep:\n            nx, ny, nz = normals[i]\n            a11 += nx * nx\n            a12 += nx * ny\n            a22 += ny * ny\n            r1 -= nx * nz\n            r2 -= ny * nz\n        det = a11 * a22 - a12 * a12\n        if det <= 0:\n            return None\n        a, b = (a22 * r1 - a12 * r2) / det, (a11 * r2 - a12 * r1) / det\n        up = calibration._unit((a, b, 1.0))\n        res = [calibration._dot(normals[i], up) for i in range(len(normals))]\n        kept = sorted(abs(res[i]) for i in keep)\n        sigma = max(1.4826 * kept[len(kept) // 2], FLOOR)\n        new = [i for i in range(len(normals)) if abs(res[i]) < 3 * sigma]\n        if new == keep:\n            break\n        keep = new\n    if len(keep) < MIN_SEGMENTS:\n        return None\n    # Incertitude : écart-type des segments sur l'information apportée, dans la direction la\n    # moins contrainte (segments mal répartis autour de la photo : une composante mal connue)\n    # Une arête donne un segment par bande qu'elle traverse : leurs erreurs ne sont pas\n    # indépendantes, on compte les arêtes distinctes (cap à EDGE_BIN° près).\n    lam = (a11 + a22) / 2 - math.sqrt(((a11 - a22) / 2) ** 2 + a12 * a12)\n    edges = len({round(yaws[i] / EDGE_BIN) for i in keep})\n    sigma_deg = math.degrees(sigma / math.sqrt(max(lam, 1e-12))) * math.sqrt(len(keep) / max(edges, 1))\n    if sigma_deg > MAX_SIGMA:\n        return None\n    tilt = math.degrees(math.acos(min(1.0, up[2])))\n    if tilt > calibration.MAX_TILT:\n        return None\n    return {\"up\": up, \"tilt\": tilt, \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n            \"residual\": math.degrees(sigma), \"partial\": False, \"count\": len(keep), \"sigma\": sigma_deg,\n            \"auto\": True}\n\n\ndef estimate(data, azimuth):\n    \"\"\"Inclinaison de la photo (octets JPEG, cap du centre de l'image) : dict de fit, ou None.\n    Photo décodée par l'hôte (host.decode_band), réduite à WIDTH et rognée à la bande utile.\"\"\"\n    band = host.decode_band(data, WIDTH, ELEV_MIN, ELEV_MAX)\n    if band is None:\n        return None\n    return fit(segments(*band, azimuth))\n\n\ndef lidar_url(lon, lat, heading):\n    \"\"\"URL des altitudes LiDAR HD sous le véhicule (voir calibration.lidar_points).\"\"\"\n    return precision.lidar_url(calibration.lidar_points(lon, lat, heading))\n\n\ndef is_360(item):\n    \"\"\"Photo équirectangulaire (360°) ?\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    try:\n        if float((props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\") or 0) >= 360:\n            return True\n    except (TypeError, ValueError):\n        pass\n    return (props.get(\"exif\") or {}).get(\"Xmp.GPano.ProjectionType\") == \"equirectangular\"\n\n\n\n\nclass TiltChecker:\n    \"\"\"Inclinaison automatique des photos : verticales de la photo HD (en arrière-plan) et\n    pente et dévers du LiDAR HD sous le véhicule. Le résultat est rangé dans le calage\n    (Calibration.set_auto), qui le conserve d'une session à l'autre ; une photo déjà\n    analysée ne l'est pas à nouveau. Seule la dernière photo demandée est analysée : celle\n    qu'on quitte est abandonnée (téléchargement interrompu, rien d'enregistré), elle sera\n    reprise si on y revient.\"\"\"\n\n    def __init__(self):\n        self._pending = {}  # photo -> rappels en attente\n        self._replies = {}  # photo -> téléchargement de la photo HD en cours\n        self.current = None  # dernière photo demandée\n        self.run = None  # calcul en arrière-plan : host.run_task, ou celui-ci (tests)\n\n    def pending(self, pic):\n        return pic in self._pending\n\n    def check(self, item, cal, done=None):\n        \"\"\"Lance l'analyse de la photo (fiche STAC) si elle n'a ni inclinaison calée à la main\n        sur deux objets ou plus, ni inclinaison automatique ; done() quand elle est rangée dans `cal` (ou abandonnée).\"\"\"\n        pic = item.get(\"id\")\n        callbacks = [done] if done else []\n        if pic != self.current:\n            self._abandon_others(pic)\n        self.current = pic\n        if not pic or cal.manual_complete(pic) or pic in cal.auto:\n            for cb in callbacks:\n                cb()\n            return\n        if pic in self._pending:\n            self._pending[pic] += callbacks\n            return\n        heading = metadata.precise_heading(item)\n        heading = metadata.item_heading(item) if heading is None else heading\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            lon = lat = None\n        if heading is None or lon is None or not is_360(item):\n            for cb in callbacks:\n                cb()\n            return\n        self._pending[pic] = callbacks\n        state = {}\n\n        def finish():\n            if self.current != pic:\n                return  # photo quittée : abandonnée (voir _abandon_others)\n            if \"lidar\" not in state or \"verticals\" not in state:\n                return  # l'autre moitié n'est pas encore arrivée\n            if state[\"lidar_error\"] and state[\"verticals\"] is None:\n                entry = None  # service injoignable : à refaire plus tard\n            else:\n                entry = {\"sequence\": item.get(\"collection\"), \"heading\": float(heading),\n                         \"verticals\": state[\"verticals\"], \"lidar\": state[\"lidar\"]}\n            for cb in [None] + self._pending.pop(pic, []):\n                if cb is None:\n                    if entry is not None:\n                        cal.set_auto(pic, entry)\n                else:\n                    cb()\n\n        def got_lidar(data, error):\n            z = [] if error else [g for g in _elevations(data)]\n            ok = len(z) == len(calibration.LIDAR_GRID) and None not in z\n            state[\"lidar\"] = list(calibration.lidar_slopes(z)) if ok else None\n            state[\"lidar_error\"] = bool(error)\n            finish()\n\n        def got_image(data, error):\n            self._replies.pop(pic, None)\n            if self.current != pic:\n                return  # photo quittée pendant le téléchargement : pas de calcul\n            if error or not data:\n                analysed(None)\n            else:\n                (self.run or host.run_task)(estimate, (bytes(data), float(heading)), analysed)\n\n        def analysed(res):\n            state[\"verticals\"] = ({\"up\": list(res[\"up\"]), \"count\": res[\"count\"], \"sigma\": res[\"sigma\"]}\n                                  if res else None)\n            finish()\n\n        host.fetch_json(lidar_url(lon, lat, heading), got_lidar)\n        href = ((item.get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n        if href and HAS_NUMPY:\n            self._replies[pic] = host.fetch(href, got_image, prefer_cache=True)\n        else:\n            analysed(None)\n\n    def _abandon_others(self, keep):\n        \"\"\"Abandonne l'analyse des photos autres que `keep` : téléchargements interrompus,\n        rappels oubliés, rien d'enregistré.\"\"\"\n        for pic in [p for p in self._pending if p != keep]:\n            self._pending.pop(pic, None)\n            reply = self._replies.pop(pic, None)\n            try:\n                if reply is not None:\n                    reply.abort()\n            except (AttributeError, RuntimeError):  # déjà terminé ou détruit\n                pass\n\n\ndef _elevations(data):\n    return precision._ground(data)\n",
 "core/buildings.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Façade du cadastre traversée par une visée, contrôlée par le MNS du LiDAR HD.\n\nPour une hauteur dont le pied est caché (voiture, haie, muret), ou pour définir une façade\nd'un seul clic : le mur est le premier bord de bâtiment du cadastre (Parcellaire Express,\nservice WFS de la Géoplateforme) que coupe la visée horizontale depuis la photo.\n\nTests du 12/10/2026 (façades triangulées entre photos imajbox RTK ; erreur sur la distance au\nmur) : à Nuits-Saint-Georges et Semur-en-Auxois (90 façades), cadastre à 0,18 m en médiane,\n90 % sous 0,8 m ; autour de Dijon, 0,08 m ; mais 0,8 m à Pouilly-en-Auxois, et des erreurs\ngrossières (2 à 18 m) quand le mur visé manque au cadastre (annexe, clôture). Le MNS du LiDAR\nHD (bâti compris) place le mur au bord du toit, 0,8 m trop près en médiane (0 à 2,2 m selon le\ndébord) : il sert de contrôle. Près de la façade du cadastre (à partir de SEARCH_BEFORE m\navant : arbres et véhicules intermédiaires exclus), le bâti commence là où le MNS dépasse le\nMNT de BUILT m ; le cadastre est confirmé s'il est de LIDAR_BEFORE m avant à LIDAR_AFTER m\naprès ce point (débord de toit), sinon un avertissement invite à contrôler la façade sur la\ncarte. Sans LiDAR publié, le cadastre est utilisé sans contrôle (signalé).\n\nLecture par maille d'environ 100 m, une fois par session ; une panne n'est pas gardée.\n\"\"\"\n\nimport array\nimport math\nimport time\nfrom urllib.parse import urlencode\n\nfrom . import host, roads, triangulation\n\nWFS_URL = roads.WFS_URL\nLAYER = \"CADASTRALPARCELS.PARCELLAIRE_EXPRESS:batiment\"\nLIGHT = \"Construction légère\"  # type des bâtiments légers du cadastre (« Bâtiment en dur » sinon)\nWMS_URL = \"https://data.geopf.fr/wms-r/wms\"\nMNS = \"IGNF_LIDAR-HD_MNS_ELEVATION.ELEVATIONGRIDCOVERAGE.WGS84G\"\nMNT = \"IGNF_LIDAR-HD_MNT_ELEVATION.ELEVATIONGRIDCOVERAGE.WGS84G\"\nCELL = roads.CELL\nMARGIN = 60.0  # m autour de la maille : bâtiments visés depuis une photo de la maille\nPIXEL = 0.5  # m : pas de la grille LiDAR demandée\nMIN_RANGE, MAX_RANGE = 1.0, 60.0  # m : façades cherchées le long de la visée\nBUILT = 2.0  # m de MNS au-dessus du MNT : bâti\nLIDAR_BEFORE, LIDAR_AFTER = 0.5, 2.0  # m : écart toléré entre cadastre et bâti du LiDAR\nSEARCH_BEFORE = 3.0  # m avant la façade du cadastre où chercher le bâti du LiDAR\nNODATA_BELOW = -1000.0\nRETRY = roads.RETRY\nPENDING = roads.PENDING\n\n\ndef _cell(lon, lat):\n    return roads._cell(lon, lat)\n\n\ndef _bounds(cell):\n    \"\"\"(lon0, lat0, lon1, lat1) de la maille et de MARGIN m autour.\"\"\"\n    lon0, lat0 = cell[0] * CELL, cell[1] * CELL\n    dlat = MARGIN / 111320.0\n    dlon = MARGIN / (111320.0 * math.cos(math.radians(lat0 + CELL / 2)))\n    return lon0 - dlon, lat0 - dlat, lon0 + CELL + dlon, lat0 + CELL + dlat\n\n\ndef wfs_url(cell):\n    lon0, lat0, lon1, lat1 = _bounds(cell)\n    return WFS_URL + \"?\" + urlencode({\n        \"SERVICE\": \"WFS\", \"VERSION\": \"2.0.0\", \"REQUEST\": \"GetFeature\", \"TYPENAMES\": LAYER,\n        \"OUTPUTFORMAT\": \"application/json\", \"SRSNAME\": \"EPSG:4326\", \"COUNT\": 2000,\n        \"BBOX\": \"{:.7f},{:.7f},{:.7f},{:.7f},urn:ogc:def:crs:EPSG::4326\".format(lat0, lon0, lat1, lon1)})\n\n\ndef grid_size(cell):\n    \"\"\"(largeur, hauteur) en pixels de la grille LiDAR de la maille, au pas de PIXEL m.\"\"\"\n    lon0, lat0, lon1, lat1 = _bounds(cell)\n    w = (lon1 - lon0) * 111320.0 * math.cos(math.radians((lat0 + lat1) / 2)) / PIXEL\n    h = (lat1 - lat0) * 111320.0 / PIXEL\n    return int(round(w)), int(round(h))\n\n\ndef wms_url(cell, layer):\n    lon0, lat0, lon1, lat1 = _bounds(cell)\n    w, h = grid_size(cell)\n    return WMS_URL + \"?\" + urlencode({\n        \"SERVICE\": \"WMS\", \"VERSION\": \"1.3.0\", \"REQUEST\": \"GetMap\", \"LAYERS\": layer, \"STYLES\": \"\",\n        \"CRS\": \"EPSG:4326\", \"BBOX\": \"{:.7f},{:.7f},{:.7f},{:.7f}\".format(lat0, lon0, lat1, lon1),\n        \"WIDTH\": w, \"HEIGHT\": h, \"FORMAT\": \"image/x-bil;bits=32\"})\n\n\ndef parse_edges(data):\n    \"\"\"Bords des bâtiments en dur d'une réponse WFS (GeoJSON) : [((lon, lat), (lon, lat))].\"\"\"\n    out = []\n    for feat in (data or {}).get(\"features\") or []:\n        if (feat.get(\"properties\") or {}).get(\"type\") == LIGHT:\n            continue  # abri, appentis, serre : rarement la façade visée, souvent devant elle\n        geom = feat.get(\"geometry\") or {}\n        if geom.get(\"type\") == \"Polygon\":\n            polys = [geom.get(\"coordinates\") or []]\n        elif geom.get(\"type\") == \"MultiPolygon\":\n            polys = geom.get(\"coordinates\") or []\n        else:\n            continue\n        for poly in polys:\n            for ring in poly:\n                try:\n                    pts = [(float(c[0]), float(c[1])) for c in ring]\n                except (TypeError, ValueError, IndexError):\n                    continue\n                out += [(a, b) for a, b in zip(pts, pts[1:]) if a != b]\n    return out\n\n\nclass Grid:\n    \"\"\"Grille d'altitudes (flottants 32 bits, ligne 0 au nord) couvrant `bounds`.\"\"\"\n\n    def __init__(self, data, cell):\n        self.values = array.array(\"f\")\n        self.values.frombytes(bytes(data)[:len(data) - len(data) % 4])\n        if array.array(\"f\", [1.0]).tobytes() != b\"\\x00\\x00\\x80\\x3f\":\n            self.values.byteswap()  # fichier petit-boutiste\n        self.w, self.h = grid_size(cell)\n        if len(self.values) != self.w * self.h:\n            raise ValueError(\"grille LiDAR de taille inattendue\")\n        self.lon0, self.lat0, self.lon1, self.lat1 = _bounds(cell)\n\n    def at(self, lon, lat):\n        \"\"\"Altitude au point (plus proche pixel), ou None hors de la grille ou sans données.\"\"\"\n        c = math.floor((lon - self.lon0) / (self.lon1 - self.lon0) * self.w)\n        r = math.floor((self.lat1 - lat) / (self.lat1 - self.lat0) * self.h)\n        if not (0 <= c < self.w and 0 <= r < self.h):\n            return None\n        z = self.values[r * self.w + c]\n        return z if z > NODATA_BELOW else None\n\n\ndef wall_hit(edges, lon, lat, yaw):\n    \"\"\"Premier bord de bâtiment coupé par la visée horizontale depuis (lon, lat) au cap yaw :\n    dict distance (m), points ((lon, lat) des extrémités du bord), ou None.\"\"\"\n    a = math.radians(yaw)\n    dx, dy = math.sin(a), math.cos(a)\n    best = None\n    for p, q in edges:\n        x1, y1 = triangulation._local(p[0], p[1], lon, lat)\n        x2, y2 = triangulation._local(q[0], q[1], lon, lat)\n        ex, ey = x2 - x1, y2 - y1\n        den = dx * ey - dy * ex\n        if abs(den) < 1e-9:\n            continue\n        t = (x1 * ey - y1 * ex) / den\n        s = (x1 * dy - y1 * dx) / den\n        if MIN_RANGE <= t <= MAX_RANGE and 0.0 <= s <= 1.0 and (best is None or t < best[\"distance\"]):\n            best = {\"distance\": t, \"points\": [p, q]}\n    return best\n\n\ndef lidar_built(mns, mnt, lon, lat, yaw, start, until):\n    \"\"\"Distance le long de la visée horizontale où commence le bâti du LiDAR (MNS au-dessus\n    du MNT de BUILT m), cherchée de `start` à `until` m ; None sans bâti, False sans LiDAR\n    publié.\"\"\"\n    seen = False\n    t = max(0.5, start)\n    while t <= until:\n        p = triangulation.offset(lon, lat, yaw, t)\n        s, g = mns.at(*p), mnt.at(*p)\n        if s is not None and g is not None:\n            seen = True\n            if s - g > BUILT:\n                return t\n        t += PIXEL / 2\n    return None if seen else False\n\n\ndef check(distance, built):\n    \"\"\"Contrôle du mur du cadastre par le LiDAR : (texte, avertissement).\"\"\"\n    if built is False:\n        return \"LiDAR HD non publié ici : façade du cadastre non contrôlée\", True\n    if built is None:\n        return (\"pas de bâti du LiDAR HD à la façade du cadastre : contrôlez-la sur la carte \"\n                \"(mur absent du LiDAR, ou cadastre décalé)\"), True\n    gap = distance - built\n    if -LIDAR_BEFORE <= gap <= LIDAR_AFTER:\n        return \"façade confirmée par le LiDAR HD\", False\n    return (\"cadastre et LiDAR HD divergent de {:.1f} m : contrôlez la façade sur la carte\".format(\n        abs(gap)).replace(\".\", \",\")), True\n\n\nclass BuildingProvider:\n    \"\"\"Façade du cadastre visée depuis une photo (voir le module), avec lectures en cache.\n\n    lookup est synchrone : il rend la façade si les données sont là, PENDING si une lecture\n    vient d'être lancée (ready() sera appelé à son arrivée), None sinon.\"\"\"\n\n    def __init__(self):\n        self._cache = {}  # (type, maille) -> arêtes ou grille (None : rien d'utilisable)\n        self._pending = set()\n        self._failed = {}\n        self.ready = None\n\n    def lookup(self, lon, lat, yaw):\n        cell = _cell(lon, lat)\n        edges = self._get((\"cadastre\", cell), lambda: wfs_url(cell), parse_edges)\n        mns = self._get((\"mns\", cell), lambda: wms_url(cell, MNS), lambda data: Grid(data, cell), raw=True)\n        mnt = self._get((\"mnt\", cell), lambda: wms_url(cell, MNT), lambda data: Grid(data, cell), raw=True)\n        if PENDING in (edges, mns, mnt):\n            return PENDING\n        hit = wall_hit(edges or [], lon, lat, yaw)\n        if hit is None:\n            return None\n        # Bâti cherché seulement près du mur : un arbre, une haie ou un véhicule entre la photo\n        # et la façade dépasse aussi du MNT\n        d = hit[\"distance\"]\n        built = lidar_built(mns, mnt, lon, lat, yaw, d - SEARCH_BEFORE, d + LIDAR_AFTER) if mns and mnt else False\n        hit[\"check\"], hit[\"warning\"] = check(hit[\"distance\"], built)\n        return hit\n\n    def _get(self, key, url, parse, raw=False):\n        if key in self._cache:\n            return self._cache[key]\n        if key in self._pending:\n            return PENDING\n        if time.monotonic() - self._failed.get(key, -RETRY) < RETRY:\n            return None\n        self._pending.add(key)\n\n        def done(data, error):\n            self._pending.discard(key)\n            parsed = None\n            if not error:\n                try:\n                    parsed = parse(data)\n                except (ValueError, TypeError):\n                    error = \"réponse illisible\"  # exception du service (XML) : panne, pas absence de données\n            if error:\n                self._failed[key] = time.monotonic()\n            else:\n                self._cache[key] = parsed\n            if self.ready is not None:\n                self.ready()\n\n        (host.fetch if raw else host.fetch_json)(url(), done, timeout_ms=20000)\n        return PENDING if key in self._pending else self._cache.get(key)\n",
 "core/calibration.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Calage des photos : correction d'inclinaison et recalage du cap.\n\n- Inclinaison (par photo) : une caméra 360 est rarement parfaitement de niveau.\n  On clique le pied puis le sommet d'objets verticaux (poteau, angle de façade) :\n  chacun impose que la vraie verticale soit dans le plan qui contient la caméra\n  et l'objet. Un objet corrige la pente vue de côté dans sa direction ; deux\n  objets à peu près à angle droit corrigent l'inclinaison complète. Sans clic,\n  l'inclinaison est calculée d'après les verticales de la photo (autotilt.py), ou à\n  défaut estimée par la pente et le dévers du LiDAR HD sous le véhicule, quand la\n  séquence a montré que la caméra penche avec lui (voir lidar_model).\n- Hauteur de caméra (par séquence) : on mesure une longueur connue, au sol\n  (trait de marquage, place de stationnement) ou en hauteur (objet de hauteur\n  connue). Les longueurs mesurées étant à peu près proportionnelles à la\n  hauteur de la caméra, on cherche celle qui redonne la longueur connue.\n- Cap et position (par séquence, autour des photos utilisées) : on clique dans\n  la photo un repère visible sur la carte, puis ce repère sur la carte. Les\n  repères donnent, par relèvement, le décalage de cap et de position GPS des\n  photos, chacun gardant son a priori (cap et position d'origine à leur\n  précision) : un repère seul corrige surtout le cap, sans jamais le dégrader ;\n  trois repères ou plus bien répartis autour de la photo recalent la position.\n\nDirections : (cap absolu en degrés, 0 = nord, sens horaire ; élévation en\ndegrés). Les corrections s'appliquent dans cet ordre : inclinaison, puis cap.\nCalage conservé dans le profil QGIS de l'utilisateur, d'une session et d'un projet à\nl'autre, jusqu'à ce qu'il soit refait ou effacé (voir plugin.py). Module sans dépendance à QGIS.\n\"\"\"\n\nimport math\n\nfrom . import ground\nfrom .triangulation import _local, offset\n\nOBJECT_ERROR = 0.2  # écart d'un objet vertical cliqué à la verticale vraie (degrés : clics, objet)\nUNCALIBRATED = 2.0  # inclinaison d'une photo non calée (degrés) : 1 à 3° mesurés sur l'imajbox\nMAX_TILT = 10.0  # au-delà, les clics sont sûrement faux (objet penché, pied/sommet inversés)\nMIN_SPAN = 3.0  # écart d'élévation minimal entre pied et sommet (degrés)\nMAX_LEAN = 30.0  # écart de cap maximal entre pied et sommet d'un même objet vertical\nMAX_OFFSET = 20.0  # au-delà, le repère cliqué sur la carte n'est sûrement pas le bon\nMIN_LANDMARK = 5.0  # distance minimale du repère (m)\nAIM_ERROR = 0.1  # précision d'un clic dans la photo zoomée (degrés)\nMAP_ERROR = 0.5  # précision de position du repère sur la carte (m)\nDEFAULT_ACCURACY = 3.0  # précision GPS supposée quand la photo ne l'indique pas (m)\nSURVEY_PRIOR = 0.5  # précision du cap d'origine, matériel de relevé (degrés)\nPRIOR = 3.0  # précision du cap d'origine, autres appareils (boussole, trajectoire GPS)\nREACH = 300.0  # portée du recalage (m) autour des photos qui l'ont servi : le GPS dérive au-delà\nOUTLIER = 4.0  # un repère qui s'écarte de plus de OUTLIER écarts-types des autres est refusé\n# Inclinaison estimée par le LiDAR HD : plan du sol ajusté sous le véhicule, sur une grille de\n# LIDAR_ALONG m devant et derrière la caméra et LIDAR_ACROSS m à droite et à gauche (sous les\n# roues) ; la grille atténue l'arrondi au centimètre des altitudes du service. Validé à\n# Pouilly-en-Auxois (imajbox, 18 photos) : 0,4° d'écart en long et 0,5° en travers avec les\n# verticales.\nLIDAR_ALONG, LIDAR_ACROSS = 1.5, 0.8\nLIDAR_GRID = [(a * LIDAR_ALONG, c * LIDAR_ACROSS) for a in (-1, -0.5, 0, 0.5, 1) for c in (-1, 0, 1)]\nLIDAR_MIN_PHOTOS = 3  # photos de la séquence calées par leurs verticales pour valider le modèle\nLIDAR_MAX_SIGMA = 0.8  # au-delà, la caméra ne suit pas le véhicule (portée à pied, stabilisée)\nLIDAR_MIN_SIGMA = 0.3\n\n\nCAMERA_MIN, CAMERA_MAX = 0.3, 6.0  # plage de hauteurs de caméra admises (m)\n\n\ndef _fr(value, digits=1):\n    return \"{:.{}f}\".format(value, digits).replace(\".\", \",\")\n\n\nclass CalibrationError(ValueError):\n    \"\"\"Clics inexploitables (message destiné à l'utilisateur).\"\"\"\n\n\ndef vector(yaw, elev):\n    \"\"\"Vecteur unitaire (est, nord, haut) d'une direction.\"\"\"\n    y, e = math.radians(yaw), math.radians(elev)\n    return (math.sin(y) * math.cos(e), math.cos(y) * math.cos(e), math.sin(e))\n\n\ndef angles(v):\n    \"\"\"Direction (cap, élévation) d'un vecteur.\"\"\"\n    x, y, z = v\n    return math.degrees(math.atan2(x, y)) % 360, math.degrees(math.atan2(z, math.hypot(x, y)))\n\n\ndef _cross(a, b):\n    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])\n\n\ndef _dot(a, b):\n    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]\n\n\ndef _unit(v):\n    n = math.sqrt(_dot(v, v))\n    return (v[0] / n, v[1] / n, v[2] / n)\n\n\ndef tilt_from_verticals(verticals, prior=None):\n    \"\"\"Verticale vraie dans le repère de la photo, d'après des objets verticaux.\n\n    verticals : liste de ((cap, élév.) du pied, (cap, élév.) du sommet).\n    prior : (up, sigma en degrés), inclinaison déjà connue (calcul automatique) qui complète\n    les objets cliqués : chaque objet ne corrige que la composante qu'il voit, l'autre reste\n    celle de l'a priori.\n    Retourne un dict : up (vecteur unitaire), tilt (degrés), toward (cap vers\n    lequel le haut de la caméra penche), residual (écart moyen des objets à la\n    verticale retenue, degrés, None avec un seul objet), partial (vrai si un\n    seul objet ou des objets alignés, sans a priori : seule une composante est corrigée),\n    sigma (incertitude, degrés, dans la direction la moins contrainte).\n    \"\"\"\n    normals = []\n    for bottom, top in verticals:\n        if top[1] - bottom[1] < MIN_SPAN:\n            raise CalibrationError(\"Cliquez d'abord le pied, puis le sommet de l'objet vertical, \"\n                                   \"assez haut (au moins {:.0f}° plus haut).\".format(MIN_SPAN))\n        if abs((top[0] - bottom[0] + 540) % 360 - 180) > MAX_LEAN:\n            raise CalibrationError(\"Le pied et le sommet ne semblent pas appartenir au même objet vertical.\")\n        normals.append(_unit(_cross(vector(*bottom), vector(*top))))\n    # Verticale vraie (a, b, 1) : n·(a, b, 1) = 0 pour chaque objet, moindres carrés.\n    # Un léger amortissement donne la plus petite correction compatible quand les objets\n    # ne suffisent pas (un seul objet, ou objets dans la même direction).\n    # Chaque objet pèse 1 / OBJECT_ERROR² ; l'a priori, 1 / sigma² sur chaque composante.\n    w = 1.0 / math.radians(OBJECT_ERROR) ** 2\n    a11 = a12 = a22 = r1 = r2 = 0.0\n    for nx, ny, nz in normals:\n        a11 += w * nx * nx\n        a12 += w * nx * ny\n        a22 += w * ny * ny\n        r1 -= w * nx * nz\n        r2 -= w * ny * nz\n    seen = (a11, a12, a22)  # information des seuls objets\n    if prior is not None:\n        pup, psigma = prior\n        wp = 1.0 / math.radians(max(psigma, 0.01)) ** 2\n        a11, a22 = a11 + wp, a22 + wp\n        r1, r2 = r1 + wp * pup[0] / pup[2], r2 + wp * pup[1] / pup[2]\n        damp = 0.0\n    else:\n        damp = 1e-6 * max(a11 + a22, 1e-12)\n        a11, a22 = a11 + damp, a22 + damp\n    det = a11 * a22 - a12 * a12\n    a, b = (a22 * r1 - a12 * r2) / det, (a11 * r2 - a12 * r1) / det\n    up = _unit((a, b, 1.0))\n    tilt = math.degrees(math.acos(min(1.0, up[2])))\n    if tilt > MAX_TILT:\n        raise CalibrationError(\"Inclinaison trouvée de {:.0f}° : objet pas vraiment vertical ou clics \"\n                               \"imprécis. Recommencez sur un autre objet.\".format(tilt))\n    # Partiel si les plans des objets se coupent mal (objets dans la même direction)\n    s11, s12, s22 = seen\n    partial = prior is None and (len(normals) < 2 or s11 * s22 - s12 * s12 < 0.1 * ((s11 + s22) / 2) ** 2)\n    lam = (a11 + a22) / 2 - math.sqrt(((a11 - a22) / 2) ** 2 + a12 * a12)  # moins contrainte\n    residual = None\n    if len(normals) > 1:\n        residual = math.degrees(math.sqrt(sum(math.asin(min(1.0, abs(_dot(n, up)))) ** 2\n                                              for n in normals) / len(normals)))\n    sigma = UNCALIBRATED if partial else math.degrees(1.0 / math.sqrt(max(lam, 1e-12)))\n    if residual is not None and not partial:\n        sigma = max(sigma, residual / math.sqrt(len(normals)))\n    return {\"up\": up, \"tilt\": tilt, \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n            \"residual\": residual, \"partial\": partial, \"count\": len(normals), \"sigma\": sigma}\n\n\ndef tilt_components(up, heading):\n    \"\"\"(avant, droite) en degrés : de combien la verticale vraie, vue de la caméra, penche\n    vers l'avant (cap `heading`) et vers la droite. Une caméra qui monte une pente de p° voit\n    la verticale pencher de p° vers l'avant ; inclinée vers la gauche, vers la droite.\"\"\"\n    h = math.radians(heading)\n    return (math.degrees(math.atan2(up[0] * math.sin(h) + up[1] * math.cos(h), up[2])),\n            math.degrees(math.atan2(up[0] * math.cos(h) - up[1] * math.sin(h), up[2])))\n\n\ndef up_from_components(forward, right, heading):\n    \"\"\"Verticale vraie (repère de la photo) penchée de forward° vers l'avant et right° vers la\n    droite (inverse de tilt_components).\"\"\"\n    h = math.radians(heading)\n    f, r = math.tan(math.radians(forward)), math.tan(math.radians(right))\n    return _unit((f * math.sin(h) + r * math.cos(h), f * math.cos(h) - r * math.sin(h), 1.0))\n\n\ndef lidar_points(lon, lat, heading):\n    \"\"\"Points du sol où lire le LiDAR HD : grille LIDAR_GRID (en avant, à droite) autour de\n    la caméra.\"\"\"\n    out = []\n    for along, right in LIDAR_GRID:\n        p = offset(lon, lat, heading, along) if along else (lon, lat)\n        out.append(offset(p[0], p[1], heading + 90, right) if right else p)\n    return out\n\n\ndef lidar_slopes(z):\n    \"\"\"(pente en long, dévers) en degrés du plan ajusté sur les altitudes des lidar_points\n    (grille symétrique : les pentes sont des moyennes pondérées indépendantes). La verticale\n    penche vers l'avant en montée, vers la droite quand la droite est plus haute.\"\"\"\n    sa = sum(a * h for (a, _), h in zip(LIDAR_GRID, z)) / sum(a * a for a, _ in LIDAR_GRID)\n    sc = sum(c * h for (_, c), h in zip(LIDAR_GRID, z)) / sum(c * c for _, c in LIDAR_GRID)\n    return math.degrees(math.atan(sa)), math.degrees(math.atan(sc))\n\n\ndef lidar_model(entries):\n    \"\"\"Modèle de la séquence : la caméra penche-t-elle avec le véhicule ? entries : inclinaisons\n    automatiques des photos de la séquence (voir Calibration.auto). Retourne le décalage moyen\n    (avant, droite) entre verticales et LiDAR (fixation de la caméra), l'écart-type sigma et le\n    nombre de photos, ou None si trop peu de photos le vérifient ou si l'écart est trop grand.\"\"\"\n    diffs = []\n    for e in entries:\n        v, lidar = e.get(\"verticals\"), e.get(\"lidar\")\n        if v and lidar:\n            f, r = tilt_components(v[\"up\"], e[\"heading\"])\n            diffs.append((f - lidar[0], r - lidar[1]))\n    if len(diffs) < LIDAR_MIN_PHOTOS:\n        return None\n    n = len(diffs)\n    mf, mr = sum(d[0] for d in diffs) / n, sum(d[1] for d in diffs) / n\n    sigma = math.sqrt(sum((d[0] - mf) ** 2 + (d[1] - mr) ** 2 for d in diffs) / (2 * max(n - 1, 1)))\n    if sigma > LIDAR_MAX_SIGMA:\n        return None\n    return {\"offset\": (mf, mr), \"sigma\": max(sigma, LIDAR_MIN_SIGMA), \"count\": n}\n\n\ndef untilt(up, yaw, elev):\n    \"\"\"Direction corrigée : rotation qui ramène la verticale `up` au zénith.\"\"\"\n    v = vector(yaw, elev)\n    k = (up[1], -up[0], 0.0)  # up × zénith\n    s = math.hypot(k[0], k[1])\n    if s < 1e-12:\n        return yaw % 360, elev\n    k = (k[0] / s, k[1] / s, 0.0)\n    c = up[2]\n    kxv, kv = _cross(k, v), _dot(k, v)\n    r = tuple(v[i] * c + kxv[i] * s + k[i] * kv * (1 - c) for i in range(3))  # Rodrigues\n    return angles(r)\n\n\ndef _reference_length(kind, camera_height, clicks):\n    \"\"\"Longueur mesurée (m) avec une hauteur de caméra donnée : distance entre deux\n    points au sol (\"ground\") ou hauteur d'un objet, pied puis sommet (\"height\").\"\"\"\n    if kind == \"height\":\n        return ground.measure_height(camera_height, *clicks)[\"value\"]\n    ground_z = (clicks[0].get(\"profile\") or ground.flat_profile())[0][1]  # même caméra pour les deux clics\n    (_, p, z1), (_, q, z2) = (ground._ground_point(camera_height, c, ground_z) for c in clicks)\n    x, y = _local(q[0], q[1], p[0], p[1])\n    return math.sqrt(x * x + y * y + (z2 - z1) ** 2)\n\n\ndef _solve_height(kind, clicks, known):\n    \"\"\"Hauteur de caméra qui redonne la longueur connue (dichotomie : la longueur\n    mesurée croît avec la hauteur de caméra).\"\"\"\n    def excess(h):\n        try:\n            return _reference_length(kind, h, clicks) - known\n        except ground.GroundError:\n            return float(\"inf\")  # point trop loin : caméra trop haute\n\n    lo, hi = CAMERA_MIN, CAMERA_MAX\n    if excess(lo) > 0:\n        raise CalibrationError(\"Longueur mesurée trop grande même avec une caméra à {} m : vérifiez la \"\n                               \"longueur connue et les clics.\".format(str(CAMERA_MIN).replace(\".\", \",\")))\n    if excess(hi) < 0:\n        raise CalibrationError(\"Longueur mesurée trop petite même avec une caméra à {} m : vérifiez la \"\n                               \"longueur connue et les clics.\".format(str(CAMERA_MAX).replace(\".\", \",\")))\n    for _ in range(40):\n        mid = (lo + hi) / 2.0\n        if excess(mid) > 0:\n            hi = mid\n        else:\n            lo = mid\n    return (lo + hi) / 2.0\n\n\ndef camera_height(kind, clicks, known, tilt_sigma=None):\n    \"\"\"Hauteur de caméra (m) et son incertitude, d'après une longueur connue.\n\n    kind : \"ground\" (deux clics au sol) ou \"height\" (pied au sol, puis sommet) ;\n    clicks : dicts avec elev (corrigée de l'inclinaison), yaw, lon, lat, profile.\n    L'incertitude combine (somme quadratique) l'inclinaison de la photo, commune aux deux\n    clics (tilt_sigma degrés, UNCALIBRATED par défaut), et la visée de chaque clic (AIM_ERROR).\n    \"\"\"\n    if known <= 0:\n        raise CalibrationError(\"Indiquez la longueur connue.\")\n    if kind == \"height\" and clicks[0].get(\"pic\") != clicks[1].get(\"pic\"):\n        raise CalibrationError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n    try:\n        h = _solve_height(kind, clicks, known)\n    except ground.GroundError as exc:\n        raise CalibrationError(str(exc))\n    tilt_sigma = UNCALIBRATED if tilt_sigma is None else tilt_sigma\n    groups = []\n    for north, east in ((tilt_sigma, 0.0), (0.0, tilt_sigma)):\n        variants = []\n        for sign in (-1, 1):\n            up = up_from_components(sign * north, sign * east, 0.0)\n            variants.append([dict(c, **dict(zip((\"yaw\", \"elev\"), untilt(up, c[\"yaw\"], c[\"elev\"])))) for c in clicks])\n        groups.append(variants)\n    for i in range(len(clicks)):\n        variants = []\n        for sign in (-1, 1):\n            moved = [dict(c) for c in clicks]\n            moved[i][\"elev\"] += sign * AIM_ERROR\n            variants.append(moved)\n        groups.append(variants)\n    total = 0.0\n    for variants in groups:\n        worst = 0.0\n        for moved in variants:\n            try:\n                worst = max(worst, abs(_solve_height(kind, moved, known) - h))\n            except (CalibrationError, ground.GroundError):\n                worst = max(worst, h)  # référence trop loin pour être fiable\n        total += worst * worst\n    return h, max(math.sqrt(total), 0.005)\n\n\nclass Calibration:\n    \"\"\"Calages : inclinaison par photo ; cap, position et hauteur de caméra par séquence.\n\n    Seules les observations sont conservées (clics et repères) : les corrections en sont\n    recalculées. to_dict / load permettent de les enregistrer (dans le profil QGIS), merge\n    d'y ajouter un calage enregistré ailleurs (projet d'une version précédente) ;\n    `changed`, s'il est défini, est appelé après chaque modification.\n    \"\"\"\n\n    FORMAT = 1  # version du format enregistré\n\n    def __init__(self):\n        self.verticals = {}  # pic -> [((cap, élév.) pied, (cap, élév.) sommet)]\n        self.landmarks = {}  # séquence -> [dicts : pic, lon, lat, yaw, elev, mlon, mlat, accuracy, prior]\n        # séquence -> calages de la hauteur de caméra : dicts kind, known, clicks (clics bruts,\n        # recalculés avec le calage actuel, voir camera), ou (hauteur, incertitude) enregistrés\n        # par une version précédente (valeur figée)\n        self.heights = {}\n        self._cameras = {}  # séquence -> hauteur recalculée (cache, vidé à chaque modification)\n        # pic -> inclinaison automatique : sequence, heading (cap du centre de l'image),\n        # verticals (up, count, sigma : d'après les verticales de la photo, ou None), lidar\n        # ((pente, dévers) en degrés sous le véhicule, ou None)\n        self.auto = {}\n        self._tilts = {}\n        self._models = {}  # séquence -> lidar_model (cache)\n        self.changed = None\n\n    def _notify(self):\n        self._cameras = {}  # l'inclinaison ou le cap ont pu changer : hauteurs à recalculer\n        if self.changed is not None:\n            self.changed()\n\n    # Enregistrement --------------------------------------------------------\n    def to_dict(self):\n        return {\n            \"format\": self.FORMAT,\n            \"verticals\": {pic: [[list(b), list(t)] for b, t in v] for pic, v in self.verticals.items()},\n            \"landmarks\": self.landmarks,\n            \"heights\": {seq: [o if isinstance(o, dict) else list(o) for o in obs] for seq, obs in self.heights.items()},\n            \"auto\": self.auto,\n        }\n\n    def load(self, data):\n        \"\"\"Remplace le calage par celui enregistré (dict de to_dict, ou None : calage vide).\n        Les entrées illisibles sont ignorées. Ne déclenche pas `changed`.\"\"\"\n        self.verticals, self.landmarks, self.heights, self._tilts = {}, {}, {}, {}\n        self.auto, self._models, self._cameras = {}, {}, {}\n        if not isinstance(data, dict) or data.get(\"format\") != self.FORMAT:\n            return\n        keys = (\"pic\", \"lon\", \"lat\", \"yaw\", \"elev\", \"mlon\", \"mlat\", \"accuracy\", \"prior\")\n        try:\n            for pic, verticals in (data.get(\"verticals\") or {}).items():\n                verticals = [((float(b[0]), float(b[1])), (float(t[0]), float(t[1]))) for b, t in verticals]\n                try:\n                    self._tilts[pic] = tilt_from_verticals(verticals)\n                    self.verticals[pic] = verticals\n                except CalibrationError:\n                    pass\n            for seq, obs in (data.get(\"landmarks\") or {}).items():\n                obs = [{k: (o[k] if k == \"pic\" else float(o[k])) for k in keys} for o in obs]\n                if obs:\n                    self.landmarks[seq] = obs\n            for seq, obs in (data.get(\"heights\") or {}).items():\n                obs = [o for o in (_height_obs(o) for o in obs) if o is not None]\n                if obs:\n                    self.heights[seq] = obs\n            for pic, entry in (data.get(\"auto\") or {}).items():\n                entry = _auto_entry(entry)\n                if entry:\n                    self.auto[pic] = entry\n        except (TypeError, ValueError, KeyError, IndexError, AttributeError):\n            pass  # format abîmé : on garde ce qui a pu être lu\n\n    def merge(self, data):\n        \"\"\"Ajoute le calage enregistré `data` (dict de to_dict) pour les photos et séquences\n        qui n'en ont pas encore : le calage en cours, plus récent, l'emporte. Ne déclenche pas\n        `changed`. Retourne le nombre de photos et séquences ajoutées.\"\"\"\n        other = Calibration()\n        other.load(data)\n        added = 0\n        for mine, theirs in ((self.verticals, other.verticals), (self.landmarks, other.landmarks),\n                             (self.heights, other.heights), (self.auto, other.auto)):\n            for key, obs in theirs.items():\n                if key not in mine:\n                    mine[key] = obs\n                    added += 1\n        for pic, tilt in other._tilts.items():\n            self._tilts.setdefault(pic, tilt)\n        self._models, self._cameras = {}, {}\n        return added\n\n    # Inclinaison ---------------------------------------------------------\n    def add_vertical(self, pic, bottom, top):\n        verticals = self.verticals.get(pic, []) + [(bottom, top)]\n        result = tilt_from_verticals(verticals)  # lève CalibrationError sans rien garder\n        self.verticals[pic], self._tilts[pic] = verticals, result\n        self._notify()\n        return result\n\n    def tilt(self, pic):\n        \"\"\"Inclinaison de la photo (dict de tilt_from_verticals, avec sigma en degrés), ou None.\n        Dans l'ordre : calée à la main sur deux objets ou plus (source \"clics\") ; calée à la\n        main sur un objet et complétée par l'inclinaison automatique (\"clics + verticales\",\n        \"clics + lidar\") ; calculée d'après les verticales de la photo (\"verticales\") ;\n        estimée par le LiDAR HD (\"lidar\").\"\"\"\n        manual, auto = self._tilts.get(pic), self.auto_tilt(pic)\n        if manual and (not manual[\"partial\"] or auto is None):\n            return dict(manual, source=\"clics\")\n        if manual:\n            combined = tilt_from_verticals(self.verticals[pic], (auto[\"up\"], auto[\"sigma\"]))\n            return dict(combined, source=\"clics + \" + auto[\"source\"])\n        return auto\n\n    def manual_complete(self, pic):\n        \"\"\"Inclinaison calée à la main sur assez d'objets pour se passer du calcul automatique.\"\"\"\n        manual = self._tilts.get(pic)\n        return bool(manual) and not manual[\"partial\"]\n\n    def auto_tilt(self, pic):\n        \"\"\"Inclinaison automatique de la photo (verticales, sinon LiDAR HD), ou None.\"\"\"\n        entry = self.auto.get(pic)\n        if not entry:\n            return None\n        v = entry.get(\"verticals\")\n        if v:\n            up = tuple(v[\"up\"])\n            return {\"up\": up, \"tilt\": math.degrees(math.acos(min(1.0, up[2]))),\n                    \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360, \"residual\": None, \"partial\": False,\n                    \"count\": v[\"count\"], \"sigma\": v[\"sigma\"], \"source\": \"verticales\"}\n        model = self.lidar_model(entry.get(\"sequence\"))\n        if model and entry.get(\"lidar\"):\n            f = entry[\"lidar\"][0] + model[\"offset\"][0]\n            r = entry[\"lidar\"][1] + model[\"offset\"][1]\n            up = up_from_components(f, r, entry[\"heading\"])\n            return {\"up\": up, \"tilt\": math.hypot(f, r), \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n                    \"residual\": None, \"partial\": False, \"count\": model[\"count\"], \"sigma\": model[\"sigma\"],\n                    \"source\": \"lidar\"}\n        return None\n\n    def set_auto(self, pic, entry):\n        \"\"\"Inclinaison automatique de la photo (voir self.auto), enregistrée.\"\"\"\n        self.auto[pic] = entry\n        self._models.pop(entry.get(\"sequence\"), None)\n        self._notify()\n\n    def lidar_model(self, sequence):\n        \"\"\"Modèle LiDAR de la séquence (voir lidar_model), ou None.\"\"\"\n        if sequence is None:\n            return None\n        if sequence not in self._models:\n            self._models[sequence] = lidar_model([e for e in self.auto.values() if e.get(\"sequence\") == sequence])\n        return self._models[sequence]\n\n    def clear_tilt(self, pic):\n        self.verticals.pop(pic, None)\n        self._tilts.pop(pic, None)\n        self._notify()\n\n    def untilted(self, pic, yaw, elev):\n        t = self.tilt(pic)\n        return untilt(t[\"up\"], yaw, elev) if t else (yaw % 360, elev)\n\n    # Hauteur de caméra --------------------------------------------------------\n    def add_camera_height(self, sequence, kind, clicks, known):\n        \"\"\"Calage de la hauteur de caméra sur une longueur connue (clics corrigés du calage\n        actuel). Les clics bruts sont conservés : la hauteur est recalculée si l'inclinaison ou\n        le cap de la photo changent ensuite (voir camera).\"\"\"\n        h, sigma = camera_height(kind, clicks, known, self._tilt_sigma(clicks[0].get(\"pic\")))\n        keep = (\"pic\", \"sequence\", \"lon\", \"lat\", \"gps\", \"raw\", \"yaw\", \"elev\", \"profile\")\n        obs = {\"kind\": kind, \"known\": float(known),\n               \"clicks\": [{k: c[k] for k in keep if c.get(k) is not None} for c in clicks]}\n        self.heights.setdefault(sequence, []).append(obs)\n        self._notify()\n        return {\"height\": h, \"sigma\": sigma}\n\n    def _height_of(self, sequence, obs):\n        \"\"\"(hauteur, incertitude) d'un calage de la hauteur de caméra, avec le calage actuel.\"\"\"\n        if not isinstance(obs, dict):\n            return tuple(obs)\n        clicks = []\n        for c in obs[\"clicks\"]:\n            if c.get(\"raw\"):  # direction brute : corrigée du calage actuel\n                lon, lat = c.get(\"gps\") or (c[\"lon\"], c[\"lat\"])\n                yaw, elev = self.correct(c.get(\"pic\"), sequence, c[\"raw\"][0], c[\"raw\"][1], lon, lat)\n            else:  # direction déjà corrigée, figée\n                yaw, elev = c[\"yaw\"], c[\"elev\"]\n            clicks.append(dict(c, yaw=yaw, elev=elev))\n        try:\n            return camera_height(obs[\"kind\"], clicks, obs[\"known\"], self._tilt_sigma(clicks[0].get(\"pic\")))\n        except (CalibrationError, ground.GroundError):\n            return None\n\n    def _tilt_sigma(self, pic):\n        \"\"\"Incertitude (degrés) de l'inclinaison de la photo, UNCALIBRATED sans calage.\"\"\"\n        t = self.tilt(pic) if pic else None\n        return t[\"sigma\"] if t and t.get(\"sigma\") is not None else UNCALIBRATED\n\n    def camera(self, sequence):\n        \"\"\"Hauteur de caméra calée de la séquence : dict height, sigma, count, legacy (calages\n        d'une version précédente, figés), ou None.\"\"\"\n        obs_list = self.heights.get(sequence) or []\n        key = (id(obs_list), len(obs_list))  # calages ajoutés ou remplacés directement\n        if self._cameras.get(sequence, (None,))[0] == key:\n            return self._cameras[sequence][1]\n        values, legacy = [], 0\n        for o in obs_list:\n            v = self._height_of(sequence, o)\n            if v is not None:\n                values.append(v)\n                legacy += not isinstance(o, dict)\n        res = None\n        if values:\n            sw = sum(1.0 / s ** 2 for _, s in values)\n            res = {\"height\": sum(h / s ** 2 for h, s in values) / sw, \"sigma\": 1.0 / math.sqrt(sw),\n                   \"count\": len(values), \"legacy\": legacy}\n        self._cameras[sequence] = (key, res)\n        return res\n\n    def clear_camera(self, sequence):\n        self.heights.pop(sequence, None)\n        self._notify()\n\n    # Cap -------------------------------------------------------------------\n    def add_landmark(self, sequence, pic, lon, lat, yaw, elev, mlon, mlat, accuracy, survey):\n        \"\"\"Repère : clic (cap, élév. bruts) depuis la photo en (lon, lat), repère en (mlon, mlat).\"\"\"\n        obs = {\"pic\": pic, \"lon\": lon, \"lat\": lat, \"yaw\": yaw, \"elev\": elev, \"mlon\": mlon, \"mlat\": mlat,\n               \"accuracy\": DEFAULT_ACCURACY if accuracy is None else float(accuracy),\n               \"prior\": SURVEY_PRIOR if survey else PRIOR}\n        offset, sigma, dist = self._landmark_offset(obs)\n        if dist < MIN_LANDMARK:\n            raise CalibrationError(\"Repère à {} m de la photo : choisissez un repère plus éloigné.\".format(_fr(dist)))\n        # L'écart toléré tient compte du décalage de position GPS possible (repère proche)\n        if abs(offset) > MAX_OFFSET + math.degrees(math.atan2(2 * obs[\"accuracy\"], dist)):\n            raise CalibrationError(\"Écart de cap de {:.0f}° : ce n'est sûrement pas le même repère sur la \"\n                                   \"carte et dans la photo.\".format(offset))\n        others = self.landmarks.get(sequence, [])\n        if len(others) >= 3:\n            # Contrôle : direction du repère prédite par les autres repères seuls\n            pose = self._solve_pose(others)\n            yaw, _ = self.untilted(obs[\"pic\"], obs[\"yaw\"], obs[\"elev\"])\n            x, y = _local(obs[\"mlon\"], obs[\"mlat\"], obs[\"lon\"], obs[\"lat\"])\n            x, y = x - pose[\"shift\"][0], y - pose[\"shift\"][1]\n            r = abs((math.degrees(math.atan2(x, y)) - yaw - pose[\"offset\"] + 540) % 360 - 180)\n            spread = math.hypot(AIM_ERROR, math.degrees(math.atan2(MAP_ERROR, dist)), pose[\"sigma\"],\n                                math.degrees(math.atan2(pose[\"shift_sigma\"], dist)))\n            if r > max(1.0, OUTLIER * spread):\n                raise CalibrationError(\"Ce repère s'écarte de {}° de ce que prévoient les précédents : repère \"\n                                       \"mal pointé sur la carte ou dans la photo ?\".format(_fr(r)))\n        self.landmarks.setdefault(sequence, []).append(obs)\n        self._notify()\n        return {\"offset\": offset, \"sigma\": sigma, \"distance\": dist}\n\n    def _landmark_offset(self, obs):\n        \"\"\"(décalage de cap, précision, distance) d'un repère seul, avec l'inclinaison actuelle\n        et sans recalage de position.\"\"\"\n        yaw, _ = self.untilted(obs[\"pic\"], obs[\"yaw\"], obs[\"elev\"])\n        x, y = _local(obs[\"mlon\"], obs[\"mlat\"], obs[\"lon\"], obs[\"lat\"])\n        dist = math.hypot(x, y)\n        bearing = math.degrees(math.atan2(x, y))\n        offset = (bearing - yaw + 540) % 360 - 180\n        position = math.degrees(math.atan2(math.hypot(obs[\"accuracy\"], MAP_ERROR), max(dist, 1e-6)))\n        return offset, math.hypot(position, AIM_ERROR), dist\n\n    def _solve_pose(self, obs):\n        \"\"\"Relèvement : décalage de cap et de position communs aux photos des repères.\n\n        Moindres carrés (Gauss-Newton) sur (cap, est, nord), chaque inconnue gardant\n        son a priori : décalage de cap nul à ±prior, position GPS juste à ±accuracy.\n        Un repère corrige surtout le cap ; trois repères ou plus bien répartis autour\n        des photos recalent aussi la position.\n        \"\"\"\n        lon0 = sum(o[\"lon\"] for o in obs) / len(obs)\n        lat0 = sum(o[\"lat\"] for o in obs) / len(obs)\n        rows = []\n        for o in obs:\n            yaw, _ = self.untilted(o[\"pic\"], o[\"yaw\"], o[\"elev\"])\n            px, py = _local(o[\"lon\"], o[\"lat\"], lon0, lat0)\n            mx, my = _local(o[\"mlon\"], o[\"mlat\"], lon0, lat0)\n            dist = max(math.hypot(mx - px, my - py), 1e-6)\n            sigma = math.radians(math.hypot(AIM_ERROR, math.degrees(math.atan2(MAP_ERROR, dist))))\n            rows.append((px, py, mx, my, math.radians(yaw), 1.0 / sigma ** 2))\n        prior = (1.0 / math.radians(obs[0][\"prior\"]) ** 2,\n                 1.0 / obs[0][\"accuracy\"] ** 2, 1.0 / obs[0][\"accuracy\"] ** 2)\n        p = [0.0, 0.0, 0.0]  # décalage de cap (radians), décalage de position est, nord (m)\n\n        def residuals(p):\n            out = []\n            for px, py, mx, my, yaw, w in rows:\n                dx, dy = mx - px - p[1], my - py - p[2]\n                r = (math.atan2(dx, dy) - yaw - p[0] + 3 * math.pi) % (2 * math.pi) - math.pi\n                d2 = dx * dx + dy * dy\n                out.append((r, (-1.0, -dy / d2, dx / d2), w))\n            return out\n\n        for _ in range(10):\n            n = [[prior[i] if i == j else 0.0 for j in range(3)] for i in range(3)]\n            g = [-prior[i] * p[i] for i in range(3)]\n            for r, jac, w in residuals(p):\n                for i in range(3):\n                    g[i] -= w * jac[i] * r\n                    for j in range(3):\n                        n[i][j] += w * jac[i] * jac[j]\n            cov = _inverse3(n)\n            step = [sum(cov[i][j] * g[j] for j in range(3)) for i in range(3)]\n            p = [p[i] + step[i] for i in range(3)]\n            if max(abs(step[0]) * 1e3, abs(step[1]), abs(step[2])) < 1e-6:\n                break\n        res = residuals(p)\n        # Grand axe de l'ellipse d'incertitude de la position\n        a, b, c = cov[1][1], cov[1][2], cov[2][2]\n        major = math.sqrt(max((a + c) / 2 + math.sqrt(((a - c) / 2) ** 2 + b * b), 0.0))\n        return {\n            \"offset\": math.degrees(p[0]), \"sigma\": math.degrees(math.sqrt(cov[0][0])),\n            \"shift\": (p[1], p[2]), \"shift_sigma\": major,\n            # Position recalée : trois repères au moins, et nettement mieux connue qu'au GPS\n            \"positioned\": len(obs) >= 3 and major < 0.7 * obs[0][\"accuracy\"],\n            \"residual\": math.degrees(math.sqrt(sum(r * r for r, _, _ in res) / len(res))),\n            \"residuals\": [math.degrees(r) for r, _, _ in res],\n            \"count\": len(obs), \"prior\": obs[0][\"prior\"], \"accuracy\": obs[0][\"accuracy\"],\n            \"photos\": [(o[\"lon\"], o[\"lat\"]) for o in obs],\n        }\n\n    def pose(self, sequence, lon=None, lat=None):\n        \"\"\"Recalage de la séquence (voir _solve_pose), ou None. Avec (lon, lat), None aussi\n        si la photo est à plus de REACH m des photos qui ont servi au recalage : la dérive\n        du GPS au fil de la séquence le rendrait faux.\"\"\"\n        obs = self.landmarks.get(sequence) if sequence else None\n        if not obs:\n            return None\n        result = self._solve_pose(obs)\n        if lon is not None and lat is not None:\n            if min(math.hypot(*_local(lon, lat, plon, plat)) for plon, plat in result[\"photos\"]) > REACH:\n                return None\n        return result\n\n    def clear_heading(self, sequence):\n        self.landmarks.pop(sequence, None)\n        self._notify()\n\n    # Application -----------------------------------------------------------\n    def correct(self, pic, sequence, yaw, elev, lon=None, lat=None):\n        \"\"\"Direction corrigée (inclinaison de la photo, puis cap de la séquence).\"\"\"\n        yaw, elev = self.untilted(pic, yaw, elev)\n        pose = self.pose(sequence, lon, lat)\n        if pose:\n            yaw = (yaw + pose[\"offset\"]) % 360\n        return yaw, elev\n\n    def position(self, sequence, lon, lat):\n        \"\"\"Position recalée de la photo : (lon, lat, précision en m), ou None si la\n        position n'a pas été recalée (moins de trois repères bien répartis).\"\"\"\n        pose = self.pose(sequence, lon, lat)\n        if not pose or not pose[\"positioned\"]:\n            return None\n        sx, sy = pose[\"shift\"]\n        lon, lat = offset(lon, lat, math.degrees(math.atan2(sx, sy)), math.hypot(sx, sy))\n        return lon, lat, pose[\"shift_sigma\"]\n\n    def heading_error(self, sequence, lon=None, lat=None):\n        \"\"\"Erreur de visée (degrés) d'une séquence recalée, ou None si elle ne l'est pas.\"\"\"\n        pose = self.pose(sequence, lon, lat)\n        return math.hypot(pose[\"sigma\"], AIM_ERROR) if pose else None\n\n\ndef _height_obs(o):\n    \"\"\"Calage de la hauteur de caméra relu (voir Calibration.heights), ou None si illisible.\"\"\"\n    try:\n        if isinstance(o, dict):\n            clicks = []\n            for c in o[\"clicks\"]:\n                clicks.append({\n                    \"pic\": c.get(\"pic\"), \"sequence\": c.get(\"sequence\"),\n                    \"lon\": float(c[\"lon\"]), \"lat\": float(c[\"lat\"]),\n                    \"gps\": [float(v) for v in c[\"gps\"]] if c.get(\"gps\") else None,\n                    \"raw\": [float(c[\"raw\"][0]), float(c[\"raw\"][1])] if c.get(\"raw\") else None,\n                    \"yaw\": float(c[\"yaw\"]) if c.get(\"yaw\") is not None else None,\n                    \"elev\": float(c[\"elev\"]) if c.get(\"elev\") is not None else None,\n                    \"profile\": [(float(d), float(z)) for d, z in c[\"profile\"]] if c.get(\"profile\") else None})\n            if o.get(\"kind\") not in (\"ground\", \"height\") or len(clicks) != 2 or float(o[\"known\"]) <= 0:\n                return None\n            if any(c[\"raw\"] is None and (c[\"yaw\"] is None or c[\"elev\"] is None) for c in clicks):\n                return None\n            return {\"kind\": o[\"kind\"], \"known\": float(o[\"known\"]), \"clicks\": clicks}\n        h, s = float(o[0]), float(o[1])\n        return (h, s) if s > 0 else None\n    except (TypeError, ValueError, KeyError, IndexError, AttributeError):\n        return None\n\n\ndef _auto_entry(entry):\n    \"\"\"Inclinaison automatique relue (voir Calibration.auto), ou None si illisible.\"\"\"\n    try:\n        out = {\"sequence\": entry.get(\"sequence\"), \"heading\": float(entry[\"heading\"]), \"verticals\": None,\n               \"lidar\": None}\n        v = entry.get(\"verticals\")\n        if v:\n            up = _unit(tuple(float(c) for c in v[\"up\"]))\n            out[\"verticals\"] = {\"up\": list(up), \"count\": int(v[\"count\"]), \"sigma\": float(v[\"sigma\"])}\n        if entry.get(\"lidar\"):\n            out[\"lidar\"] = [float(entry[\"lidar\"][0]), float(entry[\"lidar\"][1])]\n        return out\n    except (TypeError, ValueError, KeyError, IndexError, AttributeError, ZeroDivisionError):\n        return None\n\n\ndef _inverse3(m):\n    \"\"\"Inverse d'une matrice 3×3 (symétrique définie positive ici).\"\"\"\n    a, b, c = m[0]\n    d, e, f = m[1]\n    g, h, i = m[2]\n    co = [[e * i - f * h, -(d * i - f * g), d * h - e * g],\n          [-(b * i - c * h), a * i - c * g, -(a * h - b * g)],\n          [b * f - c * e, -(a * f - c * d), a * e - b * d]]\n    det = a * co[0][0] + b * co[0][1] + c * co[0][2]\n    return [[co[j][i] / det for j in range(3)] for i in range(3)]\n",
 "core/capture.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Capture « virtuelle » Full HD de la vue affichée : calcul de l'image.\n\nPlutôt qu'une capture d'écran (limitée à la taille du panneau), on recalcule la\nvue à partir de la photo originale en haute définition, avec le même cadrage\nque la visionneuse : cap, inclinaison et champ de vision.\n\n- Photo 360° (équirectangulaire) : projection perspective de la sphère.\n- Photo classique : reprojection de l'image plane selon la vue demandée.\n\nTableaux numpy RGB (numpy importé à l'usage : le cœur s'importe sans lui). Décodage,\ncartouche et enregistrement : hôte (capture.py du plugin, page web).\n\"\"\"\n\nimport math\nimport re\n\nOUT_W, OUT_H = 1920, 1080\nBACKGROUND = (40, 40, 40)\n\n\ndef _view_rays(heading, pitch, vfov, width, height):\n    \"\"\"Directions (unitaires) de chaque pixel de la vue, en repère monde.\n\n    Repère : x = est, y = haut, z = nord. heading en degrés (0 = nord),\n    pitch en degrés (positif = vers le haut), vfov = champ vertical en degrés.\n    \"\"\"\n    import numpy as np\n\n    f = (height / 2.0) / math.tan(math.radians(vfov) / 2.0)\n    u = (np.arange(width, dtype=np.float64) + 0.5 - width / 2.0) / f\n    v = (height / 2.0 - np.arange(height, dtype=np.float64) - 0.5) / f\n    x, y = np.meshgrid(u, v)\n    z = np.ones_like(x)\n    # inclinaison (rotation autour de l'axe x)\n    p = math.radians(pitch)\n    y2 = y * math.cos(p) + z * math.sin(p)\n    z2 = -y * math.sin(p) + z * math.cos(p)\n    # cap (rotation autour de l'axe vertical, sens horaire depuis le nord)\n    h = math.radians(heading)\n    x3 = x * math.cos(h) + z2 * math.sin(h)\n    z3 = -x * math.sin(h) + z2 * math.cos(h)\n    n = np.sqrt(x3 * x3 + y2 * y2 + z3 * z3)\n    return x3 / n, y2 / n, z3 / n\n\n\ndef _bilinear(src, xs, ys, valid=None):\n\n    import numpy as np\n    h, w, _ = src.shape\n    x0 = np.floor(xs).astype(np.int64)\n    y0 = np.floor(ys).astype(np.int64)\n    fx = (xs - x0)[..., None]\n    fy = (ys - y0)[..., None]\n    x1, y1 = x0 + 1, y0 + 1\n    if valid is None:  # 360° : bouclage horizontal\n        x0 %= w\n        x1 %= w\n    else:\n        x0 = np.clip(x0, 0, w - 1)\n        x1 = np.clip(x1, 0, w - 1)\n    y0 = np.clip(y0, 0, h - 1)\n    y1 = np.clip(y1, 0, h - 1)\n    s = src.astype(np.float32)\n    out = (s[y0, x0] * (1 - fx) * (1 - fy) + s[y0, x1] * fx * (1 - fy)\n           + s[y1, x0] * (1 - fx) * fy + s[y1, x1] * fx * fy)\n    if valid is not None:\n        out[~valid] = BACKGROUND\n    return out\n\n\ndef _tilted_rays(dx, dy, dz, up):\n    \"\"\"Directions vraies (x = est, y = haut, z = nord) exprimées dans le repère d'une caméra\n    penchée dont la verticale vraie est `up` (est, nord, haut ; voir core/calibration.py) : rotation\n    qui amène le zénith sur up, inverse de calibration.untilt.\"\"\"\n    ux, uy, uz = up\n    s = math.hypot(ux, uy)\n    if s < 1e-12:\n        return dx, dy, dz\n    kx, ky = -uy / s, ux / s  # zénith × up, normé\n    c = uz\n    ve, vn, vu = dx, dz, dy\n    kv = kx * ve + ky * vn\n    re = ve * c + (ky * vu) * s + kx * kv * (1 - c)\n    rn = vn * c + (-kx * vu) * s + ky * kv * (1 - c)\n    ru = vu * c + (kx * vn - ky * ve) * s\n    return re, ru, rn\n\n\ndef render_view(src, azimuth, is360, heading, pitch, vfov, photo_hfov=None,\n                width=OUT_W, height=OUT_H, up=None):\n    \"\"\"Calcule la vue (tableau numpy RGB) à partir de la photo source. up : verticale vraie de\n    la photo (calage de l'inclinaison), pour une vue redressée (verticales verticales).\"\"\"\n    import numpy as np\n\n    dx, dy, dz = _view_rays(heading, pitch, vfov, width, height)\n    if up is not None:\n        dx, dy, dz = _tilted_rays(dx, dy, dz, up)\n    sh, sw, _ = src.shape\n    a = math.radians(azimuth or 0.0)\n    # Directions exprimées dans le repère de la photo (centre de l'image = azimut)\n    px = dx * math.cos(a) - dz * math.sin(a)\n    pz = dx * math.sin(a) + dz * math.cos(a)\n    py = dy\n    if is360:\n        lon = np.arctan2(px, pz)  # -pi..pi, 0 = centre de l'image\n        lat = np.arcsin(np.clip(py, -1, 1))\n        xs = (lon / (2 * math.pi) + 0.5) * sw - 0.5\n        ys = (0.5 - lat / math.pi) * sh - 0.5\n        return _bilinear(src, xs, ys)\n    # Photo classique : plan image perpendiculaire à l'axe de prise de vue\n    hfov = photo_hfov or 70.0\n    f = (sw / 2.0) / math.tan(math.radians(hfov) / 2.0)\n    with np.errstate(divide=\"ignore\", invalid=\"ignore\"):\n        xs = sw / 2.0 + f * px / pz - 0.5\n        ys = sh / 2.0 - f * py / pz - 0.5\n    valid = (pz > 1e-6) & (xs >= 0) & (xs <= sw - 1) & (ys >= 0) & (ys <= sh - 1)\n    xs = np.where(valid, xs, 0)\n    ys = np.where(valid, ys, 0)\n    return _bilinear(src, xs, ys, valid)\n\n\ndef caption_for(item, heading):\n    \"\"\"Texte d'attribution : auteur, date, cap, licence (obligation des licences Panoramax).\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    providers = props.get(\"providers\") or item.get(\"providers\") or []\n    names = [p.get(\"name\") for p in providers if isinstance(p, dict) and p.get(\"name\")]\n    author = names[0] if names else None\n    date = (props.get(\"datetime\") or \"\")[:10]\n    lic = license_name(item)\n    parts = [\"Panoramax\"]\n    if author:\n        parts.append(\"© \" + author)\n    if date:\n        parts.append(date)\n    if heading is not None:\n        parts.append(\"cap {:.0f}°\".format(heading % 360))\n    if lic:\n        parts.append(str(lic))\n    return \"  ·  \".join(parts)\n\n\ndef license_name(item):\n    \"\"\"Licence de la photo, réduite à sa catégorie (« etalab-2.0 », « CC-BY-SA-4.0 ») : champ\n    license de la fiche, sinon le code entre parenthèses du titre du lien (« License for this\n    object (etalab-2.0) »), sinon d'après l'adresse de la licence. None si inconnue.\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    lic = props.get(\"license\") or item.get(\"license\")\n    if lic and lic != \"proprietary\":\n        return str(lic)\n    for link in item.get(\"links\", []) or []:\n        if link.get(\"rel\") == \"license\":\n            title = link.get(\"title\") or \"\"\n            code = re.search(r\"\\(([^()]+)\\)\\s*$\", title)\n            return code.group(1) if code else (title or _license_label(link.get(\"href\", \"\")))\n    return str(lic) if lic else None\n\n\ndef _license_label(href):\n    h = href.lower()\n    if \"by-sa/4.0\" in h:\n        return \"CC BY-SA 4.0\"\n    if \"by/4.0\" in h:\n        return \"CC BY 4.0\"\n    if \"etalab\" in h or \"licence-ouverte\" in h:\n        return \"Licence Ouverte 2.0\"\n    return href\n",
 "core/filters.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Filtre des photos : date, type de caméra, précision GPS, producteur.\n\nLe même filtre s'applique au filaire (expressions sur les attributs des tuiles\nvectorielles, voir layers.apply_filter) et aux photos ouvertes par un clic sur la\ncarte (propriétés des fiches STAC, voir PhotoFilter.matches). Mémorisation : hôte (filters.py\ndu plugin, page web).\n\nAttributs des tuiles Panoramax utilisés :\n- séquences : date (AAAA-MM-JJ), type, gps_accuracy, account_id ;\n- photos : ts (AAAA-MM-JJ hh:mm:ss…), type, gps_accuracy, account_id ;\n- grille de densité (petites échelles) : nb_360_pictures, nb_flat_pictures, seul le\n  type de caméra y est filtrable.\n\"\"\"\n\nKINDS = ((\"Tous types\", None), (\"360°\", \"360\"), (\"Classiques\", \"flat\"))\nGPS_LIMITS = ((\"Toute précision GPS\", None), (\"GPS ≤ 2 m (relevé)\", 2.0), (\"GPS ≤ 4 m\", 4.0))\nTILE_TYPES = {\"360\": \"equirectangular\", \"flat\": \"flat\"}\n\n\ndef _quote(text):\n    return \"'{}'\".format(str(text).replace(\"'\", \"''\"))\n\n\nclass PhotoFilter:\n    \"\"\"Critères du filtre ; None : critère inactif.\n\n    since : date minimale \"AAAA-MM-JJ\" ; kind : \"360\" ou \"flat\" ; max_gps : précision\n    GPS maximale (m) ; producer : (identifiant du compte, nom) du producteur.\"\"\"\n\n    def __init__(self, since=None, kind=None, max_gps=None, producer=None):\n        self.since, self.kind, self.max_gps, self.producer = since, kind, max_gps, producer\n\n    def __eq__(self, other):\n        return isinstance(other, PhotoFilter) and vars(self) == vars(other)\n\n    def active(self):\n        return any(v is not None for v in vars(self).values())\n\n    # Filaire ------------------------------------------------------------------\n    def tile_expression(self, layer):\n        \"\"\"Expression QGIS du filtre pour une couche des tuiles (\"sequences\", \"pictures\",\n        \"grid\"), ou \"\" si rien n'y est à filtrer.\"\"\"\n        parts = []\n        if layer == \"grid\":\n            if self.kind == \"360\":\n                parts.append('\"nb_360_pictures\" > 0')\n            elif self.kind == \"flat\":\n                parts.append('\"nb_flat_pictures\" > 0')\n            return \" AND \".join(parts)\n        if self.since:\n            parts.append('\"{}\" >= {}'.format(\"date\" if layer == \"sequences\" else \"ts\", _quote(self.since)))\n        if self.kind:\n            parts.append('\"type\" = {}'.format(_quote(TILE_TYPES[self.kind])))\n        if self.max_gps is not None:\n            parts.append('to_real(\"gps_accuracy\") <= {}'.format(self.max_gps))\n        if self.producer:\n            parts.append('\"account_id\" = {}'.format(_quote(self.producer[0])))\n        return \" AND \".join(parts)\n\n    # Fiches STAC --------------------------------------------------------------\n    def matches(self, item):\n        \"\"\"La photo (fiche STAC de l'API) passe-t-elle le filtre ? Une date, une précision GPS\n        ou un producteur absents de la fiche font refuser la photo pour ce critère.\"\"\"\n        props = item.get(\"properties\") or {}\n        if self.since and str(props.get(\"datetime\") or \"\")[:10] < self.since:\n            return False\n        if self.kind:  # angle de vue souvent absent des photos classiques (téléphones) : 360 seulement si déclaré\n            fov = (props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\") or 0\n            if (float(fov) >= 360) != (self.kind == \"360\"):\n                return False\n        if self.max_gps is not None:\n            gps = props.get(\"quality:horizontal_accuracy\")\n            if gps is None or float(gps) > self.max_gps:\n                return False\n        if self.producer:\n            ids = {p.get(\"id\") for p in item.get(\"providers\") or props.get(\"providers\") or []}\n            if self.producer[0] not in ids:\n                return False\n        return True\n\n    def describe(self):\n        \"\"\"Résumé du filtre, pour les messages (\"\" s'il est inactif).\"\"\"\n        parts = []\n        if self.since:\n            parts.append(\"depuis le {}\".format(\"/\".join(reversed(self.since.split(\"-\")))))\n        if self.kind:\n            parts.append(dict((v, k) for k, v in KINDS)[self.kind].lower())\n        if self.max_gps is not None:\n            parts.append(\"GPS ≤ {} m\".format(str(self.max_gps).rstrip(\"0\").rstrip(\".\").replace(\".\", \",\")))\n        if self.producer:\n            parts.append(\"producteur « {} »\".format(self.producer[1]))\n        return \", \".join(parts)\n\n\ndef item_producer(item):\n    \"\"\"(identifiant du compte, nom) du producteur de la photo, ou None.\"\"\"\n    for p in (item or {}).get(\"providers\") or ((item or {}).get(\"properties\") or {}).get(\"providers\") or []:\n        if \"producer\" in (p.get(\"roles\") or []) and p.get(\"id\"):\n            return p[\"id\"], p.get(\"name\") or p[\"id\"]\n    return None\n",
 "core/geometry.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Points 3D à partir des clics, pour les mesures (voir measures.py).\n\nUn clic ne donne qu'une direction ; le point 3D est l'intersection du rayon de\nvisée avec une surface :\n- le terrain (même calcul que les mesures au sol, voir ground.py) ;\n- un plan vertical : face à la caméra et passant par le pied de l'objet (hauteur),\n  ou celui d'une façade du cadastre (voir buildings.py).\n\nRepère local (est, nord, altitude) en mètres, centré sur un point de référence\n(lon0, lat0). La caméra est à la position (recalée) de la photo, à la hauteur de\ncaméra au-dessus du sol sous la photo, donné par le profil de terrain du clic.\nLes mesures sont ensuite des calculs sur ces points : distance 3D et sa\ndécomposition (horizontale, verticale, le long de la route et en travers).\nModule sans dépendance à QGIS, pour pouvoir être testé seul.\n\"\"\"\n\nimport math\n\nfrom . import ground\nfrom .triangulation import _geographic, _local\n\nMAX_RANGE = 100.0  # portée maximale d'un point sur un plan (m)\nGRAZING = 15.0  # en dessous de cet angle d'incidence sur un plan, la mesure devient imprécise\n\n\nclass GeometryError(ValueError):\n    \"\"\"Clic inexploitable (message destiné à l'utilisateur).\"\"\"\n\n\ndef direction(yaw, elev):\n    \"\"\"Vecteur unitaire (est, nord, haut) d'une direction en degrés.\"\"\"\n    y, e = math.radians(yaw), math.radians(elev)\n    return (math.sin(y) * math.cos(e), math.cos(y) * math.cos(e), math.sin(e))\n\n\ndef to_local(lon, lat, z, origin):\n    x, y = _local(lon, lat, origin[0], origin[1])\n    return (x, y, z)\n\n\ndef to_geographic(p, origin):\n    lon, lat = _geographic(p[0], p[1], origin[0], origin[1])\n    return lon, lat, p[2]\n\n\ndef camera(click, camera_height, origin, ground_z=None):\n    \"\"\"Centre optique (repère local) et direction de visée d'un clic. ground_z : altitude\n    du sol sous la photo, à donner pour qu'elle soit la même pour tous les clics d'une\n    photo (celle du profil du clic dépend de la direction visée).\"\"\"\n    if ground_z is None:\n        ground_z = (click.get(\"profile\") or ground.flat_profile())[0][1]\n    x, y = _local(click[\"lon\"], click[\"lat\"], origin[0], origin[1])\n    return (x, y, ground_z + camera_height), direction(click[\"yaw\"], click[\"elev\"])\n\n\ndef on_ground(click, camera_height, origin, ground_z=None):\n    \"\"\"Point au sol (rayon ∩ terrain), comme ground._ground_point. ground_z : altitude du sol\n    sous la photo, la même pour tous ses clics (voir ground.anchored et camera).\"\"\"\n    profile = ground.anchored(click.get(\"profile\") or ground.flat_profile(), ground_z)\n    s, z = ground.intersect(profile, camera_height, click[\"elev\"])\n    x, y = _local(click[\"lon\"], click[\"lat\"], origin[0], origin[1])\n    a = math.radians(click[\"yaw\"])\n    return (x + s * math.sin(a), y + s * math.cos(a), z), 90.0\n\n\ndef on_plane(click, camera_height, origin, point, normal, ground_z=None):\n    \"\"\"Point sur le plan (point, normale). Retourne (point, angle d'incidence en degrés).\"\"\"\n    c, u = camera(click, camera_height, origin, ground_z)\n    nu = sum(n * v for n, v in zip(normal, u))\n    if abs(nu) < 1e-6:\n        raise GeometryError(\"Visée parallèle au plan : cliquez un point plus face à la caméra.\")\n    t = sum(n * (p - q) for n, p, q in zip(normal, point, c)) / nu\n    if t <= 0.1:\n        raise GeometryError(\"Le point visé est derrière le plan de mesure : vérifiez la surface choisie.\")\n    if t * math.hypot(u[0], u[1]) > MAX_RANGE:\n        raise GeometryError(\"Point à plus de {:.0f} m sur le plan de mesure : visez plus près.\".format(MAX_RANGE))\n    norm = math.sqrt(sum(n * n for n in normal))\n    return tuple(q + t * v for q, v in zip(c, u)), math.degrees(math.asin(min(1.0, abs(nu) / norm)))\n\n\ndef vertical_plane(a, b):\n    \"\"\"Plan vertical passant par deux points (repère local) : (point, normale horizontale).\"\"\"\n    dx, dy = b[0] - a[0], b[1] - a[1]\n    if math.hypot(dx, dy) < 0.2:\n        raise GeometryError(\"Les deux points de la façade sont trop proches : cliquez ses deux extrémités.\")\n    return a, (-dy, dx, 0.0)\n\n\ndef facing_plane(cam, point):\n    \"\"\"Plan vertical passant par `point`, face à la caméra (normale horizontale vers elle).\"\"\"\n    dx, dy = point[0] - cam[0], point[1] - cam[1]\n    if math.hypot(dx, dy) < 0.1:\n        raise GeometryError(\"Point trop proche de la caméra.\")\n    return point, (dx, dy, 0.0)\n\n\ndef decompose(p, q, axis=None):\n    \"\"\"Distance de p à q : dict d3, horizontal, vertical (q − p), along et across (le long\n    de l'axe de la route et en travers, si l'axe est connu).\"\"\"\n    dx, dy, dz = q[0] - p[0], q[1] - p[1], q[2] - p[2]\n    out = {\"d3\": math.sqrt(dx * dx + dy * dy + dz * dz), \"horizontal\": math.hypot(dx, dy), \"vertical\": dz,\n           \"along\": None, \"across\": None}\n    if axis is not None:\n        ax, ay = math.sin(math.radians(axis)), math.cos(math.radians(axis))\n        out[\"along\"] = abs(dx * ax + dy * ay)\n        out[\"across\"] = abs(dx * ay - dy * ax)\n    return out\n",
 "core/ground.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Mesures sur une photo par lancer de rayon sur le terrain.\n\nLa caméra est à une hauteur connue au-dessus du sol. Un clic donne une\ndirection (cap, élévation) ; on suit ce rayon jusqu'à ce qu'il passe sous le\nterrain, décrit par un profil d'altitudes le long de la visée (MNT ou service\nd'altimétrie). Sans profil, le sol est supposé plat et horizontal. On en déduit\nla position des points au sol (utilisée par geometry.py pour toutes les mesures)\net la hauteur d'un objet, pied puis sommet (utilisée par le calage de la hauteur\nde caméra, avec le même modèle que les mesures).\n\nLa précision chute vite avec la distance (une erreur d'inclinaison de 0,5°\ndéplace un point situé à 15 m de plus d'un mètre) : réservé aux objets proches.\nModule sans dépendance à QGIS, pour pouvoir être testé seul.\n\"\"\"\n\nimport math\n\nfrom .triangulation import offset\n\nPITCH_ERROR = 0.5  # erreur d'inclinaison supposée (degrés) pour l'incertitude affichée\nMAX_DISTANCE = 60.0  # longueur du profil de terrain et portée maximale d'une mesure\nFLAT = \"sol plat\"\n\n\nclass GroundError(ValueError):\n    \"\"\"Clic inexploitable (message destiné à l'utilisateur).\"\"\"\n\n\ndef view_direction(heading, pitch, vfov, dx, dy, height_px):\n    \"\"\"Direction (cap, élévation en degrés) d'un pixel de la vue.\n\n    heading/pitch : orientation du centre de la vue ; vfov : champ vertical ;\n    dx, dy : décalage du pixel par rapport au centre (dy vers le bas) ;\n    height_px : hauteur de la vue en pixels. Même modèle que capture._view_rays.\n    \"\"\"\n    f = (height_px / 2.0) / math.tan(math.radians(vfov) / 2.0)\n    u, v = dx / f, -dy / f\n    p = math.radians(pitch)\n    y = v * math.cos(p) + math.sin(p)\n    z = -v * math.sin(p) + math.cos(p)\n    h = math.radians(heading)\n    x2 = u * math.cos(h) + z * math.sin(h)\n    z2 = -u * math.sin(h) + z * math.cos(h)\n    return math.degrees(math.atan2(x2, z2)) % 360, math.degrees(math.atan2(y, math.hypot(x2, z2)))\n\n\ndef flat_profile():\n    \"\"\"Profil d'un sol plat et horizontal (altitude relative 0).\"\"\"\n    return [(0.0, 0.0), (MAX_DISTANCE, 0.0)]\n\n\ndef intersect(profile, camera_height, elevation):\n    \"\"\"Premier point où le rayon passe sous le terrain.\n\n    profile : [(distance horizontale en m, altitude du terrain)], trié, depuis 0\n    (sous la caméra). Retourne (distance, altitude du sol). Le terrain est\n    linéaire entre deux échantillons : l'intersection y est exacte.\n    \"\"\"\n    z_cam = profile[0][1] + camera_height\n    slope = math.tan(math.radians(elevation))\n    prev_s, prev_f = profile[0][0], camera_height\n    for s, z in profile[1:]:\n        f = z_cam + s * slope - z  # hauteur du rayon au-dessus du terrain\n        if f <= 0:\n            s_hit = prev_s + (s - prev_s) * prev_f / (prev_f - f)\n            k = (s_hit - prev_s) / (s - prev_s) if s > prev_s else 0.0\n            z_prev = z_cam + prev_s * slope - prev_f\n            return s_hit, z_prev + k * (z - z_prev)\n        prev_s, prev_f = s, f\n    raise GroundError(\"Le point visé ne touche pas le sol dans les {:.0f} m : cliquez sur le sol, \"\n                      \"plus près de la photo.\".format(MAX_DISTANCE))\n\n\ndef anchored(profile, ground_z):\n    \"\"\"Profil décalé verticalement pour que le sol sous la caméra soit à ground_z.\n\n    Le profil d'un clic est la droite de pente du terrain dans la direction visée : son\n    altitude sous la caméra varie d'une direction à l'autre (quelques décimètres). Tous les\n    clics d'une même photo doivent partir de la même caméra : sinon chaque point est calculé\n    depuis une hauteur différente, ce qui fausse les dénivelés et décale son repère dans la\n    visionneuse. ground_z None : profil inchangé.\"\"\"\n    if ground_z is None:\n        return profile\n    dz = ground_z - profile[0][1]\n    return [(s, z + dz) for s, z in profile]\n\n\ndef _ground_point(camera_height, click, ground_z=None):\n    s, z = intersect(anchored(click.get(\"profile\") or flat_profile(), ground_z), camera_height, click[\"elev\"])\n    return s, offset(click[\"lon\"], click[\"lat\"], click[\"yaw\"], s), z\n\n\ndef _spread(fn, clicks):\n    \"\"\"Écart maximal du résultat quand chaque élévation varie de ±PITCH_ERROR.\"\"\"\n    ref = fn(clicks)\n    worst = 0.0\n    for i in range(len(clicks)):\n        for sign in (-1, 1):\n            moved = [dict(c) for c in clicks]\n            moved[i][\"elev\"] += sign * PITCH_ERROR\n            try:\n                worst = max(worst, abs(fn(moved) - ref))\n            except GroundError:\n                return float(\"inf\")\n    return worst\n\n\nMAX_TOP_OFFSET = 45.0  # écart de cap maximal entre le pied et le sommet d'un objet (degrés)\n\n\ndef measure_height(camera_height, base, top):\n    \"\"\"Hauteur d'un objet : clic au pied (au sol) puis au sommet, sur la même photo.\n\n    Le sommet est pris dans le plan vertical face à la caméra qui passe par le pied :\n    pour un objet fin (poteau), c'est à la même distance que le pied ; pour un mur\n    face à la caméra, le sommet peut être cliqué un peu de côté. Même modèle que\n    measures.py (plan vertical face à la caméra, voir geometry.py).\n    \"\"\"\n    if base.get(\"pic\") != top.get(\"pic\"):\n        raise GroundError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n    profile = base.get(\"profile\") or flat_profile()\n\n    def height(clicks):\n        b, t = clicks\n        s, z_ground = intersect(profile, camera_height, b[\"elev\"])\n        offset_angle = (t[\"yaw\"] - b[\"yaw\"] + 540) % 360 - 180\n        if abs(offset_angle) > MAX_TOP_OFFSET:\n            raise GroundError(\"Le sommet est trop à côté du pied : cliquez-le au-dessus du pied.\")\n        reach = s / math.cos(math.radians(offset_angle))  # distance horizontale jusqu'au plan\n        z_top = profile[0][1] + camera_height + reach * math.tan(math.radians(t[\"elev\"]))\n        return z_top - z_ground\n\n    d, p, _ = _ground_point(camera_height, base)\n    h = height([base, top])\n    if h <= 0:\n        raise GroundError(\"Le sommet est sous le pied : cliquez d'abord au pied, puis au sommet.\")\n    return {\"points\": [p], \"ranges\": [d], \"value\": h, \"uncertainty\": _spread(height, [base, top])}\n",
 "core/host.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Services que l'application hôte fournit au cœur de calcul (voir install).\n\n- fetch(url, callback, prefer_cache=False, timeout_ms=None) : GET asynchrone,\n  callback(octets | None, erreur | None) ; peut renvoyer un objet ayant abort() ;\n- fetch_json(url, callback, prefer_cache=False, timeout_ms=None) : idem, callback(objet JSON\n  | None, erreur | None) ;\n- ngf_altitude(lon, lat, ellipsoïdale) : altitude NGF-IGN69 (grille RAF20), ou None ;\n- decode_band(octets, largeur, élévation min, élévation max) : photo équirectangulaire\n  décodée en niveaux de gris, réduite à `largeur` et rognée à la bande d'élévations\n  (tableau numpy, première ligne, hauteur et largeur de l'image entière), ou None ;\n- run_task(fonction, arguments, done) : calcul en arrière-plan, puis done(résultat ou None) ;\n- api_url : API Panoramax de l'instance choisie.\n\nPlugin QGIS : qgis_host.py ; application web : réseau du navigateur, décodage par canvas.\nLes valeurs par défaut rendent le cœur utilisable sans hôte (tests) : pas de réseau, pas\nd'altitude NGF, calcul immédiat.\n\"\"\"\n\napi_url = \"https://api.panoramax.xyz/api\"\n\n\ndef fetch(url, callback, prefer_cache=False, timeout_ms=None):\n    callback(None, \"pas d'accès réseau\")\n\n\ndef fetch_json(url, callback, prefer_cache=False, timeout_ms=None):\n    callback(None, \"pas d'accès réseau\")\n\n\ndef ngf_altitude(lon, lat, ellipsoidal):\n    return None\n\n\ndef decode_band(data, width, elev_min, elev_max):\n    return None\n\n\ndef run_task(function, args, done):\n    try:\n        result = function(*args)\n    except Exception:  # calcul raté : même effet qu'un résultat vide\n        result = None\n    done(result)\n\n\nSERVICES = (\"fetch\", \"fetch_json\", \"ngf_altitude\", \"decode_band\", \"run_task\", \"api_url\")\n\n\ndef install(**services):\n    \"\"\"Remplace les services par ceux de l'hôte (noms : SERVICES).\"\"\"\n    unknown = set(services) - set(SERVICES)\n    if unknown:\n        raise ValueError(\"services inconnus : {}\".format(\", \".join(sorted(unknown))))\n    globals().update(services)\n",
 "core/measures.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Mesures entre deux points 3D : largeurs, longueur et hauteur.\n\nToutes reposent sur le même moteur (geometry.py) : chaque clic devient un point 3D\nsur une surface, puis la mesure est une grandeur calculée sur ces points.\n\n- \"road\" : largeur perpendiculaire à la chaussée (deux points au sol, composante\n  en travers de l'axe de la route) ;\n- \"width\" : longueur parallèle à la route (distance 3D entre deux points au sol) ;\n- \"height\" : hauteur d'un objet (pied au sol, sommet dans le plan vertical face à\n  la caméra, ou sur la façade du cadastre, composante verticale).\n\nLa mesure libre 3D (façade, plans, triangulation 3D entre deux photos) a été retirée le\n15/10/2026 : elle donnait des résultats trop incohérents.\n\nUn point peut être recalé après coup sur la carte : sa position horizontale vient\nalors de la carte, et son altitude du rayon de visée de la photo à cette distance.\nLa mesure est recalculée ; pour une hauteur, elle ne dépend plus ni du terrain ni\nde la hauteur de caméra.\n\"\"\"\n\nimport math\n\nfrom . import calibration, geometry, ground, triangulation\nfrom .calibration import AIM_ERROR, MAP_ERROR, UNCALIBRATED\n\nDEFAULT_CAMERA_HEIGHT = 1.9  # hauteur de caméra par défaut (m)\n\n\ndef _num(value, digits=1):\n    \"\"\"Nombre à la française (virgule décimale).\"\"\"\n    return \"{:.{}f}\".format(value, digits).replace(\".\", \",\")\n\n\nclass NullItem:\n    \"\"\"Dessin d'une mesure sur la carte, quand l'hôte n'en fournit pas (voir MeasureTool.new_item).\"\"\"\n\n    def set_data(self, *args, **kwargs):\n        pass\n\n    def remove(self):\n        pass\n\n\nSURFACE_NAMES = {\"ground\": \"sol\", \"vertical\": \"plan vertical face à la caméra\"}\nPRESET_SURFACES = {\"road\": \"ground\", \"width\": \"ground\", \"height\": \"vertical\"}  # surface de chaque mesure\nCAMERA_RANGE = (0.5, 4.0)  # hauteur de caméra plausible (m) déduite de l'altitude GPS\nCAMERA_SOURCES = {None: 0, \"calée\": 1, \"altitude GPS\": 2}  # champ camera_calee de la couche des mesures\n# Incertitude de la hauteur de caméra (m) selon sa source : altitude GPS d'une position vérifiée\n# (écart-type sur la séquence de Pouilly : 2 cm, plus le LiDAR), sinon valeur saisie (1,7 à 2,2 m\n# selon le véhicule) ; une hauteur calée a sa propre incertitude\nCAMERA_ERRORS = {\"altitude GPS\": 0.05, None: 0.15}\n# Façade du cadastre : écart du mur (m), confirmé par le LiDAR HD ou non (voir buildings.py)\nWALL_ERROR, WALL_ERROR_UNCHECKED = 0.5, 1.0\nSELECT_ANGLE = 1.0  # écart maximal (degrés) entre un clic et le repère d'un point pour le sélectionner\nERRORS = (geometry.GeometryError, ground.GroundError)\nKIND_NAMES = {\"road\": \"largeur perpendiculaire à la chaussée\", \"width\": \"longueur parallèle à la route\",\n              \"height\": \"hauteur\"}\n\n\n\n\ndef _ground_z(clicks):\n    \"\"\"Altitude du sol sous chaque photo : celle du premier clic fait sur la photo, la même\n    ensuite pour tous ses clics (le profil d'un clic dépend de la direction visée).\"\"\"\n    out = {}\n    for c in clicks:\n        out.setdefault(c.get(\"pic\"), (c.get(\"profile\") or ground.flat_profile())[0][1])\n    return out\n\n\ndef _profile_z(profile, s):\n    \"\"\"Altitude du terrain à la distance horizontale s le long d'un profil [(distance, z)].\"\"\"\n    for (s0, z0), (s1, z1) in zip(profile, profile[1:]):\n        if s <= s1 or (s1, z1) == profile[-1]:\n            k = (s - s0) / (s1 - s0) if s1 > s0 else 0.0\n            return z0 + k * (z1 - z0)\n    return profile[-1][1]\n\n\ndef _wall_foot(click, camera_height, origin, ground_z, plane):\n    \"\"\"Pied du mur visé : là où la visée horizontale du clic coupe le plan vertical du mur,\n    à l'altitude du sol (profil de terrain du clic).\"\"\"\n    cam, u = geometry.camera(click, camera_height, origin, ground_z)\n    (px, py, _), (nx, ny, _) = plane\n    hx, hy = u[0], u[1]\n    den = nx * hx + ny * hy\n    if abs(den) < 1e-6:\n        raise geometry.GeometryError(\"Visée parallèle à la façade du cadastre : visez-la plus de face.\")\n    t = (nx * (px - cam[0]) + ny * (py - cam[1])) / den\n    norm = math.hypot(hx, hy)\n    if t <= 0:\n        raise geometry.GeometryError(\"La façade du cadastre est derrière la visée.\")\n    s = t * norm  # distance horizontale\n    profile = ground.anchored(click.get(\"profile\") or ground.flat_profile(), ground_z)\n    return (cam[0] + t * hx, cam[1] + t * hy, _profile_z(profile, s))\n\n\nclass Measure:\n    \"\"\"Une mesure entre deux points 3D (voir le module).\"\"\"\n\n    def __init__(self, tool, kind, surface):\n        self.tool = tool\n        self.kind, self.surface = kind, surface\n        self.clicks = []  # dicts de PanoramaxDock.photoClicked, avec profil de terrain\n        # n° de point -> (lon, lat, orientation en degrés) : point recalé sur la carte, qui fixe\n        # son plan vertical (passant par lui, de normale horizontale orientée vers la caméra\n        # qui l'a visé au moment du recalage)\n        self.overrides = {}\n        self.aimed = set()  # points visés à nouveau après un recalage : sur le plan calé de la mesure\n        self.result = None\n        self.error = None\n        self.notice = None  # avertissement sur la source d'altitude\n        self.incidence = None  # angle d'incidence le plus rasant sur un plan (degrés)\n        self.item = None\n        self.fid = None  # entité de la couche des mesures, une fois enregistrée\n        self.layer_id = None  # couche de cette entité : un fid ne vaut que dans sa couche\n        self.saved = None  # résultat au moment de l'enregistrement (voir _snapshot)\n        self.road = None  # axe de la route au point mesuré (largeur perpendiculaire, voir roads.py)\n        self.wall = None  # façade du cadastre visée (hauteur, voir buildings.py)\n        self.wall_pending = False\n        self.wall_item = None\n        self.road_pending = False  # lecture de cet axe en cours\n\n    def needed(self):\n        return 2\n\n    def add_click(self, click, notice=None):\n        if notice:\n            self.notice = notice\n        self.clicks.append(click)\n        self.compute()\n        if self.error:\n            error = self.error\n            self.clicks.pop()  # clic refusé : on le refait\n            self.compute()\n            self.error = error\n\n    def relocate(self, index, lon, lat):\n        \"\"\"Recale le point n° index à la position (lon, lat) cliquée sur la carte. Son plan\n        vertical est orienté face à la photo qui l'a visé.\"\"\"\n        c = self.clicks[index]\n        x, y = triangulation._local(lon, lat, c[\"lon\"], c[\"lat\"])\n        state = dict(self.overrides), set(self.aimed)\n        self.overrides[index] = (lon, lat, math.degrees(math.atan2(x, y)))\n        self.aimed.discard(index)  # le point est là où on l'a lâché\n        self.compute()\n        if self.error:\n            error = self.error\n            self.overrides, self.aimed = state\n            self.compute()\n            self.error = error\n\n    def reaim(self, index, click):\n        \"\"\"Vise à nouveau le point n° index : le nouveau clic remplace le sien. Si la mesure a\n        été calée sur la carte, le point est pris sur son plan calé (profondeur de la carte,\n        position fine de la photo), qu'il ait été lui-même recalé ou non ; sinon, sur la\n        surface de la mesure.\"\"\"\n        state = list(self.clicks), set(self.aimed)\n        self.clicks[index] = click\n        if self.overrides:\n            self.aimed.add(index)\n        self.compute()\n        if self.error:\n            error = self.error\n            self.clicks, self.aimed = state\n            self.compute()\n            self.error = error\n\n    # Calcul -------------------------------------------------------------------\n    def points(self, clicks=None, overrides=None, camera_delta=None, wall_shift=0.0):\n        \"\"\"Points 3D (repère local centré sur le premier clic) des clics complets,\n        angle d'incidence le plus rasant sur un plan, origine du repère, et pour\n        chaque point le clic dont il vient. camera_delta (photo -> écart de hauteur de caméra,\n        m) et wall_shift (décalage de la façade du cadastre vers l'extérieur, m) servent au\n        calcul de l'incertitude.\"\"\"\n        clicks = self.clicks if clicks is None else clicks\n        overrides = self.overrides if overrides is None else overrides\n        if not clicks:\n            return [], None, None, []\n        origin = (clicks[0][\"lon\"], clicks[0][\"lat\"])\n        ground_z = _ground_z(clicks)\n\n        def zof(click):\n            return ground_z[click.get(\"pic\")]\n\n        def h(click):\n            return self.tool.camera_for(click, zof(click)) + (camera_delta or {}).get(click.get(\"pic\"), 0.0)\n\n        # Plan calé de la mesure, défini par les points glissés sur la carte : vertical, passant\n        # par les deux premiers (le mur tracé sur la carte), ou par le seul glissé, face à la\n        # photo qui l'avait visé\n        anchors = {k: triangulation._local(v[0], v[1], origin[0], origin[1]) + (v[2],)\n                   for k, v in overrides.items()}\n        anchored = None\n        if len(anchors) >= 2:\n            (k1, a1), (k2, a2) = sorted(anchors.items())[:2]\n            if math.hypot(a2[0] - a1[0], a2[1] - a1[1]) >= 0.2:\n                anchored = geometry.vertical_plane((a1[0], a1[1], 0.0), (a2[0], a2[1], 0.0))\n        if anchored is None and anchors:\n            x, y, azimuth = sorted(anchors.items())[0][1]\n            a = math.radians(azimuth)\n            anchored = ((x, y, 0.0), (math.sin(a), math.cos(a), 0.0))\n\n        def fixed(k, p, click):\n            \"\"\"Point k visé à nouveau après un recalage : intersection du rayon et du plan calé.\n            Recalé sur la carte : à la position de la carte, à l'altitude du rayon de visée.\"\"\"\n            if k in self.aimed and anchored is not None:  # plan calé, pas la surface de la mesure\n                return geometry.on_plane(click, h(click), origin, *anchored, ground_z=zof(click))[0]\n            if k not in anchors:\n                return p\n            x, y, _ = anchors[k]\n            cam, u = geometry.camera(click, h(click), origin, zof(click))\n            reach = math.hypot(x - cam[0], y - cam[1])\n            return (x, y, cam[2] + reach * u[2] / max(math.hypot(u[0], u[1]), 1e-9))\n\n        def recaled(k):\n            \"\"\"Point k visé à nouveau dans le plan calé : la surface de la mesure ne sert pas.\"\"\"\n            return k in self.aimed and anchored is not None\n\n        pts, sources, incidence, plane = [], [], None, None\n        if self.surface == \"ground\":\n            for c in clicks:\n                k = len(pts)\n                pts.append(fixed(k, None if recaled(k) else geometry.on_ground(c, h(c), origin, zof(c))[0], c))\n                sources.append(c)\n        else:  # plan vertical : celui du mur du cadastre, sinon face à la caméra\n            if self.wall and 0 not in anchors:\n                # Façade du cadastre : pied au bas du mur, à l'altitude du sol (même si le clic\n                # tombe sur une voiture devant), sommet sur le mur\n                plane = geometry.vertical_plane(*(geometry.to_local(lon, lat, 0.0, origin)\n                                                  for lon, lat in self.wall[\"points\"]))\n                if wall_shift:\n                    (px, py, pz), (nx, ny, nz) = plane\n                    k = wall_shift / math.hypot(nx, ny)\n                    plane = ((px + k * nx, py + k * ny, pz), (nx, ny, nz))\n                first = _wall_foot(clicks[0], h(clicks[0]), origin, zof(clicks[0]), plane)\n                planar, pts, sources = clicks[1:], [first], [clicks[0]]\n            else:\n                first = fixed(0, geometry.on_ground(clicks[0], h(clicks[0]), origin, zof(clicks[0]))[0], clicks[0])\n                cam = geometry.camera(clicks[0], h(clicks[0]), origin, zof(clicks[0]))[0]\n                plane = geometry.facing_plane(cam, first)\n                planar, pts, sources = clicks[1:], [first], [clicks[0]]\n            for c in planar:\n                if recaled(len(pts)):\n                    pts.append(fixed(len(pts), None, c))\n                    sources.append(c)\n                    continue\n                p, angle = geometry.on_plane(c, h(c), origin, *plane, ground_z=zof(c))\n                pts.append(fixed(len(pts), p, c))\n                sources.append(c)\n                incidence = angle if incidence is None else min(incidence, angle)\n        return pts, incidence, origin, sources\n\n    @property\n    def axis(self):\n        \"\"\"Axe de la route retenu (cap en degrés) : au point mesuré si connu (voir roads.py),\n        sinon direction du véhicule à la caméra, portée par le premier clic.\"\"\"\n        return self.road[\"axis\"] if self.road else self.clicks[0].get(\"axis\")\n\n    @property\n    def axis_source(self):\n        if self.road:\n            return self.road[\"source\"]\n        source = self.clicks[0].get(\"axis_source\")\n        return source + \", lecture de la BD TOPO…\" if self.road_pending and source else source\n\n    def _wall_changed(self):\n        \"\"\"Façade du cadastre visée par le pied (hauteur, voir buildings.py), si l'outil la\n        demande. Retourne True si elle a changé (les points sont à recalculer).\"\"\"\n        lookup = self.tool.wall_lookup if self.tool.use_wall else None\n        old = self.wall\n        self.wall, self.wall_pending = None, False\n        if lookup is not None:\n            c = self.clicks[0]\n            res = lookup(c[\"lon\"], c[\"lat\"], c[\"yaw\"])\n            if isinstance(res, dict):\n                self.wall = res\n            else:\n                self.wall_pending = res == \"pending\"\n        return self.wall != old\n\n    def _road_axis(self, pts, origin):\n        \"\"\"Axe de la route au milieu des deux bords (voir roads.py), si l'outil sait le lire.\"\"\"\n        lookup = self.tool.road_lookup\n        self.road, self.road_pending = None, False\n        if lookup is None:\n            return\n        mid = ((pts[0][0] + pts[1][0]) / 2, (pts[0][1] + pts[1][1]) / 2, pts[0][2])\n        lon, lat = geometry.to_geographic(mid, origin)[:2]\n        crossing = math.degrees(math.atan2(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1])) % 360\n        res = lookup(lon, lat, crossing, self.clicks[0].get(\"sequence\"))\n        if isinstance(res, dict):\n            self.road = res\n        else:\n            self.road_pending = res == \"pending\"\n\n    def quantity(self, d):\n        \"\"\"Grandeur mesurée d'après la décomposition d (voir geometry.decompose).\"\"\"\n        if self.kind == \"road\":\n            if d[\"across\"] is None:\n                raise geometry.GeometryError(\"Axe de la route inconnu pour cette photo : largeur impossible \"\n                                             \"à calculer.\")\n            return d[\"across\"]\n        if self.kind == \"height\":\n            if d[\"vertical\"] <= 0:\n                raise geometry.GeometryError(\"Le sommet est sous le pied : cliquez d'abord au pied, puis au \"\n                                             \"sommet.\")\n            return abs(d[\"vertical\"])\n        return d[\"d3\"]\n\n    def _value(self, **variant):\n        pts, _, _, _ = self.points(**variant)\n        return self.quantity(geometry.decompose(pts[0], pts[1], self.axis))\n\n    def _spread(self):\n        \"\"\"Incertitude de la mesure (m) : somme quadratique des écarts dus à chaque source\n        d'erreur indépendante, chacune prise à ±1 écart-type :\n        - inclinaison de chaque photo, commune à tous ses clics (tangage et roulis) : celle du\n          calage appliqué, ou UNCALIBRATED sans calage ;\n        - hauteur de caméra de chaque photo (CAMERA_ERRORS, ou celle de la hauteur calée) ;\n        - visée de chaque clic (AIM_ERROR) ;\n        - position de chaque point recalé sur la carte, façade du cadastre.\"\"\"\n        ref = self._value()\n        groups = []  # par source d'erreur : variantes à ±1 écart-type\n        for pic in dict.fromkeys(c.get(\"pic\") for c in self.clicks):\n            sigma = self._tilt_sigma(pic)\n            for comp in ((sigma, 0.0), (0.0, sigma)):\n                groups.append([{\"clicks\": self._tilted_clicks(self.clicks, pic, sign * comp[0], sign * comp[1])}\n                               for sign in (-1, 1)])\n            dh = self._camera_sigma(pic)\n            groups.append([{\"camera_delta\": {pic: sign * dh}} for sign in (-1, 1)])\n        for i in range(len(self.clicks)):\n            for key, step in ((\"elev\", AIM_ERROR), (\"yaw\", AIM_ERROR)):\n                variants = []\n                for sign in (-1, 1):\n                    moved = [dict(x) for x in self.clicks]\n                    moved[i][key] += sign * step\n                    variants.append({\"clicks\": moved})\n                groups.append(variants)\n        for k, (lon, lat, azimuth) in self.overrides.items():\n            for dx, dy in ((1, 0), (0, 1)):\n                variants = []\n                for sign in (-1, 1):\n                    moved = dict(self.overrides)\n                    moved[k] = triangulation._geographic(sign * dx * MAP_ERROR, sign * dy * MAP_ERROR, lon, lat) + (azimuth,)\n                    variants.append({\"overrides\": moved})\n                groups.append(variants)\n        if self.wall and not self.overrides:\n            err = WALL_ERROR_UNCHECKED if self.wall.get(\"warning\") else WALL_ERROR\n            groups.append([{\"wall_shift\": s * err} for s in (-1, 1)])\n        total = 0.0\n        for variants in groups:\n            worst = 0.0\n            for variant in variants:\n                try:\n                    worst = max(worst, abs(self._value(**variant) - ref))\n                except ERRORS:\n                    return float(\"inf\")\n            total += worst * worst\n        return math.sqrt(total)\n\n    def _tilt_sigma(self, pic):\n        \"\"\"Incertitude (degrés) de l'inclinaison appliquée aux clics de la photo.\"\"\"\n        cal = self.tool.calibration\n        tilt = cal.tilt(pic) if cal is not None and pic else None\n        return tilt[\"sigma\"] if tilt and tilt.get(\"sigma\") is not None else UNCALIBRATED\n\n    def _camera_sigma(self, pic):\n        \"\"\"Incertitude (m) de la hauteur de caméra de la photo, selon sa source.\"\"\"\n        c = next(x for x in self.clicks if x.get(\"pic\") == pic)\n        _, source = self.tool.camera_info(c, _ground_z(self.clicks)[pic])\n        if source == \"calée\":\n            return self.tool.calibration.camera(c.get(\"sequence\"))[\"sigma\"]\n        return CAMERA_ERRORS.get(source, CAMERA_ERRORS[None])\n\n    @staticmethod\n    def _tilted_clicks(clicks, pic, north, east):\n        \"\"\"Clics de la photo pic vus par une caméra penchée en plus de north° vers le nord et\n        east° vers l'est (variation d'inclinaison commune à tous ses clics).\"\"\"\n        up = calibration.up_from_components(north, east, 0.0)\n        out = []\n        for c in clicks:\n            c = dict(c)\n            if c.get(\"pic\") == pic:\n                c[\"yaw\"], c[\"elev\"] = calibration.untilt(up, c[\"yaw\"], c[\"elev\"])\n            out.append(c)\n        return out\n\n    def compute(self):\n        self.result, self.error, self.incidence = None, None, None\n        try:\n            if self.kind == \"height\" and len(self.clicks) == 2 and self.clicks[0].get(\"pic\") != self.clicks[1].get(\"pic\"):\n                raise geometry.GeometryError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n            pts, self.incidence, origin, sources = self.points()\n            if len(pts) == 2 and len(self.clicks) == self.needed():\n                if self.kind == \"height\" and self._wall_changed():\n                    pts, self.incidence, origin, sources = self.points()\n                if self.kind == \"road\":\n                    self._road_axis(pts, origin)\n                d = geometry.decompose(pts[0], pts[1], self.axis)\n                value = self.quantity(d)\n                lonlat = [geometry.to_geographic(p, origin)[:2] for p in pts]\n                ranges = []\n                for p, c in zip(pts, sources):\n                    cx, cy = triangulation._local(c[\"lon\"], c[\"lat\"], origin[0], origin[1])\n                    ranges.append(math.hypot(p[0] - cx, p[1] - cy))\n                self.result = {\"value\": value, \"decomposition\": d, \"uncertainty\": self._spread(),\n                               \"ranges\": ranges, \"points\": lonlat, \"extra\": None, \"picks\": lonlat,\n                               \"shifts\": self._shifts(pts, origin)}\n                if self.kind == \"road\":\n                    # Trait perpendiculaire à l'axe, à mi-chemin des deux bords cliqués le long de la\n                    # route ; chaque bout est relié en pointillés à son bord cliqué\n                    a = math.radians(self.axis)\n                    ux, uy = math.sin(a), math.cos(a)\n                    half = ((pts[1][0] - pts[0][0]) * ux + (pts[1][1] - pts[0][1]) * uy) / 2.0\n                    start = (pts[0][0] + half * ux, pts[0][1] + half * uy, pts[0][2])\n                    end = (pts[1][0] - half * ux, pts[1][1] - half * uy, pts[0][2])\n                    self.result[\"points\"] = [geometry.to_geographic(p, origin)[:2] for p in (start, end)]\n                    self.result[\"extra\"] = list(lonlat)\n                elif self.kind == \"height\":\n                    self.result[\"points\"] = [lonlat[0]]  # sommet au-dessus du pied\n        except ERRORS as exc:\n            self.error = str(exc)\n        self._draw()\n\n    def _shifts(self, pts, origin):\n        \"\"\"Pour chaque clic, écart (cap, élévation en degrés) entre la direction cliquée et\n        celle où la caméra voit le point 3D qui en résulte : nul pour un point resté sur sa\n        visée, non nul pour un point recalé de côté sur la carte.\"\"\"\n        ground_z = _ground_z(self.clicks)\n        out = []\n        for i, c in enumerate(self.clicks):\n            p = pts[i]\n            z = ground_z[c.get(\"pic\")]\n            cam, _ = geometry.camera(c, self.tool.camera_for(c, z), origin, z)\n            vx, vy, vz = p[0] - cam[0], p[1] - cam[1], p[2] - cam[2]\n            yaw = math.degrees(math.atan2(vx, vy))\n            elev = math.degrees(math.atan2(vz, math.hypot(vx, vy)))\n            out.append(((yaw - c[\"yaw\"] + 540) % 360 - 180, elev - c[\"elev\"]))\n        return out\n\n    def picks(self):\n        \"\"\"Points recalables sur la carte : [(n° de point, lon, lat)]. Sur le plan vertical\n        face à la caméra (hauteur), seul le pied l'est : le sommet en découle.\"\"\"\n        if self.result:\n            pts = [(k, p[0], p[1]) for k, p in enumerate(self.result[\"picks\"])]\n        else:\n            try:\n                raw, _, origin, _ = self.points()\n            except ERRORS:\n                return []\n            pts = [(k,) + geometry.to_geographic(p, origin)[:2] for k, p in enumerate(raw)]\n        return pts[:1] if self.surface == \"vertical\" else pts\n\n    # Enregistrement -----------------------------------------------------------\n    def _snapshot(self):\n        \"\"\"Ce qui doit être réécrit dans la couche s'il change : valeur, incertitude, points.\"\"\"\n        r = self.result\n        return round(r[\"value\"], 4), round(r[\"uncertainty\"], 4), tuple(map(tuple, r[\"picks\"]))\n\n    def unsaved(self):\n        \"\"\"Mesure terminée, pas encore enregistrée, ou modifiée depuis (recalage, visée).\"\"\"\n        return bool(self.result) and self.saved != self._snapshot()\n\n    # Affichage ----------------------------------------------------------------\n    def label(self):\n        if not self.result:\n            return \"\"\n        symbol = \"↕ \" if self._vertical() else \"↔ \"\n        return \"{}{} m ± {} m\".format(symbol, _num(self.result[\"value\"], 2), _num(self.result[\"uncertainty\"], 2))\n\n    def _vertical(self):\n        if self.kind in (\"road\", \"width\"):\n            return False\n        return True  # hauteur\n\n    def _draw(self):\n        if self.result:\n            points, extra = self.result[\"points\"], self.result[\"extra\"]\n            label = \"{} m\".format(_num(self.result[\"value\"], 2))\n        else:\n            points, extra, label = [p[1:] for p in self.picks()], None, \"\"\n        if self.item is None and points:\n            self.item = self.tool.new_item()\n        if self.item is not None:\n            self.item.set_data(points, label, extra)\n        wall = self.wall[\"points\"] if self.wall else []\n        if self.wall_item is None and wall:\n            self.wall_item = self.tool.new_item(wall=True)\n        if self.wall_item is not None:\n            self.wall_item.set_data(wall, \"façade du cadastre\" if wall else \"\")\n\n    def remove(self):\n        if self.item is not None:\n            self.item.remove()\n            self.item = None\n        if self.wall_item is not None:\n            self.wall_item.remove()\n            self.wall_item = None\n\n    def point_of_click(self, i):\n        \"\"\"N° du point auquel contribue le clic n° i.\"\"\"\n        return i\n\n    def viewer_marks(self, selected=None):\n        \"\"\"Repères dans la visionneuse (voir PanoramaxDock.set_measure_marks) : là où la\n        photo voit chaque point 3D, c'est-à-dire à l'endroit cliqué, décalé d'autant que le\n        point a été recalé de côté sur la carte. selected : n° du point sélectionné.\"\"\"\n        shifts = (self.result or {}).get(\"shifts\") or [(0.0, 0.0)] * len(self.clicks)\n        points = []\n        for i, (c, (dyaw, delev)) in enumerate(zip(self.clicks, shifts)):\n            pos = c.get(\"pos\") or [None, None]\n            raw = c.get(\"raw\") or [c[\"yaw\"], c[\"elev\"]]\n            if pos[0] is not None:  # position dans la photo (radians), visionneuse web\n                pos = [pos[0] + math.radians(dyaw), pos[1] + math.radians(delev)]\n            points.append({\"pic\": c.get(\"pic\"), \"yaw\": pos[0], \"pitch\": pos[1],\n                           \"abs_yaw\": raw[0] + dyaw, \"elev\": raw[1] + delev,\n                           \"sel\": selected is not None and self.point_of_click(i) == selected})\n        return {\"points\": points, \"label\": self.label(), \"beside\": bool(self.result) and self._vertical()}\n\n    def status(self):\n        \"\"\"Résultat (mesure complète) ; les consignes de clic sont dans MeasureTool.status.\"\"\"\n        r = self.result\n        d = r[\"decomposition\"]\n        value, unc = _num(r[\"value\"], 2), _num(r[\"uncertainty\"], 2)\n        if self.kind == \"road\":\n            text = (\"Largeur perpendiculaire à la chaussée : {} m (±{} m) · en biais {} m · axe {}° ({})\").format(\n                value, unc, _num(d[\"horizontal\"], 2), _num(self.axis % 180, 0), self.axis_source or \"?\")\n        elif self.kind == \"width\":\n            text = \"Longueur : {} m (±{} m) entre les deux points · à {} et {} m de la photo\".format(\n                value, unc, _num(r[\"ranges\"][0]), _num(r[\"ranges\"][1]))\n            if abs(d[\"vertical\"]) >= 0.05:\n                text += \" · dénivelé {} m\".format(_num(d[\"vertical\"], 2))\n        elif self.kind == \"height\":\n            text = \"Hauteur : {} m (±{} m) · objet à {} m\".format(value, unc, _num(r[\"ranges\"][0]))\n            if self.wall:\n                text += \" · façade du cadastre à {} m ({})\".format(_num(self.wall[\"distance\"]), self.wall[\"check\"])\n            elif self.tool.use_wall:\n                text += (\" · lecture du cadastre…\" if self.wall_pending else\n                         \" · aucune façade du cadastre dans la visée : pied cliqué\")\n        if self.overrides:\n            text += \" · {} point{} recalé{} sur la carte\".format(\n                len(self.overrides), *((\"s\", \"s\") if len(self.overrides) > 1 else (\"\", \"\")))\n            if self.aimed:\n                text += \", dont {} visé{} à nouveau dans son plan\".format(\n                    len(self.aimed), \"s\" if len(self.aimed) > 1 else \"\")\n        if self.incidence is not None and self.incidence < geometry.GRAZING:\n            text += \". Visée rasante sur le plan ({}°) : mesure imprécise, prenez une photo plus en face\".format(\n                _num(self.incidence, 0))\n        labels = {c.get(\"terrain\") for c in self.clicks if c.get(\"terrain\")}\n        height, source = self.tool.camera_info(self.clicks[0], _ground_z(self.clicks)[self.clicks[0].get(\"pic\")])\n        text += \". Terrain : {}, caméra à {} m{}.\".format(\" + \".join(sorted(labels)) or ground.FLAT,\n                                                        _num(height, 2), \" ({})\".format(source) if source else \"\")\n        if len(labels) > 1:\n            text += \" Altitudes de sources différentes : la composante verticale peut être faussée.\"\n        if self.notice:\n            text += \" ({}.)\".format(self.notice)\n        return text + \" Point mal placé : glissez-le sur la carte.\"\n\n\nclass MeasureTool:\n    \"\"\"Mesure en cours, mesures terminées gardées à l'écran et réglages.\"\"\"\n\n    def __init__(self, canvas):\n        self.canvas = canvas\n        self.mode = \"road\"  # \"road\", \"width\" ou \"height\"\n        self.camera_height = DEFAULT_CAMERA_HEIGHT  # hauteur saisie dans le panneau\n        self.road_lookup = None  # roads.RoadAxisProvider.lookup : axe de la route au point mesuré\n        self.wall_lookup = None  # buildings.BuildingProvider.lookup : façade du cadastre visée\n        self.use_wall = False  # hauteur : pied et sommet sur la façade du cadastre\n        self.calibration = None  # calibration.Calibration : hauteur calée par séquence\n        self.error = None\n        self.current = None\n        self.done = []  # mesures terminées, gardées à l'écran jusqu'à clear_all\n        self.selected = None  # (mesure, n° de point) à viser à nouveau dans la visionneuse\n\n    def new_item(self, wall=False):\n        \"\"\"Dessin d'une mesure (ou de la façade du cadastre, wall) sur la carte : set_data(points, libellé,\n        extras) et remove(). Rien ici ; l'hôte le fournit (plugin QGIS : measure.MeasureItem).\"\"\"\n        return NullItem()\n\n    # Réglages ---------------------------------------------------------------\n    def set_mode(self, mode):\n        if mode != self.mode:\n            self.finish()\n            self.mode = mode\n\n    def set_camera_height(self, value):\n        self.camera_height = float(value)\n        if self.current is not None:\n            self.current.compute()\n\n    def camera_info(self, click, ground_z=None):\n        \"\"\"(hauteur de caméra du clic, source) ; source \"altitude GPS\", \"calée\" ou None.\n\n        Dans l'ordre : altitude NGF de la caméra (position vérifiée précise, voir precision.py)\n        moins l'altitude du sol sous la photo (ground_z, si elle vient du LiDAR HD), la plus\n        précise et propre à chaque photo ; hauteur calée pour la séquence ; réglage du panneau.\"\"\"\n        camera_alt = click.get(\"camera_alt\")\n        if camera_alt is not None and ground_z is not None and click.get(\"precise_ground\"):\n            height = camera_alt - ground_z\n            if CAMERA_RANGE[0] <= height <= CAMERA_RANGE[1]:\n                return height, \"altitude GPS\"\n        sequence = click.get(\"sequence\")\n        cam = self.calibration.camera(sequence) if self.calibration and sequence else None\n        return (cam[\"height\"], \"calée\") if cam else (self.camera_height, None)\n\n    def camera_for(self, click, ground_z=None):\n        return self.camera_info(click, ground_z)[0]\n\n    def needs_profile(self):\n        return True  # altitude du sol sous la caméra, et du sol visé\n\n    # Clics --------------------------------------------------------------------\n    def select_near(self, click):\n        \"\"\"Clic sur le repère d'un point existant (à moins de SELECT_ANGLE degrés), entre deux\n        mesures : le sélectionne pour le viser à nouveau. Retourne True si le clic a servi à\n        cela. Un point déjà sélectionné : le clic est sa nouvelle visée, même tout près de son\n        repère (une correction fine l'est toujours) ; on annule avec cancel_selection.\"\"\"\n        if self.selected is not None:\n            return False\n        if self.current is not None and 0 < len(self.current.clicks) < self.current.needed():\n            return False\n        raw = click.get(\"raw\") or [click[\"yaw\"], click[\"elev\"]]\n        best, best_d = None, SELECT_ANGLE\n        for m in self.measures():\n            if not m.result:\n                continue\n            for i, p in enumerate(m.viewer_marks()[\"points\"]):\n                if p[\"pic\"] != click.get(\"pic\"):\n                    continue\n                dyaw = (raw[0] - p[\"abs_yaw\"] + 540) % 360 - 180\n                d = math.hypot(dyaw * math.cos(math.radians(raw[1])), raw[1] - p[\"elev\"])\n                if d < best_d:\n                    best, best_d = (m, m.point_of_click(i)), d\n        if best is None:\n            return False\n        self.error = None\n        self.selected = best\n        return True\n\n    def cancel_selection(self):\n        \"\"\"Annule la sélection d'un point. Retourne True s'il y en avait une.\"\"\"\n        if self.selected is None:\n            return False\n        self.selected = None\n        return True\n\n    def add_click(self, click, notice=None):\n        self.error = None\n        if self.selected is not None:  # visée à nouveau du point sélectionné\n            measure, index = self.selected\n            self.selected = None\n            if notice:\n                measure.notice = notice\n            measure.reaim(index, click)\n            if measure.error:\n                return measure.error + \" \" + (measure.status() if measure.result else \"\")\n            return measure.status()\n        if self.current is None or len(self.current.clicks) >= self.current.needed():\n            self.finish()  # nouvelle mesure, la précédente reste affichée\n            self.current = Measure(self, self.mode, PRESET_SURFACES[self.mode])\n        self.current.add_click(click, notice)\n        return self.status()\n\n    def finish(self):\n        \"\"\"Termine la mesure en cours : réussie, elle reste affichée (visionneuse et carte)\n        jusqu'à clear_all ; sinon elle est abandonnée.\"\"\"\n        if self.current is not None:\n            if self.current.result:\n                self.done.append(self.current)\n            else:\n                self.current.remove()\n        self.current, self.selected = None, None\n\n    def clear(self):\n        \"\"\"Efface la mesure en cours (les mesures terminées restent affichées).\"\"\"\n        if self.current is not None:\n            self.current.remove()\n        self.current, self.error, self.selected = None, None, None\n\n    def clear_all(self):\n        \"\"\"Efface aussi les mesures terminées.\"\"\"\n        self.clear()\n        for m in self.done:\n            m.remove()\n        self.done = []\n\n    def remove(self):\n        self.clear_all()\n\n    def measures(self):\n        \"\"\"Toutes les mesures affichées (terminées, puis en cours).\"\"\"\n        return self.done + ([self.current] if self.current is not None else [])\n\n    def set_use_wall(self, value):\n        \"\"\"Hauteur sur la façade du cadastre (case du panneau) : mesures de hauteur recalculées.\"\"\"\n        self.use_wall = bool(value)\n        return self.recompute_walls()\n\n    def recompute_walls(self):\n        \"\"\"Façades du cadastre arrivées ou demandées : hauteurs recalculées. Retourne le\n        nombre de mesures concernées.\"\"\"\n        heights = [m for m in self.measures() if m.kind == \"height\" and len(m.clicks) == m.needed()]\n        for m in heights:\n            m.compute()\n        return len(heights)\n\n    def recompute_roads(self):\n        \"\"\"Axe de la route arrivé (voir roads.py) : largeurs perpendiculaires recalculées.\n        Retourne le nombre de mesures concernées.\"\"\"\n        roads = [m for m in self.measures() if m.kind == \"road\" and len(m.clicks) == m.needed()]\n        for m in roads:\n            m.compute()\n        return len(roads)\n\n    def recorrect(self, pic, correct):\n        \"\"\"Calage de la photo `pic` changé (inclinaison automatique arrivée après les clics) :\n        directions de ses clics recalculées depuis leur direction brute par correct(clic) →\n        (cap, élévation), puis mesures recalculées. Retourne le nombre de mesures concernées.\"\"\"\n        count = 0\n        for m in self.measures():\n            clicks = [c for c in m.clicks if c.get(\"pic\") == pic and c.get(\"raw\")]\n            for c in clicks:\n                c[\"yaw\"], c[\"elev\"] = correct(c)\n            if clicks:\n                m.compute()\n                count += 1\n        return count\n\n    # Enregistrement -----------------------------------------------------------\n    # Recalage sur la carte ----------------------------------------------------\n    def handles(self):\n        \"\"\"Poignées déplaçables sur la carte : [(clé, lon, lat)], clé (\"point\", mesure,\n        n° de point).\"\"\"\n        return [((\"point\", m, k), lon, lat) for m in self.measures() for k, lon, lat in m.picks()]\n\n    def move_handle(self, key, lon, lat):\n        \"\"\"Recale une poignée à (lon, lat). Retourne le texte à afficher dans le panneau.\"\"\"\n        measure, index = key[1], key[2]\n        measure.relocate(index, lon, lat)\n        if measure.error:\n            return measure.error + \" Recalage annulé.\"\n        return measure.status() if measure.result else self.status()\n\n    # Visionneuse ----------------------------------------------------------------\n    def _marks(self, m):\n        return m.viewer_marks(self.selected[1] if self.selected and self.selected[0] is m else None)\n\n    def done_marks(self):\n        return [self._marks(m) for m in self.done]\n\n    def viewer_marks(self):\n        if self.current is None:\n            return {\"points\": [], \"label\": \"\", \"beside\": False}\n        return self._marks(self.current)\n\n    def status(self):\n        prefix = (self.error + \" \") if self.error else \"\"\n        if self.selected is not None:\n            measure, index = self.selected\n            where = (\" : il sera placé dans le plan calé sur la carte\" if measure.overrides else\n                     \" : il sera replacé sur la {}\".format(SURFACE_NAMES[measure.surface]))\n            return (\"Point {} sélectionné{}. Cliquez sa position exacte dans la photo (zoomez pour être précis), \"\n                    \"ou « Effacer » pour annuler.\").format(index + 1, where)\n        m = self.current\n        if m is not None and m.result:\n            return m.status()\n        n = len(m.clicks) if m is not None else 0\n        if m is not None and m.error:\n            prefix = m.error + \" \"\n        hints = {\n            \"road\": (\"Cliquez au pied du premier bord (bordure, marquage, limite de chaussée…).\",\n                     \"Cliquez au pied du bord opposé, pas forcément juste en face : la largeur est prise \"\n                     \"perpendiculairement à la route.\"),\n            \"width\": (\"Cliquez au sol à une extrémité de l'objet.\",\n                      \"Cliquez au sol à l'autre extrémité : la distance directe entre les deux points est mesurée.\"),\n            \"height\": (\"Cliquez dans la photo au pied de l'objet, exactement au contact du sol.\",\n                       \"Cliquez au sommet de l'objet, sur la même photo.\"),\n        }[self.mode]\n        return prefix + hints[min(n, 1)]\n",
 "core/metadata.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Fiches des photos Panoramax (STAC) : cap, précision et altitude GPS, liens, recherche.\nSans réseau ni QGIS (voir api.py pour l'accès à l'API dans le plugin).\"\"\"\n\nimport math\nfrom urllib.parse import urlencode, urlsplit\n\n\ndef search_url(lon, lat, radius_m=25, limit=20, collection=None, api_url=\"https://api.panoramax.xyz/api\"):\n    \"\"\"URL de recherche STAC des photos autour d'un point (bbox carrée), éventuellement d'une\n    seule séquence.\"\"\"\n    dlat = radius_m / 111320.0\n    dlon = radius_m / (111320.0 * max(math.cos(math.radians(lat)), 0.01))\n    bbox = \"{:.7f},{:.7f},{:.7f},{:.7f}\".format(lon - dlon, lat - dlat, lon + dlon, lat + dlat)\n    params = {\"bbox\": bbox, \"limit\": limit}\n    if collection:\n        params[\"collections\"] = collection\n    return \"{}/search?{}\".format(api_url, urlencode(params))\n\n\ndef nearest_feature(features, lon, lat):\n    \"\"\"Renvoie la photo (feature STAC) la plus proche du point.\"\"\"\n    best, best_d = None, None\n    coslat = math.cos(math.radians(lat))\n    for feat in features:\n        try:\n            flon, flat = feat[\"geometry\"][\"coordinates\"][:2]\n        except (KeyError, TypeError, ValueError):\n            continue\n        d = ((flon - lon) * coslat) ** 2 + (flat - lat) ** 2\n        if best_d is None or d < best_d:\n            best, best_d = feat, d\n    return best\n\n\ndef item_heading(item):\n    props = item.get(\"properties\", {}) or {}\n    for key in (\"view:azimuth\", \"heading\"):\n        if props.get(key) is not None:\n            try:\n                return float(props[key])\n            except (TypeError, ValueError):\n                pass\n    return None\n\n\ndef precise_heading(item):\n    \"\"\"Cap de la photo au centième de degré, tiré de l'EXIF (GPSImgDirection), ou None.\n\n    L'API arrondit view:azimuth au degré : jusqu'à 0,5° d'erreur de visée, soit\n    17 cm à 20 m. La valeur EXIF n'est retenue que si elle concorde avec\n    view:azimuth (même mesure, non arrondie), pas si l'API a corrigé le cap.\n    \"\"\"\n    rounded = item_heading(item)\n    exif = ((item.get(\"properties\", {}) or {}).get(\"exif\") or {}).get(\"Exif.GPSInfo.GPSImgDirection\")\n    if rounded is None or not exif:\n        return None\n    try:\n        num, _, den = str(exif).partition(\"/\")\n        value = float(num) / float(den or 1)\n    except (TypeError, ValueError, ZeroDivisionError):\n        return None\n    return value % 360 if abs((value - rounded + 540) % 360 - 180) < 1.0 else None\n\n\ndef _exif_number(item, key):\n    \"\"\"Valeur numérique d'une balise EXIF de la fiche (rationnel « a/b » ou nombre), ou None.\"\"\"\n    value = ((item.get(\"properties\", {}) or {}).get(\"exif\") or {}).get(key)\n    try:\n        num, _, den = str(value).partition(\"/\")\n        return float(num) / float(den or 1)\n    except (TypeError, ValueError, ZeroDivisionError):\n        return None\n\n\ndef exif_accuracy(item):\n    \"\"\"Précision horizontale de la position (m) déclarée dans l'EXIF de la photo\n    (GPSHPositioningError), ou None si la photo ne la déclare pas.\"\"\"\n    value = _exif_number(item, \"Exif.GPSInfo.GPSHPositioningError\")\n    return value if value is not None and value > 0 else None\n\n\ndef gps_differential(item):\n    \"\"\"La position de la photo a-t-elle reçu une correction différentielle (EXIF GPSDifferential) ?\n    DGPS ou RTK : la précision réelle reste à vérifier (voir precision.py).\"\"\"\n    return _exif_number(item, \"Exif.GPSInfo.GPSDifferential\") == 1\n\n\ndef item_accuracy(item):\n    \"\"\"Précision horizontale de la position GPS de la photo (m), ou None si inconnue : celle\n    déclarée dans l'EXIF, sinon celle annoncée par Panoramax (souvent générique).\"\"\"\n    value = exif_accuracy(item)\n    if value is not None:\n        return value\n    value = (item.get(\"properties\", {}) or {}).get(\"quality:horizontal_accuracy\")\n    try:\n        value = float(value)\n    except (TypeError, ValueError):\n        return None\n    return value if value > 0 else None\n\n\ndef item_altitude(item):\n    \"\"\"Altitude GPS ellipsoïdale de la caméra (m, EXIF GPSAltitude), ou None. Souvent imprécise :\n    à n'utiliser que pour une position vérifiée (voir precision.py).\"\"\"\n    altitude = _exif_number(item, \"Exif.GPSInfo.GPSAltitude\")\n    if altitude is None:\n        return None\n    return -altitude if _exif_number(item, \"Exif.GPSInfo.GPSAltitudeRef\") == 1 else altitude\n\n\ndef item_image_url(item):\n    assets = item.get(\"assets\", {}) or {}\n    for key in (\"sd\", \"thumb\", \"hd\"):\n        href = (assets.get(key) or {}).get(\"href\")\n        if href:\n            return href\n    return None\n\n\ndef item_link(item, rel):\n    for link in item.get(\"links\", []) or []:\n        if link.get(\"rel\") == rel and link.get(\"href\"):\n            return link[\"href\"]\n    return None\n\n\ndef id_from_href(href):\n    \"\"\"Dernier segment d'une URL d'item STAC (= identifiant de la photo).\"\"\"\n    return urlsplit(href).path.rstrip(\"/\").rsplit(\"/\", 1)[-1] if href else None\n\n\ndef sequence_axis(item, prev_item, next_item):\n    \"\"\"Direction de déplacement le long de la séquence (cap en degrés), ou None.\n\n    Calculée entre les photos voisines (précédente et suivante, fiches STAC ou None) pour\n    suivre l'axe de la voie, plutôt que l'orientation de la caméra.\n    \"\"\"\n    def position(feat):\n        try:\n            return [float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]]\n        except (KeyError, TypeError, ValueError):\n            return None\n\n    here = position(item)\n    a = position(prev_item) if prev_item else None\n    b = position(next_item) if next_item else None\n    a, b = (a or here), (b or here)\n    if a is None or b is None or a == b:\n        return None\n    dx = (b[0] - a[0]) * math.cos(math.radians((a[1] + b[1]) / 2))\n    dy = b[1] - a[1]\n    if math.hypot(dx, dy) * 111320.0 < 0.5:  # photos quasi confondues (arrêt) : direction peu fiable\n        return None\n    return math.degrees(math.atan2(dx, dy)) % 360\n",
 "core/precision.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Précision de la position GPS des photos, vérifiée d'après leurs métadonnées.\n\nPanoramax annonce souvent une précision générique (2 m pour le matériel de relevé). Une\nphoto est jugée précise (au décimètre) :\n- si son EXIF déclare une précision (GPSHPositioningError) d'au plus PRECISE_ACCURACY ;\n- ou si sa position a reçu une correction différentielle (GPSDifferential) et que cela se\n  vérifie sur sa séquence : pour les photos voisines, l'altitude GPS (convertie en NGF)\n  moins le sol LiDAR HD sous la photo, c'est-à-dire la hauteur de la caméra, est constante\n  à MAX_SPREAD près, sans dériver de plus de MAX_DRIFT. Un GPS non recalé (DGPS, GPS\n  simple) varie de plusieurs décimètres. Si la portion de séquence autour de la photo est\n  refusée (pont, défaut du LiDAR), d'autres portions de la séquence sont essayées : une\n  seule vérifiée suffit pour toute la séquence.\n  C'est le cas des photos imajbox 360 HD (RTK et centrale inertielle : 4,7 cm sur 100\n  photos à Pouilly-en-Auxois).\n\nUne photo précise donne la hauteur de caméra par son altitude (voir\nmeasures.MeasureTool.camera_info). Les mesures ne sont pleinement fiables qu'avec à la\nfois une position vérifiée précise et le LiDAR HD sous la photo ; sinon l'outil est en\nmode dégradé (hauteur de caméra et inclinaison à caler, sol approximatif sans LiDAR) :\nune fenêtre l'annonce à l'activation de la mesure (voir viewer_dock).\n\nUne vérification par séquence (deux requêtes : fiches des photos voisines, altitudes\nLiDAR), en arrière-plan ; le résultat est gardé pour la session.\n\"\"\"\n\nimport math\nimport statistics\nfrom urllib.parse import urlencode\n\nfrom . import host, metadata, terrain\n\nPRECISE_ACCURACY = 0.20  # m : précision déclarée suffisante pour la hauteur de caméra par l'altitude\nVERIFIED_ACCURACY = 0.10  # m : précision retenue pour une séquence vérifiée\nCHECK_RADIUS = 60.0  # m autour de la photo pour les photos voisines de la séquence\nCHECK_PHOTOS = 20\n# Portion autour de la photo refusée : autres portions de la même séquence essayées (une\n# seule vérifiée suffit, la séquence est relevée avec le même matériel)\nOTHER_PORTIONS = 2\nOTHER_RADIUS = 1000.0  # m\nOTHER_SEARCH = 100  # photos de la séquence parmi lesquelles choisir les autres portions\nMIN_PHOTOS = 8\n# Hauteur de caméra entre photos voisines : écart-type et dérive maximaux. Le sol LiDAR HD\n# (±10 cm), les bordures, le dévers et la suspension du véhicule la font varier de plus\n# de 10 cm sur des séquences RTK (Pouilly-en-Auxois, 2026-10-15 : 5 points sur 72 refusés\n# à 10 cm, de 10,5 à 19,8 cm, ou dérive de 11 cm) ; un GPS non recalé varie de plusieurs\n# décimètres.\nMAX_SPREAD = 0.20  # m : écart-type\nMAX_DRIFT = 0.15  # m : écart entre les deux moitiés de la portion vérifiée\nOUTLIER = 4.0  # photos écartées au-delà de OUTLIER écarts médians absolus (corrigés)\nMIN_MAD = 0.02  # m : écart médian minimal (photos très régulières)\nCAMERA_RANGE = (0.5, 4.0)  # hauteur de caméra plausible (m)\nELEVATION_URL = \"https://data.geopf.fr/altimetrie/1.0/calcul/alti/rest/elevation.json\"\nDEGRADED_ADVICE = (\"Les mesures dépendent alors de la hauteur de caméra, de l'inclinaison de la caméra et, sans \"\n                   \"LiDAR HD, d'un sol approximatif : calez la hauteur de caméra sur une longueur connue et \"\n                   \"l'inclinaison sur deux objets verticaux, puis contrôlez les résultats.\")\n\n\ndef lidar_url(points):\n    \"\"\"URL des altitudes LiDAR HD (MNT) sous des points [(lon, lat)].\"\"\"\n    return ELEVATION_URL + \"?\" + urlencode({\n        \"lon\": \"|\".join(\"{:.7f}\".format(lon) for lon, _ in points),\n        \"lat\": \"|\".join(\"{:.7f}\".format(lat) for _, lat in points),\n        \"resource\": terrain.LIDAR_RESOURCE, \"zonly\": \"true\"}, safe=\"|\")\n\n\ndef _ground(data):\n    \"\"\"Altitudes LiDAR d'une réponse du service (None hors couverture).\"\"\"\n    out = []\n    for z in (data or {}).get(\"elevations\") or []:\n        try:\n            z = float(z[\"z\"] if isinstance(z, dict) else z)\n        except (KeyError, TypeError, ValueError):\n            z = None\n        out.append(z if z is not None and z > terrain.NODATA_BELOW else None)\n    return out\n\n\ndef result(precise, accuracy=None, lidar=None, reason=\"\", count=0, spread=None, height=None, transient=False):\n    \"\"\"Résultat d'une vérification : precise, accuracy (m, ou None : celle de la photo), lidar (LiDAR\n    HD publié sous la photo, None si inconnu), reason (texte), count et spread pour une séquence\n    vérifiée, height : hauteur de caméra calculée (altitude GPS moins sol LiDAR HD ; médiane de la\n    séquence vérifiée, ou celle de la photo de précision déclarée), None si inconnue. transient :\n    obtenu malgré un service injoignable, donc pas gardé pour la session (vérification refaite).\"\"\"\n    return {\"precise\": precise, \"accuracy\": accuracy, \"lidar\": lidar, \"reason\": reason, \"count\": count,\n            \"spread\": spread, \"height\": height, \"transient\": transient}\n\n\ndef degraded(res):\n    \"\"\"Mode dégradé : il manque la position vérifiée précise ou le LiDAR HD sous la photo\n    (False tant que la vérification n'est pas faite).\"\"\"\n    return bool(res) and not (res[\"precise\"] and res[\"lidar\"] is True)\n\n\ndef degraded_reasons(res):\n    \"\"\"Ce qui manque pour des mesures pleinement fiables (liste de textes).\"\"\"\n    out = []\n    if not res[\"precise\"]:\n        out.append(\"position GPS non vérifiée au décimètre ({})\".format(res[\"reason\"]))\n    if res[\"lidar\"] is False:\n        out.append(\"pas de LiDAR HD publié à cet endroit\")\n    elif res[\"lidar\"] is None:\n        out.append(\"présence du LiDAR HD non vérifiée (service d'altimétrie indisponible)\")\n    return out\n\n\ndef camera_suggestion(res):\n    \"\"\"Hauteur de caméra calculée à proposer dans le panneau : (hauteur, explication), ou None.\"\"\"\n    if not res or not res[\"precise\"] or res[\"lidar\"] is not True or res.get(\"height\") is None:\n        return None\n    if res[\"count\"]:\n        how = \"médiane de {} photos de la séquence, écart-type {:.0f} cm\".format(res[\"count\"], res[\"spread\"] * 100)\n    else:\n        how = \"photo de précision déclarée ±{:.0f} cm\".format(res[\"accuracy\"] * 100)\n    return res[\"height\"], (\"Hauteur de caméra calculée : altitude GPS de la caméra (NGF) moins le sol LiDAR HD \"\n                           \"({}). Cliquer pour remplir le champ « Caméra à ».\".format(how))\n\n\ndef state_text(res, accuracy=None, tilt=None):\n    \"\"\"Ligne d'état du panneau : précision de la position, présence du LiDAR HD et, si\n    `tilt` (texte, manquante) est donné, inclinaison de la photo.\"\"\"\n    tilt_text, tilt_missing = tilt or (\"\", False)\n    if not res:\n        text = \"Position GPS et LiDAR HD : vérification en cours…\"\n        return \"⚠ {} · {}\".format(text, tilt_text) if tilt_missing else (\n            \"{} · {}\".format(text, tilt_text) if tilt_text else text)\n    if res[\"precise\"]:\n        position = \"Position GPS vérifiée (±{} m)\".format(\"{:.2f}\".format(res[\"accuracy\"]).replace(\".\", \",\"))\n    elif accuracy is not None:\n        position = \"Position GPS non vérifiée (±{} m annoncés)\".format(\"{:g}\".format(accuracy).replace(\".\", \",\"))\n    else:\n        position = \"Position GPS non vérifiée\"\n    lidar = {True: \"LiDAR HD\", False: \"pas de LiDAR HD\", None: \"LiDAR HD non vérifié\"}[res[\"lidar\"]]\n    text = \" · \".join(t for t in (position, lidar, tilt_text) if t)\n    if degraded(res):\n        return \"⚠ \" + text + \" : mode de mesure dégradé\"\n    if tilt_missing:\n        return \"⚠ \" + text + \" : calez-la sur deux objets verticaux\"\n    return text\n\n\ndef verify_heights(pts):\n    \"\"\"Vérification d'une séquence d'après la hauteur de caméra (altitude GPS NGF moins sol\n    LiDAR HD) de photos voisines [(lon, lat, hauteur)] : résultat (voir result).\n\n    Robuste : les photos dont la hauteur s'écarte de plus de OUTLIER écarts (écart médian\n    absolu) sont écartées (pont, défaut du LiDAR, arrêt sous un arbre) ; la dispersion des\n    autres doit rester sous MAX_SPREAD. La hauteur doit aussi être la même sur les deux\n    moitiés de la portion vérifiée (à MAX_DRIFT près) : un GPS non recalé peut être lisse\n    sur quelques photos, mais il dérive.\"\"\"\n    heights = [h for _, _, h in pts]\n    median = statistics.median(heights)\n    mad = 1.4826 * statistics.median(abs(h - median) for h in heights)\n    kept = [p for p in pts if abs(p[2] - median) <= OUTLIER * max(mad, MIN_MAD)]\n    if len(kept) < MIN_PHOTOS:\n        return result(False, lidar=True, reason=\"hauteur de caméra trop dispersée ({} photos sur {})\".format(\n            len(kept), len(pts)))\n    spread, height = statistics.pstdev([h for _, _, h in kept]), statistics.median([h for _, _, h in kept])\n    # Deux moitiés le long de la trajectoire (axe principal des positions)\n    lon0, lat0 = kept[0][0], kept[0][1]\n    xy = [((lon - lon0) * 111320.0 * math.cos(math.radians(lat0)), (lat - lat0) * 111320.0) for lon, lat, _ in kept]\n    mx, my = sum(x for x, _ in xy) / len(xy), sum(y for _, y in xy) / len(xy)\n    sxx = sum((x - mx) ** 2 for x, _ in xy)\n    syy = sum((y - my) ** 2 for _, y in xy)\n    sxy = sum((x - mx) * (y - my) for x, y in xy)\n    a = 0.5 * math.atan2(2 * sxy, sxx - syy)\n    order = sorted(range(len(kept)), key=lambda i: xy[i][0] * math.cos(a) + xy[i][1] * math.sin(a))\n    half = len(order) // 2\n    drift = abs(statistics.median(kept[i][2] for i in order[:half]) -\n                statistics.median(kept[i][2] for i in order[half:]))\n    precise = spread <= MAX_SPREAD and drift <= MAX_DRIFT and CAMERA_RANGE[0] <= height <= CAMERA_RANGE[1]\n    dropped = len(pts) - len(kept)\n    note = \" ({} écartée{})\".format(dropped, \"s\" if dropped > 1 else \"\") if dropped else \"\"\n    if precise:\n        reason = \"position vérifiée : hauteur de caméra constante à {:.0f} cm près sur {} photos{}\".format(\n            spread * 100, len(kept), note)\n    elif drift > MAX_DRIFT and spread <= MAX_SPREAD:\n        reason = \"position non vérifiée : hauteur de caméra qui dérive de {:.0f} cm le long de la séquence\".format(\n            drift * 100)\n    else:\n        reason = \"position non vérifiée : hauteur de caméra variable de {:.0f} cm sur {} photos\".format(\n            spread * 100, len(kept))\n    return result(precise, VERIFIED_ACCURACY if precise else None, True, reason, len(kept), spread, height)\n\n\nclass PrecisionChecker:\n    \"\"\"Vérifications par séquence, gardées pour la session.\"\"\"\n\n    def __init__(self):\n        self._results = {}  # séquence -> résultat\n        self._pending = {}  # séquence -> rappels en attente du résultat\n\n    def known(self, item):\n        \"\"\"Résultat déjà connu pour la séquence de la photo, ou None.\"\"\"\n        return self._results.get((item or {}).get(\"collection\"))\n\n    def check(self, item, callback):\n        \"\"\"Précision de la photo (fiche STAC) : callback(résultat) dès qu'il est connu.\"\"\"\n        sequence = item.get(\"collection\")\n        if sequence in self._results:\n            callback(self._results[sequence])\n            return\n        # Photo sans séquence : vérifiée seule (deux photos sans séquence ne partagent rien)\n        key = sequence if sequence is not None else (\"photo\", item.get(\"id\"))\n        if key in self._pending:\n            self._pending[key].append(callback)\n            return\n        self._pending[key] = [callback]\n\n        def done(res):\n            if sequence is not None and not res.get(\"transient\"):\n                self._results[sequence] = res\n            for cb in self._pending.pop(key, []):\n                cb(res)\n\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            done(result(False, reason=\"position de la photo inconnue\"))\n            return\n        accuracy = metadata.exif_accuracy(item)\n        if accuracy is not None and accuracy <= PRECISE_ACCURACY:\n            self._check_lidar(lon, lat, done, \"précision déclarée dans les métadonnées de la photo\", accuracy,\n                              host.ngf_altitude(lon, lat, metadata.item_altitude(item)))\n        elif metadata.gps_differential(item) and sequence:\n            self._check_sequence(item, sequence, lon, lat, done)\n        else:\n            self._check_lidar(lon, lat, done, \"pas de correction différentielle déclarée\")\n\n    def _check_lidar(self, lon, lat, done, reason, accuracy=None, camera_alt=None, transient=False):\n        \"\"\"Le LiDAR HD est-il publié sous la photo ? accuracy : précision déclarée suffisante, ou None ;\n        camera_alt : altitude NGF de la caméra, pour la hauteur de caméra d'une photo précise ;\n        transient : une étape précédente n'a pas pu joindre son service.\"\"\"\n        def got(data, error):\n            ground = _ground(data) if not error else []\n            lidar = None if error else bool(ground and ground[0] is not None)\n            height = None\n            if lidar and accuracy is not None and camera_alt is not None:\n                height = camera_alt - ground[0]\n                if not CAMERA_RANGE[0] <= height <= CAMERA_RANGE[1]:\n                    height = None\n            done(result(accuracy is not None, accuracy, lidar, reason, height=height,\n                        transient=transient or bool(error)))\n\n        host.fetch_json(lidar_url([(lon, lat)]), got, timeout_ms=terrain.TIMEOUT_MS)\n\n    def _check_sequence(self, item, sequence, lon, lat, done):\n        \"\"\"Portion de la séquence autour de la photo ; en cas d'échec, d'autres portions (voir\n        _other_portions) : une seule vérifiée suffit pour toute la séquence.\"\"\"\n        def first(kind, value):\n            if kind == \"photos\":\n                self._check_lidar(lon, lat, done, \"photos voisines indisponibles ({})\".format(value), transient=True)\n            elif kind == \"few\":\n                self._check_lidar(lon, lat, done, \"altitude GPS inexploitable ({} photos voisines)\".format(value))\n            elif kind == \"ground\":\n                done(result(False, reason=\"service d'altimétrie IGN indisponible ({})\".format(value), transient=True))\n            elif value[\"precise\"] or value[\"lidar\"] is not True:\n                done(value)  # vérifiée, ou pas de LiDAR HD ici : rien à chercher ailleurs\n            else:\n                self._other_portions(sequence, lon, lat, value, done)\n\n        self._portion(sequence, lon, lat, first)\n\n    def _portion(self, sequence, lon, lat, callback):\n        \"\"\"Vérifie la portion de séquence autour de (lon, lat) : callback(genre, valeur), genre\n        « photos » ou « ground » (service injoignable, valeur : l'erreur), « few » (trop peu\n        d'altitudes GPS, valeur : leur nombre) ou « result » (valeur : résultat).\"\"\"\n        def got_photos(data, error):\n            if error:\n                callback(\"photos\", error)\n                return\n            photos = []\n            for feat in (data or {}).get(\"features\") or []:\n                try:\n                    plon, plat = (float(v) for v in feat[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                ngf = host.ngf_altitude(plon, plat, metadata.item_altitude(feat))\n                if ngf is not None and feat.get(\"collection\", sequence) == sequence:\n                    photos.append((plon, plat, ngf))\n            if len(photos) < MIN_PHOTOS:\n                callback(\"few\", len(photos))\n                return\n            host.fetch_json(lidar_url([(p[0], p[1]) for p in photos]),\n                           lambda data, error: got_ground(photos, data, error), timeout_ms=terrain.TIMEOUT_MS)\n\n        def got_ground(photos, data, error):\n            if error:\n                callback(\"ground\", error)\n                return\n            pts = [(plon, plat, ngf - g) for (plon, plat, ngf), g in zip(photos, _ground(data)) if g is not None]\n            if len(pts) < MIN_PHOTOS:\n                callback(\"result\", result(False, lidar=False, reason=\"pas de LiDAR HD pour vérifier la position\"))\n                return\n            callback(\"result\", verify_heights(pts))\n\n        host.fetch_json(metadata.search_url(lon, lat, CHECK_RADIUS, CHECK_PHOTOS, sequence, host.api_url), got_photos)\n\n    def _other_portions(self, sequence, lon, lat, failed, done):\n        \"\"\"Portion autour de la photo refusée (failed) : jusqu'à OTHER_PORTIONS autres portions de\n        la séquence, à moins de OTHER_RADIUS, essayées l'une après l'autre (le service d'altimétrie\n        limite les rafales). La première vérifiée vaut pour toute la séquence ; si aucune ne\n        l'est, failed est retenu.\"\"\"\n        def got_photos(data, error):\n            if error:\n                done(dict(failed, transient=True))  # à refaire plus tard\n                return\n            centers, taken = [], [(lon, lat)]\n            candidates = []\n            for feat in (data or {}).get(\"features\") or []:\n                try:\n                    plon, plat = (float(v) for v in feat[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                if feat.get(\"collection\", sequence) == sequence:\n                    candidates.append((plon, plat))\n            # Les plus éloignées d'abord, assez loin les unes des autres pour ne pas se recouvrir\n            candidates.sort(key=lambda p: -_metres(p, (lon, lat)))\n            for p in candidates:\n                if len(centers) < OTHER_PORTIONS and all(_metres(p, q) >= 2 * CHECK_RADIUS for q in taken):\n                    centers.append(p)\n                    taken.append(p)\n            try_next(centers, 0)\n\n        def try_next(centers, tried):\n            if not centers:\n                if tried:\n                    plural = \"s\" if tried > 1 else \"\"\n                    done(dict(failed, reason=\"{} ; {} autre{p} portion{p} de la séquence non vérifiée{p}\".format(\n                        failed[\"reason\"], tried, p=plural)))\n                else:\n                    done(failed)\n                return\n            (clon, clat), rest = centers[0], centers[1:]\n\n            def got(kind, value):\n                if kind in (\"photos\", \"ground\"):\n                    done(dict(failed, transient=True))\n                elif kind == \"result\" and value[\"precise\"]:\n                    distance = _metres((clon, clat), (lon, lat))\n                    done(dict(value, reason=\"{}, à {:.0f} m de la photo (même séquence)\".format(\n                        value[\"reason\"], round(distance, -1))))\n                else:\n                    try_next(rest, tried + 1)\n\n            self._portion(sequence, clon, clat, got)\n\n        host.fetch_json(metadata.search_url(lon, lat, OTHER_RADIUS, OTHER_SEARCH, sequence, host.api_url), got_photos)\n\n\ndef _metres(a, b):\n    \"\"\"Distance (m) entre deux (lon, lat) proches.\"\"\"\n    dx = (b[0] - a[0]) * 111320.0 * math.cos(math.radians((a[1] + b[1]) / 2))\n    return math.hypot(dx, (b[1] - a[1]) * 111320.0)\n",
 "core/roads.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Axe de la route à l'endroit mesuré, pour la largeur perpendiculaire à la chaussée.\n\nLa direction du véhicule à la caméra n'est pas celle de la route au point mesuré, 10 à 20 m\nplus loin : en courbe, l'écart y atteint 3 à 5° (8 à 16° en courbe serrée), et aux carrefours\noù le véhicule tourne, la trajectoire coupe la route. Tests sur 419 points de la séquence imajbox\nde Pouilly-en-Auxois (12/10/2026) : les tronçons de la BD TOPO s'accordent avec la trajectoire\nà 0,4° en ligne droite et 0,8° en courbe, et suivent la route aux carrefours.\n\n1. BD TOPO (IGN, service WFS de la Géoplateforme, sans clé) : parmi les tronçons à moins de\n   MAX_DISTANCE m du milieu des deux bords cliqués, ceux plutôt perpendiculaires au segment\n   cliqué (une largeur traverse la route : à un carrefour, cela désigne la rue mesurée) ; le\n   plus proche donne l'axe, direction locale du tronçon sur ±TANGENT m.\n2. À défaut (hors de France, service injoignable, aucun tronçon) : direction de la trajectoire\n   de la séquence au plus près du point mesuré (photos voisines du milieu).\n3. À défaut : direction du véhicule à la caméra (axe porté par les clics).\n\nLes tronçons sont lus par maille d'environ 100 m, une fois par session ; une panne n'est pas\ngardée (nouvel essai après RETRY s).\n\"\"\"\n\nimport math\nimport time\nfrom urllib.parse import urlencode\n\nfrom . import host, metadata, triangulation\n\nWFS_URL = \"https://data.geopf.fr/wfs/ows\"\nLAYER = \"BDTOPO_V3:troncon_de_route\"\nCELL = 0.001  # degré (~100 m) : maille de lecture des tronçons\nMARGIN = 30.0  # m autour de la maille : tronçons proches d'un point du bord de la maille\nMAX_DISTANCE = 15.0  # m entre le milieu des bords cliqués et le tronçon\nTANGENT = 10.0  # m de part et d'autre : direction locale du tronçon\nMIN_CROSSING = 45.0  # degrés minimum entre le tronçon et le segment cliqué\nTRACK_RADIUS = 20.0  # m : photos de la séquence autour du point mesuré\nTRACK_PHOTOS = 3\nRETRY = 30.0  # s avant de réinterroger un service en panne\nPENDING = \"pending\"  # résultat de lookup quand une lecture est en cours\n\n\ndef _axis_diff(a, b):\n    \"\"\"Écart entre deux directions de droite (modulo 180°).\"\"\"\n    d = abs((a - b) % 180)\n    return min(d, 180 - d)\n\n\ndef _cell(lon, lat):\n    return int(math.floor(lon / CELL)), int(math.floor(lat / CELL))\n\n\ndef wfs_url(cell):\n    \"\"\"URL des tronçons de route de la maille (et de MARGIN m autour).\"\"\"\n    lon0, lat0 = cell[0] * CELL, cell[1] * CELL\n    dlat = MARGIN / 111320.0\n    dlon = MARGIN / (111320.0 * math.cos(math.radians(lat0 + CELL / 2)))\n    return WFS_URL + \"?\" + urlencode({\n        \"SERVICE\": \"WFS\", \"VERSION\": \"2.0.0\", \"REQUEST\": \"GetFeature\", \"TYPENAMES\": LAYER,\n        \"OUTPUTFORMAT\": \"application/json\", \"SRSNAME\": \"EPSG:4326\", \"COUNT\": 500,\n        \"BBOX\": \"{:.7f},{:.7f},{:.7f},{:.7f},urn:ogc:def:crs:EPSG::4326\".format(\n            lat0 - dlat, lon0 - dlon, lat0 + CELL + dlat, lon0 + CELL + dlon)})\n\n\ndef parse_sections(data):\n    \"\"\"Tronçons d'une réponse WFS (GeoJSON) : liste de dicts line ([(lon, lat)]), name.\"\"\"\n    out = []\n    for feat in (data or {}).get(\"features\") or []:\n        geom = feat.get(\"geometry\") or {}\n        props = feat.get(\"properties\") or {}\n        lines = geom.get(\"coordinates\") or []\n        if geom.get(\"type\") == \"LineString\":\n            lines = [lines]\n        elif geom.get(\"type\") != \"MultiLineString\":\n            continue\n        name = props.get(\"cpx_numero\") or props.get(\"nom_collaboratif_gauche\") or props.get(\"nature\") or \"\"\n        for line in lines:\n            try:\n                pts = [(float(c[0]), float(c[1])) for c in line]\n            except (TypeError, ValueError, IndexError):\n                continue\n            if len(pts) >= 2:\n                out.append({\"line\": pts, \"name\": str(name)})\n    return out\n\n\ndef _project(line, x, y):\n    \"\"\"(distance, abscisse curviligne) du point de la polyligne le plus proche de (x, y).\"\"\"\n    best, s = (float(\"inf\"), 0.0), 0.0\n    for (ax, ay), (bx, by) in zip(line, line[1:]):\n        length = math.hypot(bx - ax, by - ay)\n        if length == 0:\n            continue\n        t = max(0.0, min(1.0, ((x - ax) * (bx - ax) + (y - ay) * (by - ay)) / length ** 2))\n        d = math.hypot(x - ax - t * (bx - ax), y - ay - t * (by - ay))\n        if d < best[0]:\n            best = (d, s + t * length)\n        s += length\n    return best\n\n\ndef _at(line, s):\n    \"\"\"Point de la polyligne à l'abscisse curviligne s (bornée).\"\"\"\n    acc = 0.0\n    for (ax, ay), (bx, by) in zip(line, line[1:]):\n        length = math.hypot(bx - ax, by - ay)\n        if length > 0 and acc + length >= s:\n            t = max(0.0, (s - acc) / length)\n            return ax + t * (bx - ax), ay + t * (by - ay)\n        acc += length\n    return line[-1]\n\n\ndef road_axis(sections, lon, lat, crossing):\n    \"\"\"Axe de la route (dict axis, source, distance) au point (lon, lat), d'après les tronçons :\n    le plus proche à moins de MAX_DISTANCE m parmi ceux qui coupent la direction `crossing`\n    (cap du segment cliqué) d'au moins MIN_CROSSING°, ou None.\"\"\"\n    best = None\n    for sec in sections:\n        line = [triangulation._local(p[0], p[1], lon, lat) for p in sec[\"line\"]]\n        d, s = _project(line, 0.0, 0.0)\n        if d > MAX_DISTANCE or (best and d >= best[\"distance\"]):\n            continue\n        a, b = _at(line, s - TANGENT), _at(line, s + TANGENT)\n        if math.hypot(b[0] - a[0], b[1] - a[1]) < 1.0:\n            continue\n        axis = math.degrees(math.atan2(b[0] - a[0], b[1] - a[1])) % 360\n        if crossing is not None and _axis_diff(axis, crossing) < MIN_CROSSING:\n            continue  # rue parallèle au segment cliqué : pas celle qu'il traverse\n        source = \"BD TOPO\" + (\", \" + sec[\"name\"] if sec[\"name\"] else \"\")\n        best = {\"axis\": axis, \"source\": source, \"distance\": d}\n    return best\n\n\ndef trajectory_axis(features, sequence, lon, lat):\n    \"\"\"Direction de la trajectoire de la séquence près de (lon, lat) : axe principal des\n    positions de ses photos à moins de TRACK_RADIUS m (dict axis, source), ou None.\"\"\"\n    pts = []\n    for feat in (features or {}).get(\"features\") or []:\n        if sequence and feat.get(\"collection\", sequence) != sequence:\n            continue\n        try:\n            x, y = triangulation._local(*(float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]), lon, lat)\n        except (KeyError, TypeError, ValueError):\n            continue\n        if math.hypot(x, y) <= TRACK_RADIUS:\n            pts.append((x, y))\n    if len(pts) < TRACK_PHOTOS:\n        return None\n    mx, my = sum(p[0] for p in pts) / len(pts), sum(p[1] for p in pts) / len(pts)\n    sxx = sum((p[0] - mx) ** 2 for p in pts)\n    syy = sum((p[1] - my) ** 2 for p in pts)\n    sxy = sum((p[0] - mx) * (p[1] - my) for p in pts)\n    if sxx + syy < 4.0:\n        return None  # photos quasi confondues (arrêt)\n    angle = 0.5 * math.atan2(2 * sxy, sxx - syy)  # depuis l'est, sens trigonométrique\n    return {\"axis\": (90.0 - math.degrees(angle)) % 360, \"source\": \"trajectoire au point mesuré\"}\n\n\nclass RoadAxisProvider:\n    \"\"\"Axe de la route au point mesuré (voir le module), avec lectures en cache.\n\n    lookup est synchrone : il rend l'axe si les données sont là, PENDING si une lecture\n    vient d'être lancée (ready() sera appelé à son arrivée), None sinon.\"\"\"\n\n    def __init__(self):\n        self._sections = {}  # maille -> tronçons\n        self._tracks = {}  # (séquence, maille) -> réponse de la recherche des photos\n        self._pending = set()\n        self._failed = {}  # clé -> heure de la panne\n        self.ready = None  # appelé quand une lecture arrive\n\n    def lookup(self, lon, lat, crossing, sequence=None):\n        cell = _cell(lon, lat)\n        sections = self._get((\"bdtopo\", cell), self._sections, cell, lambda: wfs_url(cell), parse_sections)\n        if sections is PENDING:\n            return PENDING\n        res = road_axis(sections or [], lon, lat, crossing)\n        if res or not sequence:\n            return res\n        key = (sequence, cell)\n        track = self._get((\"track\",) + key, self._tracks, key,\n                          lambda: metadata.search_url(lon, lat, TRACK_RADIUS + 10, 20, sequence, host.api_url), lambda data: data)\n        if track is PENDING:\n            return PENDING\n        return trajectory_axis(track, sequence, lon, lat) if track else None\n\n    def _get(self, key, cache, cache_key, url, parse):\n        \"\"\"Données en cache, PENDING (lecture lancée ou en cours), ou None (panne récente).\"\"\"\n        if cache_key in cache:\n            return cache[cache_key]\n        if key in self._pending:\n            return PENDING\n        if time.monotonic() - self._failed.get(key, -RETRY) < RETRY:\n            return None\n        self._pending.add(key)\n\n        def done(data, error):\n            self._pending.discard(key)\n            if error:\n                self._failed[key] = time.monotonic()\n            else:\n                cache[cache_key] = parse(data)\n            if self.ready is not None:\n                self.ready()\n\n        host.fetch_json(url(), done, timeout_ms=15000)\n        return PENDING if key in self._pending else self._get(key, cache, cache_key, url, parse)\n",
 "core/terrain.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Profils d'altitude du terrain le long d'une visée (pour ground.intersect).\n\nSources, essayées dans l'ordre jusqu'à la première qui répond :\n1. le service d'altimétrie de la Géoplateforme IGN : MNT du LiDAR HD (50 cm) là où il\n   est publié, sinon RGE ALTI (1 m, France) ;\n2. un service en ligne de secours, plus grossier : Open-Meteo Copernicus 90 m (monde) ;\n3. à défaut, un sol plat et horizontal.\nUn profil est une liste [(distance horizontale en m, altitude)], depuis la photo.\n\nPente de la route plutôt que profil brut : la caméra roule sur la chaussée et les\npoints mesurés sont à moins de 20 m. Un MNT de terrain nu (RGE ALTI) contient fossés,\ntalus et bruit : un creux d'un mètre sous la visée allonge les distances de moitié.\nOn retient donc la droite de pente du terrain autour de la photo, ajustée de façon\nrobuste (Theil-Sen : pente médiane, insensible aux creux et bosses locaux), qui garde\nla vraie pente d'une rue. La fenêtre (10 m derrière la photo à 25 m devant) reste\nproche des points mesurés : sur 120 m, la droite suivait le relief lointain, et le sol\nmodélisé à 6 m pouvait être 0,3 m trop haut (mesures 15 % trop courtes, Pouilly-en-\nAuxois). Un fossé ou une bosse de moins de 10 m environ reste ignoré.\n\nSur un pont, le MNT de terrain nu donne le fond du cours d'eau sous le tablier :\nl'option « Mesure sur un pont » du panneau prend alors un sol plat et horizontal\n(bridge), sans interroger les services.\n\nLe service de secours a une maille de 90 m : seule sa pente générale a un sens.\nC'est aussi un modèle de surface (bâtiments compris) : une pente invraisemblable\nl'écarte. OpenTopoData (EU-DEM 25 m) a été retiré le 15/10/2026 : il ne répondait\nplus et n'envoie pas les en-têtes CORS qu'exige l'application web.\nGoogle Elevation n'est pas proposé : clé API et facturation obligatoires, et\nses conditions interdisent l'usage des données hors d'une carte Google.\n\"\"\"\n\nimport math\nfrom collections import OrderedDict\nfrom urllib.parse import urlencode\n\nfrom . import ground, host, triangulation\n\n# Fenêtre de la droite de pente : 10 m derrière la photo à 25 m devant, le long de la visée\nLINE_FROM, LINE_TO = -10.0, 25.0\nSAMPLES = 71  # tous les 0,5 m (241 au plus en une requête pour le service IGN)\nIGN_URL = \"https://data.geopf.fr/altimetrie/1.0/calcul/alti/rest/elevationLine.json\"\nIGN_RESOURCE = \"ign_rge_alti_wld\"\nIGN_LABEL = \"RGE ALTI (IGN), pente de la route\"\nLIDAR_RESOURCE = \"ign_lidar_hd_mnt_mono_wld\"  # MNT LiDAR HD 50 cm, publié département par département\nLIDAR_LABEL = \"LiDAR HD (IGN), profil de la chaussée\"\nLIDAR_LINE_LABEL = \"LiDAR HD (IGN), pente de la route\"  # profil incomplet : droite de pente\n# Sol sous la caméra assez exact pour en déduire la hauteur de caméra par l'altitude GPS : LiDAR\n# HD seulement (le RGE ALTI, au mètre et plus ancien, peut être décalé de 0,2 à 0,5 m, soit 10 à\n# 25 % d'erreur sur toutes les distances)\nPRECISE_LABELS = (LIDAR_LABEL, LIDAR_LINE_LABEL)\nMIN_COVERAGE = 0.8  # part minimale d'altitudes valides pour suivre le profil réel\nNODATA_BELOW = -9999.0  # le service IGN renvoie -99999 hors de sa couverture\nTIMEOUT_MS = 5000  # au-delà, on passe à la source suivante\n\n# Service de secours : altitudes ponctuelles, ajustées par une droite (pente générale).\n# Échantillons de 60 m derrière la photo à 120 m devant : assez large pour qu'une\n# maille de 90 m donne une pente, et sous la limite de 100 points par requête.\nCOARSE_FROM, COARSE_TO, COARSE_STEP = -60.0, 120.0, 7.5\nOPENMETEO_URL = \"https://api.open-meteo.com/v1/elevation\"\nOPENMETEO_LABEL = \"Copernicus 90 m (Open-Meteo), pente générale\"\n# Ces modèles sont des modèles de surface (bâtiments, arbres compris) : en ville, la\n# pente peut être faussée. Au-delà de cette pente, jugée invraisemblable pour une\n# rue, la source est écartée.\nMAX_COARSE_SLOPE = 0.12\nBRIDGE_LABEL = \"sol plat (mesure sur un pont)\"\n\n# Cache de la session, pour limiter les appels aux services : profils déjà calculés (même\n# point de vue, même direction au dixième de degré près : visée reprise, point recalé ; plus\n# grossier, le profil réel du LiDAR HD pourrait passer de l'autre côté d'une bordure)\n# et sources sans données autour d'un point (LiDAR HD pas encore publié, hors de France),\n# qui ne sont plus interrogées dans cette zone. Un service injoignable n'est pas mémorisé.\nCACHE_SIZE = 64\nCOVERAGE_CELL = 0.001  # degré (~100 m) : maille des zones sans données mémorisées\n\n\ndef _profile_key(lon, lat, yaw):\n    return round(lon, 6), round(lat, 6), int(round(yaw * 10)) % 3600\n\n\ndef _cell(lon, lat):\n    return int(math.floor(lon / COVERAGE_CELL)), int(math.floor(lat / COVERAGE_CELL))\n\n\nclass TerrainProvider:\n    def __init__(self):\n        self.bridge = False  # mesure sur un pont : sol plat, sans interroger les services\n        self._profiles = OrderedDict()  # clé (voir _profile_key) -> (profil, libellé, avertissement)\n        self._waiting = {}  # clé -> rappels en attente (même profil déjà demandé)\n        self._uncovered = set()  # (source, maille) : source sans données dans cette zone\n\n    def profile(self, lon, lat, yaw, callback):\n        \"\"\"Profil le long de la visée. callback(profil, libellé de la source, avertissement | None).\n\n        L'avertissement liste les sources écartées et pourquoi.\n        \"\"\"\n        if self.bridge:\n            callback(ground.flat_profile(), BRIDGE_LABEL, None)\n            return\n        key = _profile_key(lon, lat, yaw)\n        if key in self._profiles:\n            self._profiles.move_to_end(key)\n            callback(*self._profiles[key])\n            return\n        if key in self._waiting:\n            self._waiting[key].append(callback)\n            return\n        self._waiting[key] = [callback]\n        cell = _cell(lon, lat)\n        steps = [(name, step) for name, step in ((\"lidar\", self._lidar_step), (\"ign\", self._ign_step),\n                                                  (\"openmeteo\", self._openmeteo_step))\n                 if (name, cell) not in self._uncovered]\n        reasons = []\n\n        def finish(prof, label, cache):\n            res = (prof, label, \"; \".join(reasons) or None)\n            if cache:\n                self._profiles[key] = res\n                while len(self._profiles) > CACHE_SIZE:\n                    self._profiles.popitem(last=False)\n            for cb in self._waiting.pop(key, []):\n                cb(*res)\n\n        def next_step():\n            if not steps:\n                finish(ground.flat_profile(), ground.FLAT, False)  # à retenter : un service peut revenir\n                return\n            name, step = steps.pop(0)\n\n            def ok(prof, label):\n                finish(prof, label, True)\n\n            def failed(reason=None, uncovered=False):\n                if uncovered:  # pas de données ici : source inutile dans cette zone pour la session\n                    self._uncovered.add((name, cell))\n                if reason:  # LiDAR HD pas encore publié ici : repli silencieux sur le RGE ALTI\n                    reasons.append(reason)\n                next_step()\n\n            step(lon, lat, yaw, ok, failed)\n\n        next_step()\n\n    # ------------------------------------------------------------------\n    # Service d'altimétrie IGN\n    # ------------------------------------------------------------------\n    def _lidar_step(self, lon, lat, yaw, ok, failed):\n        \"\"\"MNT LiDAR HD : profil réel de la chaussée (voir real_profile), ou à défaut droite de pente.\"\"\"\n        def parsed(dists, values):\n            prof = real_profile(dists, values)\n            if prof is not None:\n                return prof, LIDAR_LABEL\n            prof = robust_profile(dists, values)\n            return (prof, LIDAR_LINE_LABEL) if prof is not None else None\n\n        self._ign_line(lon, lat, yaw, ok, lambda error: failed(uncovered=error is None), LIDAR_RESOURCE, parsed)\n\n    def _ign_step(self, lon, lat, yaw, ok, failed):\n        def no_data(error):\n            failed(\"service d'altimétrie IGN indisponible ({})\".format(error) if error else\n                   \"pas d'altitude IGN à cet endroit (hors de France ?)\", uncovered=error is None)\n\n        def parsed(dists, values):\n            prof = robust_profile(dists, values)\n            return (prof, IGN_LABEL) if prof is not None else None\n\n        self._ign_line(lon, lat, yaw, ok, no_data, IGN_RESOURCE, parsed)\n\n    def _ign_line(self, lon, lat, yaw, ok, no_data, resource, parse):\n        \"\"\"Profil d'une ressource du service IGN ; parse(distances, altitudes) → (profil, libellé)\n        ou None ; no_data(erreur ou None) si rien d'exploitable.\"\"\"\n        start = triangulation.offset(lon, lat, yaw, LINE_FROM)\n        end = triangulation.offset(lon, lat, yaw, LINE_TO)\n        params = {\n            \"lon\": \"{:.8f}|{:.8f}\".format(start[0], end[0]),\n            \"lat\": \"{:.8f}|{:.8f}\".format(start[1], end[1]),\n            \"resource\": resource,\n            \"sampling\": SAMPLES,\n            \"profile_mode\": \"simple\",\n        }\n        url = IGN_URL + \"?\" + urlencode(params, safe=\"|\")\n\n        def done(data, error):\n            samples = self._ign_samples(data, lon, lat, yaw) if not error and isinstance(data, dict) else None\n            res = parse(*samples) if samples else None\n            if res is not None:\n                ok(*res)\n            else:\n                no_data(error)\n\n        host.fetch_json(url, done, timeout_ms=TIMEOUT_MS)\n\n    @staticmethod\n    def _parse_ign(data, lon, lat, yaw):\n        \"\"\"Altitudes IGN → droite de pente (None si hors couverture).\"\"\"\n        samples = TerrainProvider._ign_samples(data, lon, lat, yaw)\n        return robust_profile(*samples) if samples else None\n\n    @staticmethod\n    def _ign_samples(data, lon, lat, yaw):\n        \"\"\"Altitudes IGN → (distances signées le long de la visée, altitudes), ou None.\"\"\"\n        dx, dy = math.sin(math.radians(yaw)), math.cos(math.radians(yaw))\n        dists, values = [], []\n        for pt in data.get(\"elevations\") or []:\n            try:\n                z = float(pt[\"z\"])\n                x, y = triangulation._local(float(pt[\"lon\"]), float(pt[\"lat\"]), lon, lat)\n            except (KeyError, TypeError, ValueError):\n                return None\n            dists.append(x * dx + y * dy)  # position signée le long de la visée\n            values.append(z)\n        return dists, values\n\n    # ------------------------------------------------------------------\n    # Service de secours (maille de 90 m) : pente générale\n    # ------------------------------------------------------------------\n    @staticmethod\n    def _coarse_points(lon, lat, yaw):\n        n = int(round((COARSE_TO - COARSE_FROM) / COARSE_STEP)) + 1\n        dists = [COARSE_FROM + i * COARSE_STEP for i in range(n)]\n        return dists, [triangulation.offset(lon, lat, yaw, s) for s in dists]\n\n    def _openmeteo_step(self, lon, lat, yaw, ok, failed):\n        dists, pts = self._coarse_points(lon, lat, yaw)\n        url = OPENMETEO_URL + \"?\" + urlencode({\n            \"latitude\": \",\".join(\"{:.7f}\".format(p[1]) for p in pts),\n            \"longitude\": \",\".join(\"{:.7f}\".format(p[0]) for p in pts),\n        }, safe=\",\")\n\n        def done(data, error):\n            values = data.get(\"elevation\") if not error and isinstance(data, dict) else None\n            self._coarse_done(dists, values, error, OPENMETEO_LABEL, \"Open-Meteo\", ok, failed)\n\n        host.fetch_json(url, done, timeout_ms=TIMEOUT_MS)\n\n    @staticmethod\n    def _coarse_done(dists, values, error, label, name, ok, failed):\n        if error:\n            failed(\"{} indisponible ({})\".format(name, error))\n            return\n        prof = robust_profile(dists, values)\n        if prof is None:\n            failed(\"pas d'altitude {} à cet endroit\".format(name), uncovered=True)\n            return\n        slope = (prof[1][1] - prof[0][1]) / (prof[1][0] - prof[0][0])\n        if abs(slope) > MAX_COARSE_SLOPE:\n            failed(\"pente {} invraisemblable ({:+.0f} %, bâtiments ?)\".format(name, slope * 100))\n        else:\n            ok(prof, label)\n\n\ndef robust_profile(dists, values):\n    \"\"\"Droite de pente z = a + b·s (Theil-Sen), renvoyée comme profil de 0 à MAX_DISTANCE.\n\n    Pente = médiane des pentes entre paires de points, ordonnée = médiane des\n    résidus : un creux ou une bosse sur moins d'un tiers de la fenêtre (pont,\n    fossé, talus) ne la déforme pas. None s'il manque trop d'altitudes.\n    \"\"\"\n    pts = []\n    for s, z in zip(dists, values or []):\n        try:\n            z = float(z)\n        except (TypeError, ValueError):\n            continue\n        if z == z and z > NODATA_BELOW:\n            pts.append((float(s), z))\n    if len(pts) < max(3, len(dists) // 2):\n        return None  # trop de trous (mer, hors couverture)\n    pts.sort()\n    pts = pts[::max(1, len(pts) // 120)]  # 120 points suffisent (≈ 7 000 paires)\n    slopes = sorted((z2 - z1) / (s2 - s1) for i, (s1, z1) in enumerate(pts)\n                    for s2, z2 in pts[i + 1:] if s2 - s1 > 1e-6)\n    slope = _median(slopes) if slopes else 0.0\n    z0 = _median([z - slope * s for s, z in pts])\n    return [(0.0, z0), (ground.MAX_DISTANCE, z0 + slope * ground.MAX_DISTANCE)]\n\n\ndef real_profile(dists, values):\n    \"\"\"Profil réel le long de la visée, depuis la photo (MNT LiDAR HD) : bordures, caniveau et\n    dévers y figurent, contrairement à la droite de pente.\n\n    Altitudes lissées par une médiane glissante sur trois échantillons (1,5 m) contre le bruit,\n    profil commençant sous la caméra (altitude interpolée à 0), prolongé au-delà des données par\n    la droite de pente jusqu'à MAX_DISTANCE. None s'il manque plus de 20 % des altitudes, ou\n    s'il n'y en a pas de part et d'autre de la photo.\n    \"\"\"\n    pts = []\n    for s, z in zip(dists, values or []):\n        try:\n            z = float(z)\n        except (TypeError, ValueError):\n            continue\n        if z == z and z > NODATA_BELOW:\n            pts.append((float(s), z))\n    line = robust_profile(dists, values)\n    if line is None or len(pts) < MIN_COVERAGE * len(dists):\n        return None\n    pts.sort()\n    zs = [z for _, z in pts]\n    smooth = [(s, _median(zs[max(0, i - 1):i + 2])) for i, (s, _) in enumerate(pts)]\n    before = [p for p in smooth if p[0] <= 0.0]\n    after = [p for p in smooth if p[0] > 0.0]\n    if not before or not after or after[0][0] - before[-1][0] > 2.0:\n        return None\n    (s1, z1), (s2, z2) = before[-1], after[0]\n    prof = [(0.0, z1 + (z2 - z1) * (0.0 - s1) / (s2 - s1))] + after\n    last_s, last_z = prof[-1]\n    if last_s < ground.MAX_DISTANCE:\n        slope = (line[1][1] - line[0][1]) / (line[1][0] - line[0][0])\n        prof.append((ground.MAX_DISTANCE, last_z + slope * (ground.MAX_DISTANCE - last_s)))\n    return prof\n\n\ndef _median(values):\n    values = sorted(values)\n    n = len(values)\n    return values[n // 2] if n % 2 else (values[n // 2 - 1] + values[n // 2]) / 2.0\n",
 "core/tools.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Outils de mesure communs aux hôtes (plugin QGIS, application web), hors MeasureTool\n(voir measures.py) :\n\n- photo_click : clic dans la photo affichée, converti en direction corrigée du calage,\n  avec la position (recalée), sa précision et l'axe de la route ;\n- Triangulator : visées d'un objet depuis plusieurs photos ;\n- CalibrationTool : clics de calage (inclinaison, cap et position, hauteur de caméra) ;\n- calibration_text, tilt_state : textes du calage et de l'inclinaison de la photo.\n\nLe dessin sur la carte vient de l'hôte (new_item), comme pour MeasureTool.\n\"\"\"\n\nimport math\nfrom datetime import datetime\n\nfrom . import host, metadata, triangulation\nfrom .calibration import REACH, CalibrationError\nfrom .measures import NullItem, _num\n\nLONE_RAY = 60.0  # longueur (m) d'une visée tant qu'elle n'en croise aucune autre\n\n\ndef photo_click(item, yaw, elev, cal, quality=None, pos=None, axis=None):\n    \"\"\"Clic dans la photo `item` (fiche STAC) : direction brute yaw/elev (degrés, cap absolu),\n    corrigée du calage `cal`. quality : vérification de la précision de la photo (voir\n    precision.PrecisionChecker), ou None ; pos : position du clic dans le repère de la photo\n    (radians, visionneuse web) ; axis : axe de la séquence (voir metadata.sequence_axis), à\n    défaut l'orientation de la photo. Retourne le clic (dict) ou None sans position.\"\"\"\n    try:\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n    except (KeyError, TypeError, ValueError):\n        return None\n    axis_source = \"séquence\"\n    if axis is None:\n        axis, axis_source = metadata.item_heading(item), \"orientation de la photo\"\n    pic, sequence = item.get(\"id\", \"\"), item.get(\"collection\")\n    cyaw, celev = cal.correct(pic, sequence, float(yaw), float(elev), lon, lat)\n    precise = bool(quality and quality[\"precise\"])\n    accuracy = _accuracy(item, quality)\n    fixed = cal.position(sequence, lon, lat)  # position recalée par les repères de la séquence\n    clon, clat, caccuracy = fixed if fixed else (lon, lat, accuracy)\n    # Position vérifiée précise : altitude NGF de la caméra (hauteur de caméra sans calage,\n    # voir measures.MeasureTool.camera_info)\n    camera_alt = host.ngf_altitude(lon, lat, metadata.item_altitude(item)) if precise else None\n    return {\"pic\": pic, \"lon\": clon, \"lat\": clat, \"camera_alt\": camera_alt,\n            \"gps\": [lon, lat], \"gps_accuracy\": accuracy,\n            \"yaw\": cyaw, \"elev\": celev, \"raw\": [float(yaw) % 360, float(elev)],\n            \"sequence\": sequence, \"accuracy\": caccuracy,\n            \"precise\": metadata.precise_heading(item) is not None,\n            \"axis\": axis, \"axis_source\": axis_source, \"pos\": pos}\n\n\ndef photo_sighting(item, heading, pitch, cal, quality=None):\n    \"\"\"Visée de triangulation depuis la photo `item` : cap brut du centre de la vue (degrés,\n    cap précis de la photo compris) et son inclinaison, corrigés du calage. Retourne la visée\n    (dict, voir triangulation.solve) ou None sans position.\"\"\"\n    try:\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n    except (KeyError, TypeError, ValueError):\n        return None\n    pic, sequence = item.get(\"id\", \"\"), item.get(\"collection\")\n    heading, _ = cal.correct(pic, sequence, float(heading), float(pitch), lon, lat)\n    fixed = cal.position(sequence, lon, lat)\n    clon, clat, accuracy = fixed if fixed else (lon, lat, _accuracy(item, quality))\n    return {\"pic\": pic, \"sequence\": sequence, \"lon\": clon, \"lat\": clat, \"heading\": heading,\n            \"accuracy\": accuracy, \"precise\": metadata.precise_heading(item) is not None,\n            \"heading_error\": cal.heading_error(sequence, lon, lat)}\n\n\ndef _accuracy(item, quality):\n    \"\"\"Précision de la position de la photo : vérifiée (quality), sinon celle des métadonnées.\"\"\"\n    if quality and quality[\"precise\"] and quality[\"accuracy\"] is not None:\n        return quality[\"accuracy\"]\n    return metadata.item_accuracy(item)\n\n\ndef tilt_state(cal, pic, pending=False):\n    \"\"\"(texte, manquante) : inclinaison de la photo pic, pour la ligne d'état (voir\n    precision.state_text). pending : inclinaison automatique en cours de calcul.\"\"\"\n    tilt = cal.tilt(pic) if pic else None\n    if tilt:\n        if tilt[\"source\"] == \"clics\":\n            return \"inclinaison calée à la main\", False\n        if tilt[\"source\"].startswith(\"clics + \"):\n            return \"inclinaison calée à la main et automatiquement (±{:.1f}°)\".format(\n                max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"), False\n        how = \"verticales de la photo\" if tilt[\"source\"] == \"verticales\" else \"pente et dévers LiDAR HD\"\n        return \"inclinaison calée ({}, ±{:.1f}°)\".format(how, max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"), False\n    if pending:\n        return \"inclinaison en cours de calcul…\", False\n    return \"inclinaison non calée\", True\n\n\ndef calibration_text(cal, pic, sequence, lon, lat):\n    \"\"\"Calage de la photo et de la séquence affichées (texte, vide sans calage).\"\"\"\n    parts = []\n    tilt = cal.tilt(pic) if pic else None\n    if tilt and tilt.get(\"source\", \"clics\") == \"clics\":\n        parts.append(\"inclinaison {:.1f}° corrigée{} ({} objet{})\".format(\n            tilt[\"tilt\"], \" en partie\" if tilt[\"partial\"] else \"\", tilt[\"count\"],\n            \"s\" if tilt[\"count\"] > 1 else \"\").replace(\".\", \",\"))\n    elif tilt and tilt[\"source\"].startswith(\"clics + \"):\n        parts.append(\"inclinaison {:.1f}° corrigée ({} objet{} cliqué{}, complété{} par {}, ±{:.1f}°)\".format(\n            tilt[\"tilt\"], tilt[\"count\"], *((\"s\", \"s\", \"s\") if tilt[\"count\"] > 1 else (\"\", \"\", \"\")),\n            \"les verticales de la photo\" if tilt[\"source\"].endswith(\"verticales\") else \"le LiDAR HD\",\n            max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"))\n    elif tilt and tilt[\"source\"] == \"verticales\":\n        parts.append(\"inclinaison {:.1f}° corrigée automatiquement ({} verticales de la photo, ±{:.1f}°)\".format(\n            tilt[\"tilt\"], tilt[\"count\"], max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"))\n    elif tilt:\n        parts.append(\"inclinaison {:.1f}° estimée par la pente et le dévers LiDAR HD (±{:.1f}°, modèle vérifié \"\n                     \"sur {} photos de la séquence)\".format(tilt[\"tilt\"], tilt[\"sigma\"], tilt[\"count\"]).replace(\".\", \",\"))\n    camera = cal.camera(sequence) if sequence else None\n    if camera:\n        text = \"caméra à {:.2f} m (±{:.2f} m, {} référence{})\".format(\n            camera[\"height\"], camera[\"sigma\"], camera[\"count\"], \"s\" if camera[\"count\"] > 1 else \"\").replace(\".\", \",\")\n        if camera.get(\"legacy\"):\n            text += (\", dont {} d'une version précédente, sans l'inclinaison automatique : refaites le calage\"\n                     .format(camera[\"legacy\"]))\n        parts.append(text)\n    pose = cal.pose(sequence, lon, lat) if sequence else None\n    if pose:\n        text = \"cap {:+.2f}° (±{:.2f}°)\".format(pose[\"offset\"], pose[\"sigma\"])\n        if pose[\"positioned\"]:\n            sx, sy = pose[\"shift\"]\n            text += \", position décalée de {:.2f} m vers {:.0f}° (±{:.2f} m)\".format(\n                math.hypot(sx, sy), math.degrees(math.atan2(sx, sy)) % 360, pose[\"shift_sigma\"])\n        text += \" · {} repère{}\".format(pose[\"count\"], \"s\" if pose[\"count\"] > 1 else \"\")\n        if pose[\"count\"] > 3:\n            text += \", écart {:.2f}°\".format(pose[\"residual\"])\n        parts.append(text.replace(\".\", \",\"))\n    elif sequence and cal.landmarks.get(sequence):\n        parts.append(\"recalage de la séquence hors de portée (photo à plus de {:.0f} m des repères)\".format(\n            REACH))\n    return \"Calage : \" + \" · \".join(parts) if parts else \"\"\n\n\nclass Triangulator:\n    \"\"\"Visées en cours et point d'intersection. Le dessin des visées sur la carte vient de\n    l'hôte (new_item), l'enregistrement aussi (attributes donne les valeurs).\"\"\"\n\n    def __init__(self):\n        self.sightings = []  # dicts : pic, lon, lat, heading, accuracy, precise\n        self.result = None\n        self.error = None\n        self.item = None\n\n    def new_item(self):\n        \"\"\"Dessin des visées et du point sur la carte : set_data(visées [(lon, lat, lon, lat)],\n        point (lon, lat) ou None), remove(). Remplacé par l'hôte.\"\"\"\n        return NullItem()\n\n    # ------------------------------------------------------------------\n    def add(self, sighting):\n        \"\"\"Ajoute une visée (remplace celle déjà faite depuis la même photo).\"\"\"\n        self.sightings = [s for s in self.sightings if s[\"pic\"] != sighting[\"pic\"]] + [sighting]\n        self._compute()\n        return self.status()\n\n    def clear(self):\n        self.sightings, self.result, self.error = [], None, None\n        self._draw()\n\n    def remove(self):\n        if self.item is not None:\n            self.item.remove()\n            self.item = None\n\n    def _compute(self):\n        self.result, self.error = None, None\n        if len(self.sightings) >= 2:\n            try:\n                self.result = triangulation.solve(self.sightings)\n            except triangulation.TriangulationError as exc:\n                self.error = str(exc)\n        self._draw()\n\n    def _draw(self):\n        if self.item is None:\n            if not self.sightings:\n                return\n            self.item = self.new_item()\n        rays = []\n        for i, s in enumerate(self.sightings):\n            length = self.result[\"distances\"][i] * 1.15 + 3 if self.result else LONE_RAY\n            end = triangulation.offset(s[\"lon\"], s[\"lat\"], s[\"heading\"], length)\n            rays.append((s[\"lon\"], s[\"lat\"]) + end)\n        self.item.set_data(rays, (self.result[\"lon\"], self.result[\"lat\"]) if self.result else None)\n\n    # ------------------------------------------------------------------\n    def status(self):\n        n = len(self.sightings)\n        if n == 0:\n            return (\"Placez le réticule sur l'objet puis « Viser ». Recommencez depuis une autre \"\n                    \"photo, sur le côté de l'objet.\")\n        if n == 1:\n            return \"1 visée. Changez de photo, visez le même objet puis « Viser » à nouveau.\"\n        if self.error:\n            return \"{} visées : {}\".format(n, self.error)\n        r = self.result\n        text = \"{} visées : point à {} m · croisement {}° · incertitude ±{} m\".format(\n            n, \" / \".join(_num(d) for d in r[\"distances\"]), _num(r[\"angle\"], 0), _num(r[\"uncertainty\"]))\n        if n > 2:\n            text += \" · écart des visées {} m\".format(_num(r[\"rms\"]))\n        text += \" · GPS ±{} m\".format(_num(r[\"gps\"]))\n        if r[\"gps_assumed\"]:\n            text += \" (précision inconnue pour certaines photos : {} m supposés)\".format(\n                _num(triangulation.GPS_ACCURACY, 0))\n        if r[\"angle\"] < 15:\n            text += \". Croisement faible : une visée plus latérale améliorerait le point.\"\n        if r[\"gps\"] > triangulation.GPS_WARNING:\n            text += (\". Position GPS des photos imprécise (±{} m) : visez depuis des photos mieux \"\n                     \"positionnées, ou d'autres séquences.\".format(_num(r[\"gps\"])))\n        return text\n\n    def attributes(self):\n        \"\"\"Attributs du point triangulé (couche « points triangulés » du plugin, export de\n        l'application web), ou None sans résultat.\"\"\"\n        r = self.result\n        if r is None:\n            return None\n        return {\n            \"nb_visees\": len(self.sightings),\n            \"angle\": round(r[\"angle\"], 1),\n            \"incert_m\": round(r[\"uncertainty\"], 2),\n            \"ecart_m\": round(r[\"rms\"], 2),\n            \"dist_max_m\": round(max(r[\"distances\"]), 1),\n            \"gps_m\": round(r[\"gps\"], 1),\n            \"photos\": \",\".join(s[\"pic\"] for s in self.sightings),\n            \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n        }\n\n\nclass CalibrationTool:\n    \"\"\"Clics de calage (voir core/calibration.py) : pied et sommet d'objets verticaux\n    (inclinaison de la photo), ou repère cliqué dans la photo puis sur la carte\n    (cap de la séquence).\"\"\"\n\n    MAP_NAME = \"la carte\"  # dans les consignes : « la carte QGIS » dans le plugin\n\n    def __init__(self, calibration, current, reference=None):\n        self.calibration = calibration\n        self.current = current  # () -> (photo, séquence) affichées\n        self.reference = reference  # () -> (\"ground\" | \"height\", longueur connue en m)\n        self.mode = \"tilt\"\n        self.clicks = []  # clics en attente (dicts de PanoramaxDock.photoClicked)\n        self.error = None\n        self.last = None  # résultat du dernier calage (texte)\n        self.new_camera = None  # hauteur de caméra de la séquence, juste calée (à reporter dans le panneau)\n        self.item = None\n\n    def new_item(self):\n        \"\"\"Dessin des visées vers les repères (mode cap), comme Triangulator.new_item.\"\"\"\n        return NullItem()\n\n    def set_mode(self, mode):\n        self.mode = mode\n        self.reset()\n\n    def needs_profile(self):\n        \"\"\"Le prochain clic doit-il toucher le sol ? (hauteur de caméra, sauf sommet d'un objet)\"\"\"\n        if self.mode != \"camera\":\n            return False\n        return self._reference()[0] == \"ground\" or not self.clicks\n\n    def _reference(self):\n        return self.reference() if self.reference else (\"ground\", 0.0)\n\n    def waiting_map(self):\n        \"\"\"Le repère cliqué dans la photo attend son clic sur la carte.\"\"\"\n        return self.mode == \"heading\" and len(self.clicks) == 1\n\n    def add_click(self, click, notice=None):\n        self.error, self.last = None, None\n        if self.mode == \"camera\":\n            self._add_camera_click(click)\n        elif self.mode == \"heading\":\n            if not click.get(\"sequence\"):\n                self.error = \"Séquence de la photo inconnue : recalage du cap impossible.\"\n            else:\n                self.clicks = [click]\n        else:\n            if self.clicks and self.clicks[0][\"pic\"] != click[\"pic\"]:\n                self.clicks = []  # le sommet doit être sur la même photo que le pied\n            self.clicks.append(click)\n            if len(self.clicks) == 2:\n                bottom, top = (tuple(c[\"raw\"]) for c in self.clicks)\n                self.clicks = []\n                try:\n                    r = self.calibration.add_vertical(click[\"pic\"], bottom, top)\n                except CalibrationError as exc:\n                    self.error = str(exc)\n                else:\n                    self.last = \"Inclinaison de la photo : {}° vers {}°{}.\".format(\n                        _num(r[\"tilt\"], 2), _num(r[\"toward\"], 0),\n                        \"\" if r[\"residual\"] is None else \", écart des objets {}°\".format(_num(r[\"residual\"], 2)))\n                    if r[\"partial\"]:\n                        self.last += (\" Correction partielle : cliquez un autre objet vertical, à environ 90° \"\n                                      \"du premier, pour corriger toute l'inclinaison.\")\n        self._draw()\n        return self.status()\n\n    def _add_camera_click(self, click):\n        if not click.get(\"sequence\"):\n            self.error = \"Séquence de la photo inconnue : calage de la hauteur impossible.\"\n            return\n        if self.clicks and self.clicks[0][\"pic\"] != click[\"pic\"]:\n            self.clicks = []  # les deux clics se font sur la même photo\n        self.clicks.append(click)\n        if len(self.clicks) < 2:\n            return\n        clicks, self.clicks = self.clicks, []\n        kind, known = self._reference()\n        try:\n            r = self.calibration.add_camera_height(click[\"sequence\"], kind, clicks, known)\n        except CalibrationError as exc:\n            self.error = str(exc)\n        else:\n            self.new_camera = self.calibration.camera(click[\"sequence\"])[\"height\"]\n            self.last = \"Caméra à {} m (±{} m) d'après cette référence de {} m.\".format(\n                _num(r[\"height\"], 2), _num(r[\"sigma\"], 2), _num(known, 2))\n            if self.calibration.camera(click[\"sequence\"])[\"count\"] > 1:\n                self.last += \" Avec les références précédentes : {} m.\".format(_num(self.new_camera, 2))\n            self.last += \" Hauteur reportée dans le réglage « Caméra à ».\"\n            if r[\"sigma\"] > 0.25:\n                self.last += \" Référence trop loin ou trop courte pour être précise : prenez-en une plus proche.\"\n\n    def add_map_point(self, mlon, mlat):\n        \"\"\"Repère cliqué sur la carte (WGS84), après son clic dans la photo.\"\"\"\n        if not self.waiting_map():\n            return self.status()\n        c, self.clicks = self.clicks[0], []\n        # Position et précision GPS d'origine : le recalage ne doit pas partir d'une position déjà recalée\n        lon, lat = c.get(\"gps\") or (c[\"lon\"], c[\"lat\"])\n        accuracy = c.get(\"gps_accuracy\", c.get(\"accuracy\"))\n        survey = bool(c.get(\"precise\")) and accuracy is not None and accuracy <= triangulation.SURVEY_ACCURACY\n        try:\n            r = self.calibration.add_landmark(c[\"sequence\"], c[\"pic\"], lon, lat, c[\"raw\"][0],\n                                              c[\"raw\"][1], mlon, mlat, accuracy, survey)\n        except CalibrationError as exc:\n            self.error = str(exc)\n        else:\n            pose = self.calibration.pose(c[\"sequence\"])\n            n = pose[\"count\"]\n            self.last = \"Repère {} à {} m (écart de cap brut {}°).\".format(\n                n, _num(r[\"distance\"], 0), _num(r[\"offset\"], 2))\n            if pose[\"positioned\"]:\n                self.last += \" Position recalée à ±{} m, cap à ±{}°.\".format(\n                    _num(pose[\"shift_sigma\"], 2), _num(pose[\"sigma\"], 2))\n            elif n >= 3:\n                self.last += (\" Repères mal répartis pour recaler la position : ajoutez-en dans d'autres \"\n                              \"directions (devant, derrière, sur les côtés).\")\n            else:\n                self.last += (\" Cap corrigé à ±{}°. À partir de 3 repères bien répartis autour de la photo, \"\n                              \"la position est recalée aussi.\".format(_num(pose[\"sigma\"], 2)))\n        self._draw()\n        return self.status()\n\n    def reset(self):\n        \"\"\"Abandonne les clics en attente (le calage déjà fait est conservé).\"\"\"\n        self.clicks, self.error, self.last = [], None, None\n        self._draw()\n\n    def clear(self):\n        \"\"\"Efface le calage du mode : inclinaison de la photo ou cap de la séquence affichée.\"\"\"\n        pic, sequence = self.current()\n        if self.mode == \"tilt\" and pic:\n            self.calibration.clear_tilt(pic)\n        elif self.mode == \"heading\" and sequence:\n            self.calibration.clear_heading(sequence)\n        elif self.mode == \"camera\" and sequence:\n            self.calibration.clear_camera(sequence)\n        self.reset()\n\n    def remove(self):\n        if self.item is not None:\n            self.item.remove()\n            self.item = None\n\n    def _draw(self):\n        \"\"\"Carte : visées vers les repères de la séquence affichée (mode cap).\"\"\"\n        _, sequence = self.current()\n        obs = self.calibration.landmarks.get(sequence, []) if self.mode == \"heading\" else []\n        if self.item is None:\n            if not obs:\n                return\n            self.item = self.new_item()\n        rays = [(o[\"lon\"], o[\"lat\"], o[\"mlon\"], o[\"mlat\"]) for o in obs]\n        self.item.set_data(rays, (obs[-1][\"mlon\"], obs[-1][\"mlat\"]) if obs else None)\n\n    def viewer_marks(self):\n        points = []\n        for c in self.clicks:\n            pos = c.get(\"pos\") or [None, None]\n            points.append({\"pic\": c.get(\"pic\"), \"yaw\": pos[0], \"pitch\": pos[1],\n                           \"abs_yaw\": c[\"raw\"][0], \"elev\": c[\"raw\"][1]})\n        return {\"points\": points, \"label\": \"\", \"beside\": self.mode in (\"tilt\", \"camera\")}\n\n    def status(self):\n        n = len(self.clicks)\n        text = \"\"\n        if self.error:\n            text = self.error + \" \"\n        elif self.last:\n            text = self.last + \" \"\n        if self.mode == \"camera\":\n            kind, known = self._reference()\n            if kind == \"height\":\n                if n == 1:\n                    return text + \"Cliquez le sommet de l'objet, sur la même photo.\"\n                return text + (\"Cliquez au pied d'un objet de hauteur connue ({} m), puis à son sommet. \"\n                               \"Choisissez-le proche (moins de 10–15 m).\".format(_num(known, 2)))\n            if n == 1:\n                return text + \"Cliquez la seconde extrémité, au sol, sur la même photo.\"\n            return text + (\"Cliquez au sol les deux extrémités d'une longueur connue ({} m) : trait de marquage, \"\n                           \"place de stationnement, ou longueur mesurée sur la carte. Choisissez-la proche \"\n                           \"(moins de 10–15 m) et plutôt en travers de la vue : dans l'axe, elle est moins précise.\".format(_num(known, 2)))\n        if self.mode == \"tilt\":\n            if n == 1:\n                return text + \"Cliquez le sommet du même objet.\"\n            return text + (\"Cliquez le pied puis le sommet d'un objet bien vertical (poteau, angle de façade). \"\n                           \"Deux objets à environ 90° l'un de l'autre corrigent toute l'inclinaison de la photo.\")\n        if n == 1:\n            return text + (\"Cliquez maintenant ce même repère sur {} (glisser pour déplacer la carte, \"\n                           \"molette pour zoomer, Échap pour annuler).\".format(self.MAP_NAME))\n        return text + (\"Cliquez dans la photo un repère net, visible aussi sur la carte (poteau, angle de bâtiment). \"\n                       \"Un repère seul corrige le cap (choisissez-le lointain) ; trois repères ou plus, bien \"\n                       \"répartis autour de la photo, recalent aussi sa position. Le recalage vaut pour les photos \"\n                       \"de la séquence à moins de {} m.\".format(_num(REACH, 0)))\n",
 "core/triangulation.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Position d'un objet par intersection de visées (triangulation).\n\nChaque visée part de la position d'une photo dans une direction (cap absolu,\n0 = nord, sens horaire). Le point retenu est celui qui minimise la somme\npondérée des carrés des distances aux demi-droites de visée (moindres carrés) :\ndeux visées suffisent, chaque visée supplémentaire améliore et contrôle le\nrésultat. Le poids d'une visée est l'inverse du carré de son écart latéral\nprobable, qui cumule l'erreur de visée (croissante avec la distance) et la\nprécision de la position GPS de la photo : une visée lointaine ou une photo mal\npositionnée compte moins.\n\nCalcul dans un plan tangent local (quelques centaines de mètres au plus) :\nl'erreur due à la projection est négligeable devant la précision du GPS.\nModule sans dépendance à QGIS, pour pouvoir être testé seul.\n\"\"\"\n\nimport math\n\nEARTH_RADIUS = 6371008.8\nHEADING_ERROR = 1.0  # erreur de visée supposée (degrés) pour l'incertitude affichée\n# Matériel de relevé (GPS corrigé à SURVEY_ACCURACY m ou mieux, cap EXIF au centième) :\n# sur les photos imajbox à position RTK, le cap suit la trajectoire à 0,33° près (écart-type).\nSURVEY_HEADING_ERROR = 0.5\nSURVEY_ACCURACY = 2.0\nMIN_ANGLE = 3.0  # en dessous, les visées sont jugées parallèles\nMAX_DISTANCE = 500.0  # au-delà, le résultat n'a plus de sens avec des photos de rue\nGPS_ACCURACY = 3.0  # précision GPS supposée (m) quand la photo ne l'indique pas\nGPS_WARNING = 5.0  # au-delà, la position des photos limite nettement la précision du point\nITERATIONS = 4  # les poids dépendent des distances, donc du point : quelques passes suffisent\n\n\nclass TriangulationError(ValueError):\n    \"\"\"Visées inexploitables (message destiné à l'utilisateur).\"\"\"\n\n\ndef _local(lon, lat, lon0, lat0):\n    \"\"\"Coordonnées métriques (est, nord) autour de (lon0, lat0).\"\"\"\n    return (EARTH_RADIUS * math.radians(lon - lon0) * math.cos(math.radians(lat0)),\n            EARTH_RADIUS * math.radians(lat - lat0))\n\n\ndef _geographic(x, y, lon0, lat0):\n    return (lon0 + math.degrees(x / (EARTH_RADIUS * math.cos(math.radians(lat0)))),\n            lat0 + math.degrees(y / EARTH_RADIUS))\n\n\ndef offset(lon, lat, heading, distance):\n    \"\"\"Point situé à `distance` mètres de (lon, lat) dans la direction `heading`.\"\"\"\n    a = math.radians(heading)\n    return _geographic(distance * math.sin(a), distance * math.cos(a), lon, lat)\n\n\ndef crossing_angle(h1, h2):\n    \"\"\"Angle entre deux droites de visée, ramené entre 0 et 90°.\"\"\"\n    a = abs(h1 - h2) % 180.0\n    return min(a, 180.0 - a)\n\n\ndef heading_error(sighting):\n    \"\"\"Erreur de visée supposée (degrés) : celle du recalage du cap s'il y en a un\n    (\"heading_error\", voir calibration.py), plus faible pour le matériel de relevé.\"\"\"\n    if sighting.get(\"heading_error\") is not None:\n        return float(sighting[\"heading_error\"])\n    accuracy = sighting.get(\"accuracy\")\n    if sighting.get(\"precise\") and accuracy is not None and accuracy <= SURVEY_ACCURACY:\n        return SURVEY_HEADING_ERROR\n    return HEADING_ERROR\n\n\ndef _sigma(distance, accuracy, error=HEADING_ERROR):\n    \"\"\"Écart latéral probable d'une visée (m) : erreur de visée et position GPS.\"\"\"\n    lateral = max(distance, 0.0) * math.tan(math.radians(error))\n    return max(math.hypot(lateral, accuracy), 0.05)\n\n\ndef _normal(rays, weights):\n    \"\"\"Normales pondérées  Σ w (I - d dᵀ) : (a11, a12, a22, b1, b2).\"\"\"\n    a11 = a12 = a22 = b1 = b2 = 0.0\n    for (px, py, dx, dy), w in zip(rays, weights):\n        m11, m12, m22 = w * (1 - dx * dx), w * (-dx * dy), w * (1 - dy * dy)\n        a11 += m11\n        a12 += m12\n        a22 += m22\n        b1 += m11 * px + m12 * py\n        b2 += m12 * px + m22 * py\n    return a11, a12, a22, b1, b2\n\n\ndef _distances(rays, x, y):\n    \"\"\"Position du point le long de chaque visée (m).\"\"\"\n    return [(x - px) * dx + (y - py) * dy for px, py, dx, dy in rays]\n\n\ndef solve(sightings):\n    \"\"\"Intersection des visées.\n\n    sightings : liste de dicts avec au moins \"lon\", \"lat\", \"heading\", et\n    éventuellement \"accuracy\" (précision de la position GPS en m, None si inconnue)\n    \"precise\" (cap au centième de degré), \"heading_error\" (voir heading_error) et\n    \"sequence\" (erreurs communes aux photos d'une même séquence).\n    Retourne un dict : lon, lat, distances (m, une par visée), angle (° de\n    croisement le plus favorable), rms (écart moyen des visées au point, m),\n    uncertainty (rayon d'incertitude en m pour l'erreur de visée de chaque photo et la\n    précision GPS), gps (précision GPS la moins bonne, m), gps_assumed (vrai si\n    au moins une photo n'indique pas sa précision, GPS_ACCURACY est alors supposé).\n    Lève TriangulationError si les visées ne permettent pas de conclure.\n    \"\"\"\n    if len(sightings) < 2:\n        raise TriangulationError(\"Il faut au moins deux visées.\")\n    lon0 = sum(s[\"lon\"] for s in sightings) / len(sightings)\n    lat0 = sum(s[\"lat\"] for s in sightings) / len(sightings)\n\n    angle = max(crossing_angle(a[\"heading\"], b[\"heading\"])\n                for i, a in enumerate(sightings) for b in sightings[i + 1:])\n    if angle < MIN_ANGLE:\n        raise TriangulationError(\n            \"Visées presque parallèles ({:.0f}°) : visez l'objet depuis une photo plus \"\n            \"décalée sur le côté.\".format(angle))\n\n    rays, accuracies, errors = [], [], []\n    for s in sightings:\n        px, py = _local(s[\"lon\"], s[\"lat\"], lon0, lat0)\n        h = math.radians(s[\"heading\"])\n        rays.append((px, py, math.sin(h), math.cos(h)))\n        accuracies.append(s.get(\"accuracy\"))\n        errors.append(heading_error(s))\n    gps_assumed = any(a is None for a in accuracies)\n    accuracies = [GPS_ACCURACY if a is None else float(a) for a in accuracies]\n\n    # Normales  Σ w (I - d dᵀ) X = Σ w (I - d dᵀ) P ; première passe sans pondération,\n    # puis poids recalculés à partir des distances au point trouvé.\n    weights = [1.0] * len(rays)\n    for _ in range(ITERATIONS):\n        a11, a12, a22, b1, b2 = _normal(rays, weights)\n        det = a11 * a22 - a12 * a12\n        if abs(det) < 1e-9 * max(a11 + a22, 1e-12) ** 2:\n            raise TriangulationError(\"Visées parallèles : impossible de les croiser.\")\n        x = (a22 * b1 - a12 * b2) / det\n        y = (a11 * b2 - a12 * b1) / det\n        weights = [1.0 / _sigma(t, acc, e) ** 2 for t, acc, e in zip(_distances(rays, x, y), accuracies, errors)]\n\n    distances = _distances(rays, x, y)\n    residuals = [abs((x - px) * dy - (y - py) * dx) for px, py, dx, dy in rays]  # écart perpendiculaire\n    if min(distances) < 0.5:\n        raise TriangulationError(\n            \"Les visées ne se croisent pas devant les photos : vérifiez que vous visez \"\n            \"bien le même objet.\")\n    if max(distances) > MAX_DISTANCE:\n        raise TriangulationError(\n            \"Point trouvé à plus de {:.0f} m : visées trop peu sécantes ou objets \"\n            \"différents.\".format(MAX_DISTANCE))\n\n    # Incertitude : chaque visée est décalée latéralement d'environ _sigma (erreur de cap\n    # et position GPS). Covariance du point = (Σ w (I - d dᵀ))⁻¹, w = 1 / décalage² ;\n    # on garde le grand axe.\n    weights = [1.0 / _sigma(t, acc, e) ** 2 for t, acc, e in zip(distances, accuracies, errors)]\n    c11, c12, c22, _, _ = _normal(rays, weights)\n    cdet = c11 * c22 - c12 * c12\n    if cdet > 0:\n        # Valeurs propres de l'inverse = inverses des valeurs propres : on prend la plus petite\n        half = (c11 + c22) / 2.0\n        smallest = half - math.sqrt(max(half * half - cdet, 0.0))\n        uncertainty = 1.0 / math.sqrt(smallest) if smallest > 0 else float(\"inf\")\n    else:\n        uncertainty = float(\"inf\")\n\n    # Photos d'une même séquence : leur décalage de position GPS et leur erreur de cap (fixation\n    # de la caméra) sont presque les mêmes ; ils déplacent le point d'un bloc et ne se compensent\n    # pas entre visées. L'incertitude ne descend pas sous cette part commune.\n    sequences = {s.get(\"sequence\") for s in sightings}\n    if len(sequences) == 1 and None not in sequences:\n        n = len(sightings)\n        common = math.hypot(sum(accuracies) / n,\n                            sum(distances) / n * math.tan(math.radians(sum(errors) / n)))\n        uncertainty = max(uncertainty, common)\n\n    lon, lat = _geographic(x, y, lon0, lat0)\n    return {\n        \"lon\": lon,\n        \"lat\": lat,\n        \"distances\": distances,\n        \"angle\": angle,\n        \"rms\": math.sqrt(sum(r * r for r in residuals) / len(residuals)),\n        \"uncertainty\": uncertainty,\n        \"gps\": max(accuracies),\n        \"gps_assumed\": gps_assumed,\n    }\n",
 "geoid.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Altitude NGF-IGN69 dans le navigateur : grille RAF20 de l'IGN (ondulation du géoïde),\ncomme PROJ dans le plugin (voir altitude.py du plugin).\n\nLa grille est celle que PROJ télécharge (cdn.proj.org, GeoTIFF de 340 Ko, licence\nouverte Etalab) : 421 × 381 nœuds, 1/30° × 0,025°, France métropolitaine. Lue ici sans\nGDAL : tuiles compressées (deflate), prédicteur des flottants (TIFF, prédicteur 3).\n\"\"\"\n\nimport struct\nimport zlib\nfrom itertools import accumulate\n\nURL = \"https://cdn.proj.org/fr_ign_RAF20.tif\"\nGEOID_RANGE = (30.0, 70.0)  # écart plausible entre ellipsoïde et NGF-IGN69 en France (m), comme le plugin\n\n\nclass GeoidError(ValueError):\n    pass\n\n\ndef _tags(data):\n    bo = \"<\" if data[:2] == b\"II\" else \">\"\n    if data[2:4] != (b\"*\\x00\" if bo == \"<\" else b\"\\x00*\"):\n        raise GeoidError(\"pas un fichier TIFF\")\n    off = struct.unpack(bo + \"I\", data[4:8])[0]\n    n = struct.unpack(bo + \"H\", data[off:off + 2])[0]\n    sizes, formats = {2: 1, 3: 2, 4: 4, 11: 4, 12: 8}, {3: \"H\", 4: \"I\", 11: \"f\", 12: \"d\"}\n    tags = {}\n    for i in range(n):\n        entry = off + 2 + 12 * i\n        tag, kind, count = struct.unpack(bo + \"HHI\", data[entry:entry + 8])\n        size = sizes.get(kind, 1) * count\n        if size <= 4:\n            raw = data[entry + 8:entry + 8 + size]\n        else:\n            start = struct.unpack(bo + \"I\", data[entry + 8:entry + 12])[0]\n            raw = data[start:start + size]\n        fmt = formats.get(kind)\n        tags[tag] = raw if fmt is None else struct.unpack(bo + fmt * count, raw)\n    return bo, tags\n\n\nclass Grid:\n    \"\"\"Grille d'ondulation du géoïde (m), interpolée linéairement entre les nœuds.\"\"\"\n\n    def __init__(self, data):\n        bo, t = _tags(data)\n        self.cols, self.rows = t[256][0], t[257][0]\n        if t[258][0] != 32 or t[339][0] != 3 or t[277][0] != 1:\n            raise GeoidError(\"format de grille inattendu (flottants 32 bits, une bande)\")\n        compression, predictor = t[259][0], t.get(317, (1,))[0]\n        if compression not in (1, 8) or predictor not in (1, 3):\n            raise GeoidError(\"compression de grille non prise en charge\")\n        if t.get(34735) and dict(zip(t[34735][4::4], t[34735][7::4])).get(1025) != 2:\n            raise GeoidError(\"grille attendue aux nœuds (PixelIsPoint)\")\n        self.dx, self.dy = t[33550][0], t[33550][1]\n        self.lon0, self.lat0 = t[33922][3], t[33922][4]\n        tw, th = t[322][0], t[323][0]\n        across = (self.cols + tw - 1) // tw\n        self.values = [[0.0] * self.cols for _ in range(self.rows)]\n        for k, (start, size) in enumerate(zip(t[324], t[325])):\n            raw = data[start:start + size]\n            if compression == 8:\n                raw = zlib.decompress(raw)\n            ty, tx = divmod(k, across)\n            for r in range(th):\n                row = ty * th + r\n                if row >= self.rows:\n                    break\n                line = raw[r * tw * 4:(r + 1) * tw * 4]\n                if predictor == 3:  # octets différenciés, rangés par plan (poids fort d'abord)\n                    line = bytes(v & 0xFF for v in accumulate(line))\n                    line = bytes(b for i in range(tw) for b in (line[i], line[tw + i], line[2 * tw + i],\n                                                                 line[3 * tw + i]))\n                    values = struct.unpack(\">\" + \"f\" * tw, line)\n                else:\n                    values = struct.unpack(bo + \"f\" * tw, line)\n                for c in range(tw):\n                    col = tx * tw + c\n                    if col < self.cols:\n                        self.values[row][col] = values[c]\n\n    def undulation(self, lon, lat):\n        \"\"\"Ondulation du géoïde (m) au point, ou None hors de la grille.\"\"\"\n        x, y = (lon - self.lon0) / self.dx, (self.lat0 - lat) / self.dy\n        if not (0 <= x <= self.cols - 1 and 0 <= y <= self.rows - 1):\n            return None\n        i, j = min(int(x), self.cols - 2), min(int(y), self.rows - 2)\n        fx, fy = x - i, y - j\n        v = self.values\n        return ((v[j][i] * (1 - fx) + v[j][i + 1] * fx) * (1 - fy)\n                + (v[j + 1][i] * (1 - fx) + v[j + 1][i + 1] * fx) * fy)\n\n\ndef ngf_altitude(grid, lon, lat, ellipsoidal):\n    \"\"\"Altitude NGF-IGN69 (m) d'un point d'altitude ellipsoïdale, ou None (pas de grille, hors\n    de France, valeur invraisemblable).\"\"\"\n    if grid is None or ellipsoidal is None:\n        return None\n    n = grid.undulation(float(lon), float(lat))\n    if n is None or not GEOID_RANGE[0] <= n <= GEOID_RANGE[1]:\n        return None\n    return float(ellipsoidal) - n\n",
 "web_app.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Application de mesure dans le navigateur : le cœur de calcul du plugin (core/), piloté par\nla page (src/app.js). Même enchaînement que le plugin QGIS (plugin.py, viewer_dock.py) :\n\n- clic dans la photo → direction corrigée du calage (tools.photo_click) → profil du terrain\n  le long de la visée → point 3D → mesure (measures.MeasureTool) ;\n- triangulation : visée du centre de la vue (tools.Triangulator) ;\n- calages : inclinaison, cap et position, hauteur de caméra (tools.CalibrationTool) ;\n- photo affichée : précision GPS vérifiée (precision.PrecisionChecker), inclinaison\n  automatique (autotilt.TiltChecker), axe de la séquence entre les photos voisines.\n\nLa page appelle les méthodes de App ; les résultats sont rendus en JSON (texte). Quand une\nlecture réseau ou un calcul aboutit après coup, App appelle notify() pour que la page se\nredessine.\n\"\"\"\n\nimport json\nimport math\nimport traceback\nfrom datetime import datetime\n\nimport web_host\nfrom core import (autotilt, buildings, calibration, capture, filters, measures, metadata, precision, roads, terrain,\n                  tools, triangulation)\n\nGROUND_MODES = (\"road\", \"width\", \"height\")  # mesures par lancer de rayon (voir core/measures.py)\nCALIBRATION_MODES = (\"tilt\", \"heading\", \"camera\")\nMODES = GROUND_MODES + (\"tri\",) + CALIBRATION_MODES\n\n\nclass WebItem:\n    \"\"\"Dessin d'une mesure ou d'une façade sur la carte (voir measures.MeasureTool.new_item) :\n    gardé ici, rendu en GeoJSON par App.map_geojson.\"\"\"\n\n    def __init__(self, wall=False):\n        self.wall = wall\n        self.points, self.label, self.extras = [], \"\", []\n        self.removed = False\n\n    def set_data(self, points, label=\"\", extras=None):\n        self.points, self.label, self.extras = list(points), label, list(extras or [])\n\n    def remove(self):\n        self.removed = True\n\n\nclass RaysItem:\n    \"\"\"Visées sur la carte (triangulation, repères du calage du cap) : voir\n    tools.Triangulator.new_item.\"\"\"\n\n    def __init__(self):\n        self.rays, self.point = [], None\n        self.removed = False\n\n    def set_data(self, rays, point):\n        self.rays, self.point = list(rays), point\n\n    def remove(self):\n        self.removed = True\n\n\nclass App:\n    def __init__(self, notify, remote=None, api_url=web_host.API_URL):\n        web_host.install(remote, api_url)\n        if remote is not None:\n            autotilt.HAS_NUMPY = True  # verticales calculées dans le Pyodide d'arrière-plan, qui a numpy\n        self.notify = notify  # fonction de la page : redessiner après une lecture réseau\n        self.items, self.rays = [], []\n        self.calibration = calibration.Calibration()\n        self.terrain = terrain.TerrainProvider()\n        self.roads = roads.RoadAxisProvider()\n        self.buildings = buildings.BuildingProvider()\n        self.precision = precision.PrecisionChecker()\n        self.tilts = autotilt.TiltChecker()\n        self.roads.ready = self._roads_ready\n        self.buildings.ready = self._buildings_ready\n        self.tool = measures.MeasureTool(None)\n        self.tool.new_item = self._new_item\n        self.tool.calibration = self.calibration\n        self.tool.road_lookup = self.roads.lookup\n        self.tool.wall_lookup = self.buildings.lookup\n        self.triangulator = tools.Triangulator()\n        self.triangulator.new_item = self._new_rays\n        self.reference = (\"ground\", 5.0)  # calage de la hauteur de caméra : longueur connue\n        self.calibrator = tools.CalibrationTool(self.calibration, self.current_ids, lambda: self.reference)\n        self.calibrator.new_item = self._new_rays\n        self.mode = \"road\"\n        self.tool.set_mode(\"road\")\n        self.item = None  # fiche STAC de la photo affichée\n        self.quality = None  # vérification de sa précision (voir precision.PrecisionChecker)\n        self.neighbours = {}  # fiches des photos voisines (axe de la séquence) : id -> fiche\n        self.photo_filter = filters.PhotoFilter()\n        self.message = \"\"\n        self.new_camera = None  # hauteur de caméra calée, à reporter dans le réglage de la page\n        self.points = []  # points triangulés gardés : (lon, lat, attributs)\n        self.links = []  # distances entre deux points gardés : (n° du premier, n° du second, attributs)\n        self._handles = []  # clés des poignées de la carte, dans l'ordre de handles()\n        self.calibration_version = 0  # augmente à chaque changement du calage (à enregistrer)\n        self.active = False  # bouton « Mesure » de la page : clics dans la photo pour mesurer\n        self.epoch = 0  # change quand les clics en cours sont abandonnés (profil arrivé trop tard)\n\n    # Dessin --------------------------------------------------------------------------\n    def _new_item(self, wall=False):\n        item = WebItem(wall)\n        self.items.append(item)\n        return item\n\n    def _new_rays(self):\n        item = RaysItem()\n        self.rays.append(item)\n        return item\n\n    def current_ids(self):\n        item = self.item or {}\n        return item.get(\"id\"), item.get(\"collection\")\n\n    def _active(self):\n        \"\"\"Outil du mode : MeasureTool, Triangulator ou CalibrationTool.\"\"\"\n        if self.mode == \"tri\":\n            return self.triangulator\n        if self.mode in CALIBRATION_MODES:\n            if self.calibrator.mode != self.mode:\n                self.calibrator.set_mode(self.mode)\n            return self.calibrator\n        self.tool.set_mode(self.mode)\n        return self.tool\n\n    def _calibration_changed(self):\n        self.calibration_version += 1\n\n    # Réglages ------------------------------------------------------------------------\n    def set_active(self, on):\n        \"\"\"Bouton « Mesure » : activé, les clics dans la photo mesurent et l'inclinaison de la\n        photo est calculée ; désactivé, les mesures en cours sont terminées (les mesures réussies\n        restent affichées), comme dans le plugin.\"\"\"\n        self.active = bool(on)\n        self.message = \"\"\n        if self.active:\n            self._check_tilt()\n        else:\n            self._clear_measures()\n        return self.status()\n\n    def _check_tilt(self):\n        \"\"\"Inclinaison automatique de la photo affichée, en mesure ou en calage seulement : la\n        triangulation ne vise qu'en cap, elle n'en a pas besoin (calcul long évité).\"\"\"\n        if self.active and self.item and self.mode != \"tri\":\n            pic = self.item.get(\"id\")\n            self.tilts.check(self.item, self.calibration, lambda: self._on_tilt(pic))\n\n    def set_mode(self, mode):\n        if mode not in MODES:\n            return self.status()\n        self._clear_measures()\n        self.mode = mode\n        self.message = \"\"\n        self._active()\n        self._check_tilt()  # en quittant la triangulation\n        return self.status()\n\n    def _clear_measures(self):\n        \"\"\"Termine les mesures en cours (réussies, elles restent affichées) ; le calage déjà\n        fait est conservé (comme le plugin à un changement de mode).\"\"\"\n        self.epoch += 1\n        self.triangulator.clear()\n        self.tool.finish()\n        self.calibrator.reset()\n\n    def set_camera_height(self, value):\n        self.tool.set_camera_height(float(value))\n        return self.status()\n\n    def set_use_wall(self, value):\n        self.tool.set_use_wall(bool(value))\n        return self.status()\n\n    def set_bridge(self, value):\n        \"\"\"« Mesure sur un pont » : sol plat sous la caméra ; les profils déjà lus ne valent plus.\"\"\"\n        self.terrain.bridge = bool(value)\n        self.epoch += 1\n        self.tool.clear()\n        self.calibrator.reset()\n        self.message = \"\"\n        return self.status()\n\n    def set_reference(self, kind, length):\n        \"\"\"Référence du calage de la hauteur de caméra : \"ground\" (longueur au sol) ou \"height\"\n        (hauteur d'un objet), en m.\"\"\"\n        self.reference = (\"height\" if kind == \"height\" else \"ground\", float(length))\n        if self.mode == \"camera\":\n            self.calibrator.reset()  # clics en attente faits pour l'ancienne référence\n        return self.status()\n\n    def set_api_url(self, url):\n        \"\"\"Instance Panoramax choisie : recherches du cœur (précision GPS, trajectoire).\"\"\"\n        web_host.host.api_url = url\n        self.neighbours = {}\n\n    def set_filter(self, text):\n        \"\"\"Filtre des photos (JSON : since, kind, max_gps, producer [id, nom]).\"\"\"\n        data = json.loads(text) if text else {}\n        producer = data.get(\"producer\")\n        self.photo_filter = filters.PhotoFilter(data.get(\"since\") or None, data.get(\"kind\") or None,\n                                                data.get(\"max_gps\"), tuple(producer) if producer else None)\n\n    def filter_matches(self, item_json):\n        return self.photo_filter.matches(json.loads(item_json))\n\n    def filter_text(self):\n        return self.photo_filter.describe()\n\n    def producer(self):\n        \"\"\"Producteur de la photo affichée (JSON [id, nom] ou null).\"\"\"\n        p = filters.item_producer(self.item)\n        return json.dumps(list(p) if p else None)\n\n    # Photo affichée ------------------------------------------------------------------\n    def set_picture(self, item_json):\n        \"\"\"Photo affichée dans la visionneuse : sa fiche STAC (texte JSON).\"\"\"\n        item = json.loads(item_json)\n        self.item = item\n        pic = item.get(\"id\")\n        self.quality = self.precision.known(item)\n        self.precision.check(item, lambda res: self._on_precision(pic, res))\n        for rel in (\"prev\", \"next\"):  # voisines : axe de la séquence\n            nid = metadata.id_from_href(metadata.item_link(item, rel))\n            if nid and nid not in self.neighbours:\n                web_host.fetch_json(\"{}/search?ids={}\".format(web_host.host.api_url, nid),\n                                    lambda data, error, nid=nid: self._on_neighbour(nid, data))\n        self._check_tilt()\n        return self.status()\n\n    def _on_neighbour(self, nid, data):\n        features = (data or {}).get(\"features\") or []\n        if features:\n            self.neighbours[nid] = features[0]\n            if len(self.neighbours) > 200:\n                self.neighbours.pop(next(iter(self.neighbours)))\n\n    def _axis(self, item):\n        def neighbour(rel):\n            return self.neighbours.get(metadata.id_from_href(metadata.item_link(item, rel)))\n        return metadata.sequence_axis(item, neighbour(\"prev\"), neighbour(\"next\"))\n\n    def _on_precision(self, pic, res):\n        if pic != (self.item or {}).get(\"id\"):\n            return  # photo déjà quittée\n        self.quality = res\n        self.notify()\n\n    def _on_tilt(self, pic):\n        \"\"\"Inclinaison automatique arrivée : clics déjà faits sur la photo corrigés.\"\"\"\n        self._calibration_changed()\n        cal = self.calibration\n\n        def correct(c):\n            gps = c.get(\"gps\") or [None, None]\n            return cal.correct(pic, c.get(\"sequence\"), c[\"raw\"][0], c[\"raw\"][1], gps[0], gps[1])\n\n        try:\n            self.tool.recorrect(pic, correct)\n        except Exception:\n            traceback.print_exc()\n        self.notify()\n\n    def _heading(self):\n        \"\"\"Cap du centre de l'image (degrés) : EXIF précis, sinon view:azimuth.\"\"\"\n        precise = metadata.precise_heading(self.item)\n        return precise if precise is not None else (metadata.item_heading(self.item) or 0.0)\n\n    # Clics -------------------------------------------------------------------------------\n    def click(self, yaw, pitch):\n        \"\"\"Clic dans la photo affichée : direction dans le repère de la photo (radians, cap\n        relatif au centre de l'image, comme le donne la visionneuse).\"\"\"\n        if not self.active:\n            return self.status()\n        if not self.item:\n            self.message = \"Photo en cours de chargement : cliquez à nouveau.\"\n            return self.status()\n        if self.mode == \"tri\":\n            self.message = \"Triangulation : placez le réticule sur l'objet puis « Viser ».\"\n            return self.status()\n        raw_yaw = (math.degrees(yaw) + self._heading()) % 360\n        click = tools.photo_click(self.item, raw_yaw, math.degrees(pitch), self.calibration, self.quality,\n                                  [yaw, pitch], self._axis(self.item))\n        if click is None:\n            self.message = \"Position de la photo inconnue.\"\n            return self.status()\n        self.message = \"\"\n        tool = self._active()\n        if tool is self.tool and tool.select_near(click):\n            return self.status()  # repère d'un point : sélectionné pour le viser à nouveau\n        if not tool.needs_profile():\n            tool.add_click(click)  # sommet d'un objet ou calage : pas de terrain\n            self._after_calibration(tool)\n            return self.status()\n        self.message = \"Altitude du terrain le long de la visée…\"\n        epoch = self.epoch\n        self.terrain.profile(click[\"lon\"], click[\"lat\"], click[\"yaw\"],\n                             lambda profile, label, warning: self._profiled(epoch, tool, click, profile, label,\n                                                                            warning))\n        return self.status()\n\n    def _profiled(self, epoch, tool, click, profile, label, warning):\n        if epoch != self.epoch:\n            return  # mode changé, mesure effacée ou désactivée entre-temps : clic abandonné\n        try:\n            click.update(profile=profile, terrain=label, precise_ground=label in terrain.PRECISE_LABELS)\n            tool.add_click(click, warning)\n            self.message = \"\"  # la mesure en cours dit la suite (status)\n            self._after_calibration(tool)\n        except Exception:\n            traceback.print_exc()\n        self.notify()\n\n    def _after_calibration(self, tool):\n        if tool is not self.calibrator:\n            return\n        self._calibration_changed()\n        if tool.new_camera is not None:\n            self.new_camera, tool.new_camera = tool.new_camera, None\n\n    def take_camera_height(self):\n        \"\"\"Hauteur de caméra juste calée (à reporter dans le réglage « Caméra à »), ou None.\"\"\"\n        height, self.new_camera = self.new_camera, None\n        return height\n\n    def waiting_map(self):\n        \"\"\"Calage du cap : le repère cliqué dans la photo attend son clic sur la carte.\"\"\"\n        return self.mode == \"heading\" and self.calibrator.waiting_map()\n\n    def map_click(self, lon, lat):\n        \"\"\"Clic sur la carte pendant le calage du cap : le repère. Retourne True s'il a servi.\"\"\"\n        if not self.waiting_map():\n            return False\n        self.calibrator.add_map_point(float(lon), float(lat))\n        self._calibration_changed()\n        return True\n\n    def cancel_landmark(self):\n        self.calibrator.reset()\n        return self.status()\n\n    def aim(self, yaw, pitch):\n        \"\"\"Triangulation : visée du centre de la vue (radians, dans le repère de la photo).\"\"\"\n        if not self.active:\n            return self.status()\n        if not self.item:\n            self.message = \"Aucune photo affichée : impossible de viser.\"\n            return self.status()\n        sighting = tools.photo_sighting(self.item, (math.degrees(yaw) + self._heading()) % 360,\n                                        math.degrees(pitch), self.calibration, self.quality)\n        if sighting is None:\n            self.message = \"Position de la photo inconnue : impossible de viser.\"\n            return self.status()\n        self.message = \"\"\n        self.triangulator.add(sighting)\n        return self.status()\n\n    def keep_point(self):\n        \"\"\"Garde le point triangulé (exporté avec les mesures), puis repart de zéro.\"\"\"\n        values = self.triangulator.attributes()\n        if values is None:\n            self.message = self.triangulator.error or \"Il faut au moins deux visées qui se croisent.\"\n            return self.status()\n        r = self.triangulator.result\n        values[\"commentaire\"] = \"\"\n        self.points.append((r[\"lon\"], r[\"lat\"], values))\n        self.triangulator.clear()\n        self.message = \"Point {} gardé (incertitude ±{} m) : il sera exporté avec les mesures.\".format(\n            len(self.points), measures._num(r[\"uncertainty\"]))\n        if len(self.points) >= 2:  # distance au point gardé précédent, aussitôt\n            self.message += \" \" + self._link_last()\n        return self.status()\n\n    def _link_last(self):\n        \"\"\"Distance horizontale entre les deux derniers points gardés (la triangulation donne\n        une position sur la carte), incertitude des deux points combinée, gardée comme une\n        mesure. Retourne le texte à afficher.\"\"\"\n        i, j = len(self.points) - 2, len(self.points) - 1\n        (lon1, lat1, v1), (lon2, lat2, v2) = self.points[i], self.points[j]\n        x, y = triangulation._local(lon2, lat2, lon1, lat1)\n        value, unc = math.hypot(x, y), math.hypot(v1[\"incert_m\"], v2[\"incert_m\"])\n        self.links.append((i, j, {\"valeur_m\": round(value, 3), \"incert_m\": round(unc, 2), \"commentaire\": \"\"}))\n        return \"Distance entre les points {} et {} : {} m (±{} m).\".format(\n            i + 1, j + 1, measures._num(value, 2), measures._num(unc, 2))\n\n    def move_handle(self, index, lon, lat):\n        \"\"\"Poignée n° index (voir handles) glissée sur la carte en (lon, lat).\"\"\"\n        if not 0 <= index < len(self._handles):\n            return self.status()\n        try:\n            self.message = self.tool.move_handle(self._handles[index], float(lon), float(lat))\n        except Exception:\n            traceback.print_exc()\n            self.message = \"Recalage impossible.\"\n        return self.status()\n\n    def clear(self):\n        \"\"\"« Effacer » : sélection d'un point, mesure en cours, visées, ou calage du mode.\"\"\"\n        self.message = \"\"\n        tool = self._active()\n        if tool is self.tool and tool.cancel_selection():\n            return self.status()\n        self.epoch += 1\n        tool.clear()\n        if tool is self.calibrator:\n            self._calibration_changed()\n        return self.status()\n\n    def clear_all(self):\n        self.epoch += 1\n        self.triangulator.clear()\n        self.tool.clear_all()\n        self.calibrator.reset()\n        self.points, self.links = [], []\n        self.message = \"\"\n        return self.status()\n\n    def _roads_ready(self):\n        if self.tool.recompute_roads():\n            self.notify()\n\n    def _buildings_ready(self):\n        self.tool.recompute_walls()\n        self.notify()\n\n    # Calage enregistré ---------------------------------------------------------------\n    def calibration_json(self):\n        return json.dumps(self.calibration.to_dict(), separators=(\",\", \":\"))\n\n    def load_calibration(self, text):\n        \"\"\"Calage enregistré dans le navigateur : remplace celui en mémoire. Retourne False\n        s'il est illisible.\"\"\"\n        try:\n            data = json.loads(text) if text else None\n        except ValueError:\n            return False\n        self.calibration.load(data)\n        return True\n\n    def merge_calibration(self, text):\n        \"\"\"Calage d'un fichier : complète celui en mémoire. Retourne le nombre de photos ou\n        séquences ajoutées, ou -1 si le fichier est illisible.\"\"\"\n        try:\n            added = self.calibration.merge(json.loads(text))\n        except (ValueError, TypeError, AttributeError):\n            return -1\n        if added:\n            self._calibration_changed()\n        return added\n\n    # Affichage -----------------------------------------------------------------------\n    def status(self):\n        \"\"\"Texte de la mesure (consigne ou résultat).\"\"\"\n        if not self.active:\n            return self.message or \"Cliquez « 📐 Mesure » pour mesurer dans la photo ou la caler.\"\n        return self.message or self._active().status()\n\n    def state(self):\n        \"\"\"État de la photo affichée (JSON) : ligne de qualité, calage, hauteur de caméra\n        proposée, raisons du mode dégradé…\"\"\"\n        item, pic = self.item, (self.item or {}).get(\"id\")\n        lon = lat = None\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            pass\n        suggestion = precision.camera_suggestion(self.quality) if item else None\n        tilt = tools.tilt_state(self.calibration, pic, bool(pic) and self.tilts.pending(pic))\n        sequence = (item or {}).get(\"collection\")\n        return json.dumps({\n            \"quality\": precision.state_text(self.quality, metadata.item_accuracy(item), tilt) if item else \"\",\n            \"calibration\": tools.calibration_text(self.calibration, pic, sequence, lon, lat) if item else \"\",\n            \"camera\": [round(suggestion[0], 2), suggestion[1]] if suggestion else None,\n            \"degraded\": precision.degraded_reasons(self.quality) if precision.degraded(self.quality) else [],\n            \"advice\": precision.DEGRADED_ADVICE,\n            \"waiting_map\": self.waiting_map(),\n            \"point\": self.triangulator.result is not None,\n            \"active\": self.active,\n            \"lights\": self._lights(pic) if item else [],\n        })\n\n    def _lights(self, pic):\n        \"\"\"Voyants de la visionneuse : [(nom, état)], état « ok », « non » ou « attente ».\"\"\"\n        res = self.quality\n\n        def light(value):\n            return \"attente\" if value is None else (\"ok\" if value else \"non\")\n\n        if self.calibration.tilt(pic):\n            tilt = \"ok\"\n        else:\n            tilt = \"attente\" if self.tilts.pending(pic) else \"non\"\n        return [(\"RTK\", light(res[\"precise\"] if res else None)),\n                (\"LiDAR HD\", light(res[\"lidar\"] if res else None)),\n                (\"Inclinaison\", tilt)]\n\n    def viewer_marks(self):\n        \"\"\"Repères de la photo affichée (JSON) : pour chaque mesure, points (cap et élévation\n        dans le repère de la photo, radians), libellé, point sélectionné.\"\"\"\n        pic = (self.item or {}).get(\"id\")\n        marks = self.tool.done_marks()\n        if self.active and self.mode in GROUND_MODES:  # mesure ou calage en cours\n            marks = marks + [self.tool.viewer_marks()]\n        elif self.active and self.mode in CALIBRATION_MODES:\n            marks = marks + [self.calibrator.viewer_marks()]\n        out = []\n        for m in marks:\n            points = [p for p in m[\"points\"] if p.get(\"pic\") == pic and p.get(\"yaw\") is not None]\n            if points:\n                out.append({\"points\": [[p[\"yaw\"], p[\"pitch\"], bool(p.get(\"sel\"))] for p in points],\n                            \"label\": m.get(\"label\", \"\"), \"beside\": m.get(\"beside\", False)})\n        return json.dumps(out)\n\n    def handles(self):\n        \"\"\"Poignées déplaçables sur la carte (JSON) : [[lon, lat, façade ?]], repérées par leur\n        rang pour move_handle. Seulement en mesure, comme dans le plugin.\"\"\"\n        handles = self.tool.handles() if self.active and self.mode in GROUND_MODES else []\n        self._handles = [key for key, _, _ in handles]\n        return json.dumps([[lon, lat, key[0] == \"facade\"] for key, lon, lat in handles])\n\n    def map_geojson(self):\n        \"\"\"Mesures, façades, visées et points triangulés à dessiner sur la carte (GeoJSON, texte).\"\"\"\n        features = []\n\n        def add(kind, geometry_type, coordinates, label=\"\", sublabel=\"\"):\n            properties = {\"kind\": kind, \"label\": label}\n            if sublabel:  # sous le trait, le long de celui-ci\n                properties[\"sublabel\"] = sublabel\n            features.append({\"type\": \"Feature\", \"properties\": properties,\n                             \"geometry\": {\"type\": geometry_type, \"coordinates\": coordinates}})\n\n        self.items = [i for i in self.items if not i.removed]\n        for item in self.items:\n            if not item.points:\n                continue\n            if item.wall or not item.extras:\n                if len(item.points) >= 2:\n                    add(\"facade\" if item.wall else \"mesure\", \"LineString\", [list(p) for p in item.points], item.label)\n            else:  # largeur perpendiculaire : plan perpendiculaire à la route, puis trait de la visionneuse\n                if len(item.points) >= 2:\n                    add(\"trace\", \"LineString\", [list(p) for p in item.points], sublabel=\"plan perpendiculaire\")\n                if len(item.extras) >= 2:\n                    add(\"mesure\", \"LineString\", [list(item.extras[0]), list(item.extras[-1])], item.label)\n            for p in ([] if item.wall else (item.extras if item.extras else item.points)):\n                add(\"point\", \"Point\", list(p))\n            for start, end in zip(item.points, item.extras):  # pointillés vers les bords cliqués\n                add(\"lien\", \"LineString\", [list(start), list(end)])\n            if len(item.points) == 1 and item.label:  # hauteur : étiquette au pied\n                add(\"etiquette\", \"Point\", list(item.points[0]), item.label)\n        self.rays = [r for r in self.rays if not r.removed]\n        for item in self.rays:\n            for lon, lat, elon, elat in item.rays:\n                add(\"visee\", \"LineString\", [[lon, lat], [elon, elat]])\n            if item.point:\n                add(\"cible\", \"Point\", list(item.point))\n        for lon, lat, values in self.points:\n            add(\"triangule\", \"Point\", [lon, lat], \"±{} m\".format(measures._num(values[\"incert_m\"], 2)))\n        for i, j, values in self.links:  # distance entre deux points gardés : trait rouge, comme une mesure\n            add(\"mesure\", \"LineString\", [list(self.points[i][:2]), list(self.points[j][:2])],\n                \"{} m\".format(measures._num(values[\"valeur_m\"], 2)))\n        return json.dumps({\"type\": \"FeatureCollection\", \"features\": features})\n\n    def results(self):\n        \"\"\"Mesures terminées et points gardés, pour la liste de la page (JSON).\"\"\"\n        out = [{\"id\": id(m), \"kind\": \"mesure\", \"text\": m.label(), \"comment\": getattr(m, \"comment\", \"\")}\n               for m in self.tool.measures() if m.result]\n        out += [{\"id\": i, \"kind\": \"point\", \"text\": \"Point triangulé {} ±{} m\".format(\n                    i + 1, measures._num(v[\"incert_m\"], 2)), \"comment\": v.get(\"commentaire\", \"\")}\n                for i, (_, _, v) in enumerate(self.points)]\n        out += [{\"id\": k, \"kind\": \"distance\", \"text\": \"↔ {} m ± {} m entre les points {} et {}\".format(\n                    measures._num(v[\"valeur_m\"], 2), measures._num(v[\"incert_m\"], 2), i + 1, j + 1),\n                 \"comment\": v.get(\"commentaire\", \"\")}\n                for k, (i, j, v) in enumerate(self.links)]\n        return json.dumps(out)\n\n    def delete_result(self, kind, ident):\n        \"\"\"Efface un résultat de la liste : mesure (et son dessin), point triangulé (et les\n        distances qui le relient ; les points suivants sont renumérotés) ou distance.\"\"\"\n        if kind == \"mesure\":\n            tool = self.tool\n            for m in tool.measures():\n                if id(m) == ident:\n                    if tool.selected is not None and tool.selected[0] is m:\n                        tool.selected = None\n                    m.remove()\n                    if m is tool.current:\n                        tool.current = None\n                    else:\n                        tool.done.remove(m)\n                    self.message = \"Mesure effacée.\"\n                    break\n        elif kind == \"point\" and 0 <= ident < len(self.points):\n            del self.points[ident]\n            self.links = [(i - (i > ident), j - (j > ident), v) for i, j, v in self.links if ident not in (i, j)]\n            self.message = \"Point triangulé effacé.\"\n        elif kind == \"distance\" and 0 <= ident < len(self.links):\n            del self.links[ident]\n            self.message = \"Distance effacée.\"\n        return self.status()\n\n    def set_comment(self, kind, ident, text):\n        \"\"\"Commentaire d'une mesure ou d'un point gardé (champ « commentaire » de l'export).\"\"\"\n        if kind == \"point\":\n            if 0 <= ident < len(self.points):\n                self.points[ident][2][\"commentaire\"] = text\n            return\n        if kind == \"distance\":\n            if 0 <= ident < len(self.links):\n                self.links[ident][2][\"commentaire\"] = text\n            return\n        for m in self.tool.measures():  # rangé sur la mesure : effacée, son commentaire disparaît avec elle\n            if id(m) == ident:\n                m.comment = text\n\n    # Export ------------------------------------------------------------------------------\n    def _records(self):\n        \"\"\"Mesures terminées et points triangulés : (géométrie [(lon, lat)], attributs), comme\n        les couches du plugin.\"\"\"\n        out = []\n        for m in self.tool.measures():\n            r = m.result\n            if not r:\n                continue\n            d = r[\"decomposition\"]\n            ends = r[\"points\"] if len(r[\"points\"]) >= 2 else r[\"picks\"]\n            height, source = self.tool.camera_info(m.clicks[0], measures._ground_z(m.clicks)[m.clicks[0].get(\"pic\")])\n\n            def num(value, digits=3):\n                return None if value is None else round(value, digits)\n\n            out.append((ends, {\n                \"type\": measures.KIND_NAMES[m.kind],\n                \"surface\": measures.SURFACE_NAMES.get(m.surface, m.surface),\n                \"valeur_m\": num(r[\"value\"]), \"incert_m\": num(r[\"uncertainty\"]),\n                \"horiz_m\": num(d[\"horizontal\"]), \"vert_m\": num(d[\"vertical\"]),\n                \"long_route_m\": num(d[\"along\"]), \"travers_m\": num(d[\"across\"]),\n                \"dist_photo_m\": num(max(r[\"ranges\"]), 1), \"camera_m\": num(height, 2),\n                \"camera_calee\": measures.CAMERA_SOURCES.get(source, 0),\n                \"terrain\": \" + \".join(sorted({c.get(\"terrain\") for c in m.clicks if c.get(\"terrain\")})),\n                \"axe_route\": m.axis_source if m.kind == \"road\" else None,\n                \"recales\": len(m.overrides),\n                \"photos\": \",\".join(dict.fromkeys(c.get(\"pic\") or \"\" for c in m.clicks)),\n                \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n                \"commentaire\": getattr(m, \"comment\", \"\"),\n            }))\n        for n, (lon, lat, values) in enumerate(self.points):\n            out.append(([(lon, lat)], dict({\"type\": \"point triangulé\", \"point\": n + 1}, **values)))\n        for i, j, values in self.links:\n            (lon1, lat1, v1), (lon2, lat2, v2) = self.points[i], self.points[j]\n            out.append(([(lon1, lat1), (lon2, lat2)], {\n                \"type\": \"distance entre points triangulés\", \"valeur_m\": values[\"valeur_m\"],\n                \"incert_m\": values[\"incert_m\"], \"horiz_m\": values[\"valeur_m\"], \"points\": \"{}-{}\".format(i + 1, j + 1),\n                \"photos\": \",\".join(dict.fromkeys(p for v in (v1, v2) for p in v.get(\"photos\", \"\").split(\",\") if p)),\n                \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n                \"commentaire\": values.get(\"commentaire\", \"\"),\n            }))\n        return out\n\n    def export_geojson(self):\n        features = [{\"type\": \"Feature\", \"properties\": attrs,\n                     \"geometry\": ({\"type\": \"LineString\", \"coordinates\": [list(p) for p in ends]} if len(ends) >= 2\n                                  else {\"type\": \"Point\", \"coordinates\": list(ends[0])})}\n                    for ends, attrs in self._records()]\n        return json.dumps({\"type\": \"FeatureCollection\", \"features\": features}, ensure_ascii=False, indent=1)\n\n    def export_csv(self):\n        \"\"\"CSV (séparateur point-virgule, virgule décimale : tableurs français), coordonnées\n        des extrémités en WGS 84 ; mesures et points triangulés dans le même tableau.\"\"\"\n        records = self._records()\n        if not records:\n            return \"\"\n        keys = list(dict.fromkeys(k for _, attrs in records for k in attrs))\n        rows = [\";\".join(keys + [\"lon1\", \"lat1\", \"lon2\", \"lat2\"])]\n        for ends, attrs in records:\n            a, b = ends[0], ends[-1]\n            values = [attrs.get(k) for k in keys] + [a[0], a[1], b[0], b[1]]\n            rows.append(\";\".join(_csv(v) for v in values))\n        return \"\\n\".join(rows) + \"\\n\"\n\n    def has_results(self):\n        return bool(self.points) or bool(self.links) or any(m.result for m in self.tool.measures())\n\n    # Captures --------------------------------------------------------------------------\n    def capture_args(self, yaw, pitch, vfov):\n        \"\"\"Paramètres de la capture HD de la vue (JSON), pour le Pyodide d'arrière-plan :\n        photo, cadrage (cap absolu, inclinaison, champ vertical, en degrés), redressement,\n        cartouche d'attribution, nom du fichier. \"\" sans photo HD.\"\"\"\n        item = self.item\n        href = (((item or {}).get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n        if not href:\n            return \"\"\n        props = item.get(\"properties\") or {}\n        fov = (props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\")\n        rounded = metadata.item_heading(item) or 0.0\n        heading = _view_heading(item, yaw)\n        tilt = self.calibration.tilt(item.get(\"id\")) if item.get(\"id\") else None\n        date = \"\".join(ch for ch in (props.get(\"datetime\") or \"\") if ch.isdigit())[:8] or \"sansdate\"\n        return json.dumps({\"href\": href, \"azimuth\": rounded, \"is360\": bool(fov and float(fov) >= 360),\n                           \"heading\": heading, \"pitch\": math.degrees(pitch), \"vfov\": float(vfov),\n                           \"photo_hfov\": float(fov) if fov else None,\n                           \"up\": list(tilt[\"up\"]) if tilt else None,  # vue redressée\n                           \"caption\": capture.caption_for(item, None),  # sans le cap\n                           \"name\": \"panoramax_{}_cap{:03.0f}_{}\".format(date, heading, (item.get(\"id\") or \"\")[:8])})\n\n    def caption(self, yaw):\n        \"\"\"Cartouche d'attribution de la vue (obligation des licences Panoramax) : auteur, date,\n        catégorie de la licence ; sans le cap (yaw, gardé pour la page, ne sert plus).\"\"\"\n        if not self.item:\n            return \"Panoramax\"\n        return capture.caption_for(self.item, None)\n\n\ndef _view_heading(item, yaw):\n    \"\"\"Cap (degrés) du centre de la vue : la visionneuse s'oriente sur view:azimuth.\"\"\"\n    return (math.degrees(yaw) + (metadata.item_heading(item) or 0.0)) % 360\n\n\ndef _csv(value):\n    if value is None:\n        return \"\"\n    if isinstance(value, float):\n        return repr(round(value, 7)).replace(\".\", \",\")\n    text = str(value)\n    return '\"' + text.replace('\"', '\"\"') + '\"' if any(c in text for c in ';\"\\n') else text\n",
 "web_host.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Services du navigateur pour le cœur de calcul (voir core/host.py), dans Pyodide.\n\n- Réseau : fetch du navigateur (pyodide.http.pyfetch), en tâche asyncio ; le rappel est\n  appelé à l'arrivée de la réponse, comme avec QgsNetworkAccessManager dans le plugin.\n- Altitude NGF : grille RAF20 de l'IGN (voir geoid.py), chargée par load_geoid.\n- Calculs lourds (inclinaison automatique, capture HD) : dans un second Pyodide, en\n  arrière-plan (Web Worker, voir src/calcul.js), qui décode aussi les photos (Pillow).\n\"\"\"\n\nimport asyncio\nimport json\nimport traceback\n\nfrom pyodide.ffi import to_js\nfrom pyodide.http import pyfetch\n\nimport geoid\nfrom core import host\n\nAPI_URL = \"https://api.panoramax.xyz/api\"\n# Service d'altimétrie de l'IGN : il refuse les rafales (HTTP 429). Ses requêtes partent une à\n# une, espacées, et un refus est retenté après une pause.\nTHROTTLED = \"data.geopf.fr/altimetrie/\"\nSPACING = 0.25  # s entre deux requêtes au service\nRETRIES = (1.0, 3.0)  # pauses (s) avant de retenter après un refus\n_throttle = None  # verrou des requêtes au service (créé dans la boucle asyncio)\n\n_local_run = host.run_task  # calcul sur place, sans arrière-plan (valeur par défaut du cœur)\n_geoid = None  # grille RAF20, une fois chargée\n_remote = None  # fonction JS (module, fonction, arguments) -> promesse du résultat (texte JSON)\n\n\nclass Reply:\n    \"\"\"Requête en cours : abort() l'abandonne sans appeler son rappel.\"\"\"\n\n    def __init__(self, task):\n        self.task = task\n\n    def abort(self):\n        self.task.cancel()\n\n\nasync def _fetch(url, timeout_ms):\n    request = pyfetch(url)\n    return await (asyncio.wait_for(request, timeout_ms / 1000.0) if timeout_ms else request)\n\n\nasync def _fetch_throttled(url, timeout_ms):\n    global _throttle\n    if _throttle is None:\n        _throttle = asyncio.Lock()\n    for pause in RETRIES + (None,):\n        async with _throttle:\n            response = await _fetch(url, timeout_ms)\n            await asyncio.sleep(SPACING)\n        if response.status != 429 or pause is None:\n            return response\n        await asyncio.sleep(pause)\n\n\nasync def _get(url, callback, as_json, timeout_ms):\n    try:\n        response = await (_fetch_throttled if THROTTLED in url else _fetch)(url, timeout_ms)\n        if not response.ok:\n            result = (None, \"HTTP {}\".format(response.status))\n        elif as_json:\n            result = (await response.json(), None)\n        else:\n            result = (await response.bytes(), None)\n    except asyncio.CancelledError:\n        return  # abandonnée (voir Reply.abort)\n    except asyncio.TimeoutError:\n        result = (None, \"pas de réponse en {:.0f} s\".format(timeout_ms / 1000.0))\n    except Exception as exc:  # réseau, CORS, JSON illisible\n        result = (None, str(exc) or exc.__class__.__name__)\n    try:\n        callback(*result)\n    except Exception:\n        traceback.print_exc()  # erreur du rappel : signalée dans la console, pas avalée\n\n\ndef fetch(url, callback, prefer_cache=False, timeout_ms=None):\n    return Reply(asyncio.ensure_future(_get(url, callback, False, timeout_ms)))\n\n\ndef fetch_json(url, callback, prefer_cache=False, timeout_ms=None):\n    return Reply(asyncio.ensure_future(_get(url, callback, True, timeout_ms)))\n\n\ndef ngf_altitude(lon, lat, ellipsoidal):\n    return geoid.ngf_altitude(_geoid, lon, lat, ellipsoidal)\n\n\nasync def _run(function, args, done):\n    try:\n        args = [to_js(a) if isinstance(a, (bytes, bytearray)) else a for a in args]\n        text = await _remote(function.__module__, function.__name__, to_js(args))\n        result = json.loads(text) if text else None\n    except Exception:\n        traceback.print_exc()\n        result = None\n    done(result)\n\n\ndef run_task(function, args, done):\n    \"\"\"function(*args) dans le Pyodide d'arrière-plan (fonction d'un module du cœur, arguments\n    et résultat simples : nombres, textes, octets, listes, dicts), puis done(résultat ou None).\"\"\"\n    if _remote is None:\n        _local_run(function, args, done)\n    else:\n        asyncio.ensure_future(_run(function, args, done))\n\n\nasync def load_geoid():\n    \"\"\"Charge la grille du géoïde (altitude NGF) ; sans elle, pas d'altitude GPS de la caméra.\"\"\"\n    global _geoid\n    try:\n        response = await pyfetch(geoid.URL)\n        if response.ok:\n            _geoid = geoid.Grid(await response.bytes())\n    except Exception:\n        traceback.print_exc()\n    return _geoid is not None\n\n\ndef install(remote=None, api_url=API_URL):\n    \"\"\"remote : exécution en arrière-plan (voir run_task), ou None (pas d'arrière-plan).\"\"\"\n    global _remote\n    _remote = remote\n    host.install(fetch=fetch, fetch_json=fetch_json, ngf_altitude=ngf_altitude, run_task=run_task,\n                 api_url=api_url)\n",
 "web_worker.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Calculs lourds de la page, dans un second Pyodide en arrière-plan (Web Worker, voir\nsrc/calcul.js) : la page reste fluide pendant l'analyse d'une photo HD.\n\n- call : fonction d'un module du cœur (inclinaison automatique : autotilt.estimate),\n  demandée par web_host.run_task ;\n- capture : capture HD de la vue (core/capture.py), en JPEG.\n\nLes photos sont décodées par Pillow : réduites dès le décodage (mise à l'échelle du JPEG),\ncomme QImageReader dans le plugin.\n\"\"\"\n\nimport base64\nimport importlib\nimport io\nimport json\n\nfrom core import host\n\ntry:\n    from pyodide.ffi import JsProxy\nexcept ImportError:  # hors du navigateur (essais)\n    JsProxy = ()\n\nCAPTURE_WIDTH = 6144  # largeur de travail de la photo source d'une capture (HD imajbox : 12 288)\n\n\ndef _open(data, width, gray=False):\n    \"\"\"Image Pillow réduite à environ `width` de large dès le décodage ; gray : décodée\n    directement en niveaux de gris (JPEG : luminance seule, plus rapide).\"\"\"\n    from PIL import Image\n\n    img = Image.open(io.BytesIO(_python(data)))\n    w, h = img.size\n    mode = \"L\" if gray else (img.mode if img.mode in (\"L\", \"RGB\") else \"RGB\")\n    if w > width or gray:\n        img.draft(mode, (min(width, w), round(min(width, w) * h / w)))\n    return img\n\n\ndef decode_band(data, width, elev_min, elev_max):\n    \"\"\"Voir core/host.py : photo équirectangulaire en niveaux de gris, réduite et rognée.\"\"\"\n    import numpy as np\n    from PIL import Image\n\n    try:\n        img = _open(data, width, gray=True)\n    except Exception:\n        return None\n    full_w, full_h = img.size\n    if full_w < 2 * full_h - 2:\n        return None  # pas une photo équirectangulaire\n    w = min(width, full_w)\n    h = round(w * full_h / full_w)\n    img = img.convert(\"L\")\n    if img.size != (w, h):\n        img = img.resize((w, h), Image.Resampling.BILINEAR)\n    row0, row1 = int((90 - elev_max) / 180 * h), int((90 - elev_min) / 180 * h)\n    band = np.asarray(img.crop((0, row0, w, row1)), dtype=np.float32)\n    return band, row0, h, w\n\n\ndef _python(value):\n    \"\"\"Valeur venue du navigateur en Python : octets (Uint8Array) en bytes, tableaux en listes.\"\"\"\n    if isinstance(value, JsProxy):\n        value = value.to_py()\n    return bytes(value) if isinstance(value, (memoryview, bytearray)) else value\n\n\ndef _plain(value):\n    \"\"\"Résultat converti en types JSON (numpy compris).\"\"\"\n    if isinstance(value, dict):\n        return {k: _plain(v) for k, v in value.items()}\n    if isinstance(value, (list, tuple)):\n        return [_plain(v) for v in value]\n    if hasattr(value, \"tolist\"):\n        return value.tolist()\n    return value\n\n\ndef call(module, name, args):\n    \"\"\"module.name(*args) ; résultat en texte JSON.\"\"\"\n    function = getattr(importlib.import_module(module), name)\n    args = [_python(a) for a in _python(args)]\n    return json.dumps(_plain(function(*args)))\n\n\ndef capture(data, azimuth, is360, heading, pitch, vfov, photo_hfov, up):\n    \"\"\"Capture HD de la vue (voir core/capture.py) : JPEG en base64, ou \"\" si la photo est\n    illisible. Les cartouches (attribution, localisation) sont ajoutés par la page, avec les\n    polices du navigateur (accents compris).\"\"\"\n    import numpy as np\n    from PIL import Image\n\n    from core import capture as calc\n\n    try:\n        img = _open(data, CAPTURE_WIDTH).convert(\"RGB\")\n    except Exception:\n        return \"\"\n    is360 = bool(is360) or img.size[0] >= 1.9 * img.size[1]\n    up = list(_python(up)) if up else None\n    out = calc.render_view(np.asarray(img), azimuth, is360, heading, pitch, vfov,\n                           None if is360 else photo_hfov, up=up)\n    view = Image.fromarray(np.clip(out, 0, 255).astype(np.uint8), \"RGB\")\n    buf = io.BytesIO()\n    view.save(buf, \"JPEG\", quality=92)\n    return base64.b64encode(buf.getvalue()).decode(\"ascii\")\n\n\nhost.install(decode_band=decode_band)\n"
};
